window.EMMAUS_SCRIPTURE_PREVIEWS={"source":{"label":"和合本（維基文庫 1919 用字版，神版）","url":"https://zh.wikisource.org/wiki/聖經_(和合本)","note":"維基文庫依 1919 年用字校訂；預覽與外連的 Bible.com 新標點和合本（CUNP-神）可能有文字差異。"},"passages":{"1CH 17:7-14":{"label":"歷代志上 17:7–14","verses":[{"number":7,"text":"現在你要告訴我僕人大衞說、萬軍之耶和華如此說、我從羊圈中將你召來、叫你不再跟從羊羣、立你作我民以色列的君．"},{"number":8,"text":"你無論往那裏去、我常與你同在、剪除你的一切仇敵．我必使你得大名、好像世上大大有名的人一樣。"},{"number":9,"text":"我必爲我民以色列選定一個地方、栽培他們、使他們住自己的地方、不再遷移．凶惡之子也不像從前擾害他們、"},{"number":10,"text":"並不像我命士師治理我民以色列的時候一樣．我必治服你的一切仇敵、並且我耶和華應許你、必爲你建立家室。"}],"total":8},"1CO 1:24":{"label":"哥林多前書 1:24","verses":[{"number":24,"text":"但在那蒙召的、無論是猶太人、希利尼人、基督總爲　神的能力、　神的智慧。"}],"total":1},"1CO 1:30":{"label":"哥林多前書 1:30","verses":[{"number":30,"text":"但你們得在基督耶穌裏、是本乎　神、　神又使他成爲我們的智慧、公義、聖潔、救贖．"}],"total":1},"1CO 5:7":{"label":"哥林多前書 5:7","verses":[{"number":7,"text":"你們旣是無酵的麵、應當把舊酵除淨、好使你們成爲新團．因爲我們逾越節的羔羊基督、已經被殺獻祭了。"}],"total":1},"1CO 5:7-8":{"label":"哥林多前書 5:7–8","verses":[{"number":7,"text":"你們旣是無酵的麵、應當把舊酵除淨、好使你們成爲新團．因爲我們逾越節的羔羊基督、已經被殺獻祭了。"},{"number":8,"text":"所以我們守這節不可用舊酵、也不可用惡毒邪惡的酵、只用誠實眞正的無酵餅。"}],"total":2},"1CO 10:1-4":{"label":"哥林多前書 10:1–4","verses":[{"number":1,"text":"弟兄們、我不願意你們不曉得、我們的祖宗從前都在雲下、都從海中經過．"},{"number":2,"text":"都在雲裏海裏受洗歸了摩西．"},{"number":3,"text":"並且都喫了一樣的靈食．"},{"number":4,"text":"也都喝了一樣的靈水．所喝的是出於隨着他們的靈磐石．那磐石就是基督。"}],"total":4},"1CO 10:1-6":{"label":"哥林多前書 10:1–6","verses":[{"number":1,"text":"弟兄們、我不願意你們不曉得、我們的祖宗從前都在雲下、都從海中經過．"},{"number":2,"text":"都在雲裏海裏受洗歸了摩西．"},{"number":3,"text":"並且都喫了一樣的靈食．"},{"number":4,"text":"也都喝了一樣的靈水．所喝的是出於隨着他們的靈磐石．那磐石就是基督。"}],"total":6},"1CO 15:3-4":{"label":"哥林多前書 15:3–4","verses":[{"number":3,"text":"我當日所領受又傳給你們的、第一、就是基督照聖經所說、爲我們的罪死了．"},{"number":4,"text":"而且埋葬了．又照聖經所說、第三天復活了．"}],"total":2},"1CO 15:20-23":{"label":"哥林多前書 15:20–23","verses":[{"number":20,"text":"但基督已經從死裏復活、成爲睡了之人初熟的果子。"},{"number":21,"text":"死旣是因一人而來、死人復活也是因一人而來。"},{"number":22,"text":"在亞當裏衆人都死了．照樣、在基督裏衆人也都要復活。"},{"number":23,"text":"但各人是按着自己的次序復活。初熟的果子是基督．以後在他來的時候、是那些屬基督的。"}],"total":4},"1CO 15:21-22":{"label":"哥林多前書 15:21–22","verses":[{"number":21,"text":"死旣是因一人而來、死人復活也是因一人而來。"},{"number":22,"text":"在亞當裏衆人都死了．照樣、在基督裏衆人也都要復活。"}],"total":2},"1CO 15:25":{"label":"哥林多前書 15:25","verses":[{"number":25,"text":"因爲基督必要作王、等　神把一切仇敵、都放在他的脚下。"}],"total":1},"1CO 15:27":{"label":"哥林多前書 15:27","verses":[{"number":27,"text":"因爲經上說、『　神叫萬物都服在他的脚下。』旣說萬物都服了他、明顯那叫萬物服他的不在其內了。"}],"total":1},"1CO 15:45-49":{"label":"哥林多前書 15:45–49","verses":[{"number":45,"text":"經上也是這樣記着說、『首先的人亞當、成了有靈的活人。』末後的亞當、成了叫人活的靈。"},{"number":46,"text":"但屬靈的不在先、屬血氣的在先．以後纔有屬靈的。"},{"number":47,"text":"頭一個人是出於地、乃屬土．第二個人是出於天。"},{"number":48,"text":"那屬土的怎樣、凡屬土的也就怎樣．屬天的怎樣、凡屬天的也就怎樣。"}],"total":5},"1CO 15:54":{"label":"哥林多前書 15:54","verses":[{"number":54,"text":"這必朽壞的、旣變成不朽壞的．這必死的、旣變成不死的．那時經上所記、死被得勝吞滅的話就應驗了。"}],"total":1},"1CO 15:54-57":{"label":"哥林多前書 15:54–57","verses":[{"number":54,"text":"這必朽壞的、旣變成不朽壞的．這必死的、旣變成不死的．那時經上所記、死被得勝吞滅的話就應驗了。"},{"number":55,"text":"死阿、你得勝的權勢在那裏．死阿、你的毒鈎在那裏．"},{"number":56,"text":"死的毒鈎就是罪．罪的權勢就是律法。"},{"number":57,"text":"感謝　神、使我們藉着我們的主耶穌基督得勝。"}],"total":4},"1JN 1:7":{"label":"約翰一書 1:7","verses":[{"number":7,"text":"我們若在光明中行、如同　神在光明中、就彼此相交、他兒子耶穌的血也洗淨我們一切的罪。"}],"total":1},"1JN 3:8":{"label":"約翰一書 3:8","verses":[{"number":8,"text":"犯罪的是屬魔鬼、因爲魔鬼從起初就犯罪。　神的兒子顯現出來、爲要除滅魔鬼的作爲。"}],"total":1},"1KI 8:10-21":{"label":"列王紀上 8:10–21","verses":[{"number":10,"text":"祭司從聖所出來的時候、有雲充滿耶和華的殿．"},{"number":11,"text":"甚至祭司不能站立供職、因爲耶和華的榮光充滿了殿。"},{"number":12,"text":"那時所羅門說、耶和華曾說、他必住在幽暗之處。"},{"number":13,"text":"我已經建造殿宇作你的居所、爲你永遠的住處。"}],"total":12},"1KI 10:1-10":{"label":"列王紀上 10:1–10","verses":[{"number":1,"text":"示巴女王聽見所羅門因耶和華之名所得的名聲、就來要用難解的話、試問所羅門。"},{"number":2,"text":"跟隨他到耶路撒冷的人甚多．又有駱駝馱着香料、寶石、和許多金子．他來見了所羅門王、就把心裏所有的、對所羅門都說出來。"},{"number":3,"text":"所羅門王將他所問的都答上了．沒有一句不明白、不能答的。"},{"number":4,"text":"示巴女王見所羅門大有智慧、和他所建造的宮室、"}],"total":10},"1KI 17:8-24":{"label":"列王紀上 17:8–24","verses":[{"number":8,"text":"耶和華的話臨到他、說、"},{"number":9,"text":"你起身往西頓的撒勒法去住在那裏．我已吩咐那裏的一個寡婦供養你。"},{"number":10,"text":"以利亞就起身往撒勒法去、到了城門、見有一個寡婦在那裏撿柴．以利亞呼叫他、說、求你用器皿取點水來給我喝。"},{"number":11,"text":"他去取水的時候、以利亞又呼叫他、說、也求你拿點餅來給我。"}],"total":17},"1KI 22:17":{"label":"列王紀上 22:17","verses":[{"number":17,"text":"米該雅說、我看見以色列衆民散在山上、如同沒有牧人的羊羣一般．耶和華說、這民沒有主人、他們可以平平安安的各歸各家去。"}],"total":1},"1PE 1:18-19":{"label":"彼得前書 1:18–19","verses":[{"number":18,"text":"知道你們得贖、脫去你們祖宗所傳流虛妄的行爲、不是憑着能壞的金銀等物．"},{"number":19,"text":"乃是憑着基督的寶血、如同無瑕疵無玷汚的羔羊之血．"}],"total":2},"1PE 2:2-4":{"label":"彼得前書 2:2–4","verses":[{"number":2,"text":"就要愛慕那純淨的靈奶、像纔生的嬰孩愛慕奶一樣、叫你們因此漸長、以致得救．"},{"number":3,"text":"你們若嘗過主恩的滋味、就必如此。"},{"number":4,"text":"主乃活石．固然是被人所棄的、卻是被　神所揀選所寶貴的．"}],"total":3},"1PE 2:4-7":{"label":"彼得前書 2:4–7","verses":[{"number":4,"text":"主乃活石．固然是被人所棄的、卻是被　神所揀選所寶貴的．"},{"number":5,"text":"你們來到主面前、也就像活石、被建造成爲靈宮、作聖潔的祭司、藉着耶穌基督奉獻　神所悅納的靈祭。"},{"number":6,"text":"因爲經上說、『看哪、我把所揀選所寶貴的房角石、安放在錫安．信靠他的人、必不至於羞愧。』"},{"number":7,"text":"所以他在你們信的人就爲寶貴、在那不信的人有話說、『匠人所棄的石頭、已作了房角的頭塊石頭。』"}],"total":4},"1PE 2:4-8":{"label":"彼得前書 2:4–8","verses":[{"number":4,"text":"主乃活石．固然是被人所棄的、卻是被　神所揀選所寶貴的．"},{"number":5,"text":"你們來到主面前、也就像活石、被建造成爲靈宮、作聖潔的祭司、藉着耶穌基督奉獻　神所悅納的靈祭。"},{"number":6,"text":"因爲經上說、『看哪、我把所揀選所寶貴的房角石、安放在錫安．信靠他的人、必不至於羞愧。』"},{"number":7,"text":"所以他在你們信的人就爲寶貴、在那不信的人有話說、『匠人所棄的石頭、已作了房角的頭塊石頭。』"}],"total":5},"1PE 2:4-10":{"label":"彼得前書 2:4–10","verses":[{"number":4,"text":"主乃活石．固然是被人所棄的、卻是被　神所揀選所寶貴的．"},{"number":5,"text":"你們來到主面前、也就像活石、被建造成爲靈宮、作聖潔的祭司、藉着耶穌基督奉獻　神所悅納的靈祭。"},{"number":6,"text":"因爲經上說、『看哪、我把所揀選所寶貴的房角石、安放在錫安．信靠他的人、必不至於羞愧。』"},{"number":7,"text":"所以他在你們信的人就爲寶貴、在那不信的人有話說、『匠人所棄的石頭、已作了房角的頭塊石頭。』"}],"total":7},"1PE 2:9-10":{"label":"彼得前書 2:9–10","verses":[{"number":9,"text":"惟有你們是被揀選的族類、是有君尊的祭司、是聖潔的國度、是屬　神的子民、要叫你們宣揚那召你們出黑暗入奇妙光明者的美德。"},{"number":10,"text":"你們從前算不得子民、現在卻作了　神的子民．從前未曾蒙憐恤、現在卻蒙了憐恤。"}],"total":2},"1PE 2:22-25":{"label":"彼得前書 2:22–25","verses":[{"number":22,"text":"他並沒有犯罪、口裏也沒有詭詐．"},{"number":23,"text":"他被罵不還口．受害不說威嚇的話．只將自己交託那按公義審判人的主．"},{"number":24,"text":"他被掛在木頭上親身擔當了我們的罪、使我們旣然在罪上死、就得以在義上活．因他受的鞭傷、你們便得了醫治。"},{"number":25,"text":"你們從前好像迷路的羊．如今卻歸到你們靈魂的牧人監督了。"}],"total":4},"1PE 2:23":{"label":"彼得前書 2:23","verses":[{"number":23,"text":"他被罵不還口．受害不說威嚇的話．只將自己交託那按公義審判人的主．"}],"total":1},"1PE 3:18-22":{"label":"彼得前書 3:18–22","verses":[{"number":18,"text":"因基督也曾一次爲罪受苦、就是義的代替不義的、爲要引我們到　神面前．按着肉體說他被治死．按着靈性說他復活了。"},{"number":19,"text":"他藉這靈、曾去傳道給那些在監獄裏的靈聽、"},{"number":20,"text":"就是那從前在挪亞豫備方舟、　神容忍等待的時候、不信從的人．當時進入方舟、藉着水得救的不多、只有八個人．"},{"number":21,"text":"這水所表明的洗禮、現在藉着耶穌基督復活．也拯救你們．這洗禮本不在乎除掉肉體的汚穢、只求在　神面前有無虧的良心。"}],"total":5},"1PE 5:4":{"label":"彼得前書 5:4","verses":[{"number":4,"text":"到了牧長顯現的時候、你們必得那永不衰殘的榮耀冠冕。"}],"total":1},"1SA 2:1-10":{"label":"撒母耳記上 2:1–10","verses":[{"number":1,"text":"哈拿禱告說、我的心因耶和華快樂．我的角因耶和華高舉．我的口向仇敵張開．我因耶和華的救恩歡欣。"},{"number":2,"text":"只有耶和華爲聖、除他以外沒有可比的、也沒有磐石像我們的　神。"},{"number":3,"text":"人不要誇口說驕傲的話、也不要出狂妄的言語、因耶和華是大有智識的　神、人的行爲被他衡量。"},{"number":4,"text":"勇士的弓都已折斷．跌倒的人以力量束腰。"}],"total":10},"1SA 2:35":{"label":"撒母耳記上 2:35","verses":[{"number":35,"text":"我要爲自己立一個忠心的祭司、他必照我的心意而行、我要爲他建立堅固的家、他必永遠行在我的受膏者面前。"}],"total":1},"1SA 16:1-13":{"label":"撒母耳記上 16:1–13","verses":[{"number":1,"text":"耶和華對撒母耳說、我旣厭棄掃羅作以色列的王、你爲他悲傷要到幾時呢．你將膏油盛滿了角、我差遣你往伯利恆人耶西那裏去、因爲我在他衆子之內、豫定一個作王的。"},{"number":2,"text":"撒母耳說、我怎能去呢、掃羅若聽見、必要殺我．耶和華說、你可以帶一隻牛犢去、就說、我來是要向耶和華獻祭。"},{"number":3,"text":"你要請耶西來喫祭肉、我就指示你所當行的事、我所指給你的人你要膏他。"},{"number":4,"text":"撒母耳就照耶和華的話去行．到了伯利恆、那城裏的長老都戰戰兢兢的出來迎接他、問他說、你是爲平安來的麼．"}],"total":13},"1SA 17:32-51":{"label":"撒母耳記上 17:32–51","verses":[{"number":32,"text":"大衞對掃羅說、人都不必因那非利士人膽怯．你的僕人要去與那非利士人戰鬬。"},{"number":33,"text":"掃羅對大衞說、你不能去與那非利士人戰鬬．因爲你年紀太輕、他自幼就作戰士。"},{"number":34,"text":"大衞對掃羅說、你僕人爲父親放羊．有時來了獅子、有時來了熊、從羣中啣一隻羊羔去。"},{"number":35,"text":"我就追趕他、擊打他、將羊羔從他口中救出來．他起來要害我、我就揪着他的鬍子、將他打死。"}],"total":20},"2CH 7:1-3":{"label":"歷代志下 7:1–3","verses":[{"number":1,"text":"所羅門祈禱已畢、就有火從天上降下來、燒盡燔祭和別的祭．耶和華的榮光充滿了殿．"},{"number":2,"text":"因耶和華的榮光充滿了耶和華殿、所以祭司不能進殿。"},{"number":3,"text":"那火降下、耶和華的榮光在殿上的時候、以色列衆人看見、就在鋪石地俯伏叩拜、稱謝耶和華說、耶和華本爲善、他的慈愛永遠長存。"}],"total":3},"2CO 3:7-18":{"label":"哥林多後書 3:7–18","verses":[{"number":7,"text":"那用字刻在石頭上屬死的職事、尚且有榮光、甚至以色列人因摩西面上的榮光、不能定睛看他的臉．這榮光原是漸漸退去的．"},{"number":8,"text":"何况那屬靈的職事、豈不更有榮光麼。"},{"number":9,"text":"若是定罪的職事有榮光、那稱義的職事、榮光就越發大了。"},{"number":10,"text":"那從前有榮光的、因這極大的榮光、就算不得有榮光了．"}],"total":12},"2CO 4:6":{"label":"哥林多後書 4:6","verses":[{"number":6,"text":"那吩咐光從黑暗裏照出來的　神、已經照在我們心裏、叫我們得知　神榮耀的光、顯在耶穌基督的面上。"}],"total":1},"2CO 6:1-2":{"label":"哥林多後書 6:1–2","verses":[{"number":1,"text":"我們與　神同工的、也勸你們、不可徒受他的恩典．"},{"number":2,"text":"因爲他說、『在悅納的時候、我應允了你．在拯救的日子、我搭救了你。』看哪、現在正是悅納的時候、現在正是拯救的日子。"}],"total":2},"2KI 5:1-14":{"label":"列王紀下 5:1–14","verses":[{"number":1,"text":"亞蘭王的元帥乃縵、在他主人面前爲尊爲大、因耶和華曾藉他使亞蘭人得勝．他又是大能的勇士、只是長了大痲瘋。"},{"number":2,"text":"先前亞蘭人成羣的出去、從以色列國擄了一個小女子．這女子就服事乃縵的妻。"},{"number":3,"text":"他對主母說、巴不得我主人去見撒瑪利亞的先知．必能治好他的大痲瘋。"},{"number":4,"text":"乃縵進去、告訴他主人說、以色列國的女子如此如此說。"}],"total":14},"2PE 3:13":{"label":"彼得後書 3:13","verses":[{"number":13,"text":"但我們照他的應許、盼望新天新地、有義居在其中。"}],"total":1},"2SA 5:2":{"label":"撒母耳記下 5:2","verses":[{"number":2,"text":"從前掃羅作我們王的時候、率領以色列人出入的是你．耶和華也曾應許你說、你必牧養我的民以色列、作以色列的君。"}],"total":1},"2SA 7:8-16":{"label":"撒母耳記下 7:8–16","verses":[{"number":8,"text":"現在你要告訴我僕人大衞說、萬軍之耶和華如此說、我從羊圈中將你召來、叫你不再跟從羊羣、立你作我民以色列的君。"},{"number":9,"text":"你無論往那裏去、我常與你同在、剪除你的一切仇敵．我必使你得大名、好像世上大大有名的人一樣。"},{"number":10,"text":"我必爲我民以色列選定一個地方、栽培他們、使他們住自己的地方、不再遷移．凶惡之子、也不像從前擾害他們．"},{"number":11,"text":"並不像我命士師治理我民以色列的時候一樣．我必使你安靖、不被一切仇敵擾亂．並且我耶和華應許你、必爲你建立家室。"}],"total":9},"2SA 15:30-31":{"label":"撒母耳記下 15:30–31","verses":[{"number":30,"text":"大衞蒙頭赤脚、上橄欖山、一面上、一面哭．跟隨他的人、也都蒙頭哭着上去。"},{"number":31,"text":"有人告訴大衞說、亞希多弗也在叛黨之中、隨從押沙龍。大衞禱告說、耶和華阿、求你使亞希多弗的計謀、變爲愚拙。"}],"total":2},"2SA 17:23":{"label":"撒母耳記下 17:23","verses":[{"number":23,"text":"亞希多弗見不依從他的計謀、就備上驢、歸回本城、到了家、留下遺言、便弔死了、葬在他父親的墳墓裏。"}],"total":1},"2SA 22:50":{"label":"撒母耳記下 22:50","verses":[{"number":50,"text":"耶和華阿、因此我要在外邦中稱謝你、歌頌你的名。"}],"total":1},"2TH 2:8":{"label":"帖撒羅尼迦後書 2:8","verses":[{"number":8,"text":"那時這不法的人、必顯露出來．主耶穌要用口中的氣滅絕他、用降臨的榮光廢掉他。"}],"total":1},"ACT 1:8":{"label":"使徒行傳 1:8","verses":[{"number":8,"text":"但聖靈降臨在你們身上、你們就必得着能力．並要在耶路撒冷、猶太全地、和撒瑪利亞、直到地極、作我的見證。"}],"total":1},"ACT 1:9-11":{"label":"使徒行傳 1:9–11","verses":[{"number":9,"text":"說了這話、他們正看的時候、他就被取上升、有一朶雲彩把他接去、便看不見他了。"},{"number":10,"text":"當他往上去、他們定睛望天的時候、忽然有兩個人、身穿白衣、站在旁邊、說、"},{"number":11,"text":"加利利人哪、你們爲甚麼站着望天呢．這離開你們被接升天的耶穌、你們見他怎樣往天上去、他還要怎樣來。"}],"total":3},"ACT 1:9-12":{"label":"使徒行傳 1:9–12","verses":[{"number":9,"text":"說了這話、他們正看的時候、他就被取上升、有一朶雲彩把他接去、便看不見他了。"},{"number":10,"text":"當他往上去、他們定睛望天的時候、忽然有兩個人、身穿白衣、站在旁邊、說、"},{"number":11,"text":"加利利人哪、你們爲甚麼站着望天呢．這離開你們被接升天的耶穌、你們見他怎樣往天上去、他還要怎樣來。"},{"number":12,"text":"有一座山名叫橄欖山、離耶路撒冷不遠、約有安息日可走的路程．當下門徒從那裏回耶路撒冷去。"}],"total":4},"ACT 1:16-20":{"label":"使徒行傳 1:16–20","verses":[{"number":16,"text":"弟兄們、聖靈藉大衞的口、在聖經上、豫言領人捉拿耶穌的猶大．這話是必須應驗的。"},{"number":17,"text":"他本來列在我們數中、並且在使徒的職任上得了一分。"},{"number":18,"text":"這人用他作惡的工價、買了一塊田、以後身子仆倒、肚腹崩裂、腸子都流出來。"},{"number":19,"text":"住在耶路撒冷的衆人都知道這事、所以按着他們那裏的話、給那塊田起名叫亞革大馬、就是血田的意思。"}],"total":5},"ACT 2:16-21":{"label":"使徒行傳 2:16–21","verses":[{"number":16,"text":"這正是先知約珥所說的．"},{"number":17,"text":"『　神說、在末後的日子、我要將我的靈澆灌凡有血氣的．你們的兒女要說豫言．你們的少年人要見異象．老年人要作異夢．"},{"number":18,"text":"在那些日子、我要將我的靈澆灌我的僕人和使女、他們就要說豫言。"},{"number":19,"text":"在天上我要顯出奇事、在地下我要顯出神蹟、有血、有火、有煙霧．"}],"total":6},"ACT 2:25-32":{"label":"使徒行傳 2:25–32","verses":[{"number":25,"text":"大衞指着他說、『我看見主常在我眼前、他在我右邊、叫我不至於搖動．"},{"number":26,"text":"所以我心裏歡喜、我的靈快樂．並且我的肉身要安居在指望中．"},{"number":27,"text":"因你必不將我的靈魂撇在陰間、也不叫你的聖者見朽壞。"},{"number":28,"text":"你已將生命的道路指示我、必叫我因見你的面、得着滿足的快樂。』"}],"total":8},"ACT 2:25-36":{"label":"使徒行傳 2:25–36","verses":[{"number":25,"text":"大衞指着他說、『我看見主常在我眼前、他在我右邊、叫我不至於搖動．"},{"number":26,"text":"所以我心裏歡喜、我的靈快樂．並且我的肉身要安居在指望中．"},{"number":27,"text":"因你必不將我的靈魂撇在陰間、也不叫你的聖者見朽壞。"},{"number":28,"text":"你已將生命的道路指示我、必叫我因見你的面、得着滿足的快樂。』"}],"total":12},"ACT 2:29-32":{"label":"使徒行傳 2:29–32","verses":[{"number":29,"text":"弟兄們、先祖大衞的事、我可以明明的對你們說、他死了、也葬埋了、並且他的墳墓、直到今日還在我們這裏。"},{"number":30,"text":"大衞旣是先知、又曉得　神曾向他起誓、要從他的後裔中、立一位坐在他的寶座上．"},{"number":31,"text":"就豫先看明這事、講論基督復活說、他的靈魂、不撇在陰間、他的肉身、也不見朽壞、"},{"number":32,"text":"這耶穌、　神已經叫他復活了、我們都爲這事作見證。"}],"total":4},"ACT 2:29-36":{"label":"使徒行傳 2:29–36","verses":[{"number":29,"text":"弟兄們、先祖大衞的事、我可以明明的對你們說、他死了、也葬埋了、並且他的墳墓、直到今日還在我們這裏。"},{"number":30,"text":"大衞旣是先知、又曉得　神曾向他起誓、要從他的後裔中、立一位坐在他的寶座上．"},{"number":31,"text":"就豫先看明這事、講論基督復活說、他的靈魂、不撇在陰間、他的肉身、也不見朽壞、"},{"number":32,"text":"這耶穌、　神已經叫他復活了、我們都爲這事作見證。"}],"total":8},"ACT 2:32-36":{"label":"使徒行傳 2:32–36","verses":[{"number":32,"text":"這耶穌、　神已經叫他復活了、我們都爲這事作見證。"},{"number":33,"text":"他旣被　神的右手高舉、又從父受了所應許的聖靈、就把你們所看見所聽見的、澆灌下來。"},{"number":34,"text":"大衞並沒有升到天上、但自己說、『主對我主說、你坐在我的右邊、"},{"number":35,"text":"等我使你仇敵作你的脚凳。』"}],"total":5},"ACT 2:33":{"label":"使徒行傳 2:33","verses":[{"number":33,"text":"他旣被　神的右手高舉、又從父受了所應許的聖靈、就把你們所看見所聽見的、澆灌下來。"}],"total":1},"ACT 2:33-36":{"label":"使徒行傳 2:33–36","verses":[{"number":33,"text":"他旣被　神的右手高舉、又從父受了所應許的聖靈、就把你們所看見所聽見的、澆灌下來。"},{"number":34,"text":"大衞並沒有升到天上、但自己說、『主對我主說、你坐在我的右邊、"},{"number":35,"text":"等我使你仇敵作你的脚凳。』"},{"number":36,"text":"故此、以色列全家當確實的知道、你們釘在十字架上的這位耶穌、　神已經立他爲主爲基督了。"}],"total":4},"ACT 3:22-26":{"label":"使徒行傳 3:22–26","verses":[{"number":22,"text":"摩西曾說、『主　神要從你們弟兄中間、給你們興起一位先知像我、凡他向你們所說的、你們都要聽從。"},{"number":23,"text":"凡不聽從那先知的、必要從民中全然滅絕。』"},{"number":24,"text":"從撒母耳以來的衆先知、凡說豫言的、也都說到這些日子。"},{"number":25,"text":"你們是先知的子孫、也承受　神與你們祖宗所立的約、就是對亞伯拉罕說、地上萬族、都要因你的後裔得福。"}],"total":5},"ACT 3:25-26":{"label":"使徒行傳 3:25–26","verses":[{"number":25,"text":"你們是先知的子孫、也承受　神與你們祖宗所立的約、就是對亞伯拉罕說、地上萬族、都要因你的後裔得福。"},{"number":26,"text":"神旣興起他的僕人、就先差他到你們這裏來、賜福給你們、叫你們各人回轉、離開罪惡。"}],"total":2},"ACT 4:10-12":{"label":"使徒行傳 4:10–12","verses":[{"number":10,"text":"你們衆人、和以色列百姓、都當知道、站在你們面前的這人得痊愈、是因你們所釘十字架、　神叫他從死裏復活的、拿撒勒人耶穌基督的名。"},{"number":11,"text":"他是你們匠人所棄的石頭、已成了房角的頭塊石頭。"},{"number":12,"text":"除他以外、別無拯救．因爲在天下人間、沒有賜下別的名、我們可以靠着得救。"}],"total":3},"ACT 4:25-28":{"label":"使徒行傳 4:25–28","verses":[{"number":25,"text":"你曾藉着聖靈、託你僕人我們祖宗大衞的口、說、『外邦爲甚麼爭鬧、萬民爲甚麼謀算虛妄的事．"},{"number":26,"text":"世上的君王一齊起來、臣宰也聚集、要敵擋主、並主的受膏者。』"},{"number":27,"text":"希律和本丟彼拉多、外邦人和以色列民、果然在這城裏聚集、要攻打你所膏的聖僕耶穌、"},{"number":28,"text":"成就你手和你意旨所豫定必有的事。"}],"total":4},"ACT 7:9-16":{"label":"使徒行傳 7:9–16","verses":[{"number":9,"text":"先祖嫉妒約瑟、把他賣到埃及去．　神卻與他同在、"},{"number":10,"text":"救他脫離一切苦難、又使他在埃及王法老面前、得恩典有智慧．法老就派他作埃及國的宰相兼管全家。"},{"number":11,"text":"後來埃及和迦南全地遭遇饑荒、大受艱難、我們的祖宗、就絕了糧。"},{"number":12,"text":"雅各聽見在埃及有糧、就打發我們的祖宗、初次往那裏去。"}],"total":8},"ACT 7:23-37":{"label":"使徒行傳 7:23–37","verses":[{"number":23,"text":"他將到四十歲、心中起意、去看望他的弟兄以色列人．"},{"number":24,"text":"到了那裏、見他們一個人受寃屈、就護庇他、爲那受欺壓的人報仇、打死了那埃及人。"},{"number":25,"text":"他以爲弟兄必明白　神是藉他的手搭救他們．他們卻不明白。"},{"number":26,"text":"第二天、遇見兩個以色列人爭鬬、就勸他們和睦、說、你們二位是弟兄、爲甚麼彼此欺負呢。"}],"total":15},"ACT 7:37":{"label":"使徒行傳 7:37","verses":[{"number":37,"text":"那曾對以色列人說、『　神要從你們弟兄中間、給你們興起一位先知像我的、』就是這位摩西。"}],"total":1},"ACT 7:51-52":{"label":"使徒行傳 7:51–52","verses":[{"number":51,"text":"你們這硬着頸項、心與耳未受割禮的人、常時抗拒聖靈．你們的祖宗怎樣、你們也怎樣。"},{"number":52,"text":"那一個先知、不是你們祖宗逼迫呢．他們也把豫先傳說那義者要來的人殺了．如今你們又把那義者賣了、殺了。"}],"total":2},"ACT 8:32-35":{"label":"使徒行傳 8:32–35","verses":[{"number":32,"text":"他所念的那段經、說、『他像羊被牽到宰殺之地、又像羊羔在剪毛的人手下無聲、他也是這樣不開口。"},{"number":33,"text":"他卑微的時候、人不按公義審判他．誰能述說他的世代、因爲他的生命從地上奪去。』"},{"number":34,"text":"太監對腓利說、請問、先知說這話、是指着誰、是指着自己呢、是指着別人呢。"},{"number":35,"text":"腓利就開口從這經上起、對他傳講耶穌。"}],"total":4},"ACT 13:21-23":{"label":"使徒行傳 13:21–23","verses":[{"number":21,"text":"後來他們求一個王、　神就將便雅憫支派中、基士的兒子掃羅、給他們作王四十年。"},{"number":22,"text":"旣廢了掃羅、就選立大衞作他們的王．又爲他作見證說、『我尋得耶西的兒子大衞、他是合我心意的人、凡事要遵行我的旨意。』"},{"number":23,"text":"從這人的後裔中、　神已經照着所應許的、爲以色列人立了一位救主、就是耶穌。"}],"total":3},"ACT 13:22-23":{"label":"使徒行傳 13:22–23","verses":[{"number":22,"text":"旣廢了掃羅、就選立大衞作他們的王．又爲他作見證說、『我尋得耶西的兒子大衞、他是合我心意的人、凡事要遵行我的旨意。』"},{"number":23,"text":"從這人的後裔中、　神已經照着所應許的、爲以色列人立了一位救主、就是耶穌。"}],"total":2},"ACT 13:32-33":{"label":"使徒行傳 13:32–33","verses":[{"number":32,"text":"我們也報好信息給你們、就是那應許祖宗的話、"},{"number":33,"text":"神已經向我們這作兒女的應驗、叫耶穌復活了．正如詩篇第二篇上記着說、『你是我的兒子、我今日生你。』"}],"total":2},"ACT 13:32-37":{"label":"使徒行傳 13:32–37","verses":[{"number":32,"text":"我們也報好信息給你們、就是那應許祖宗的話、"},{"number":33,"text":"神已經向我們這作兒女的應驗、叫耶穌復活了．正如詩篇第二篇上記着說、『你是我的兒子、我今日生你。』"},{"number":34,"text":"論到　神叫他從死裏復活、不再歸於朽壞、就這樣說、『我必將所應許大衞那聖潔可靠的恩典、賜給你們。』"},{"number":35,"text":"又有一篇上說、『你必不叫你的聖者見朽壞。』"}],"total":6},"ACT 13:35-37":{"label":"使徒行傳 13:35–37","verses":[{"number":35,"text":"又有一篇上說、『你必不叫你的聖者見朽壞。』"},{"number":36,"text":"大衞在世的時候、遵行了　神的旨意、就睡了、歸到他祖宗那裏、已見朽壞．"},{"number":37,"text":"惟獨　神所復活的、他並未見朽壞。"}],"total":3},"ACT 13:46-47":{"label":"使徒行傳 13:46–47","verses":[{"number":46,"text":"保羅和巴拿巴放膽說、　神的道先講給你們、原是應當的、只因你們棄絕這道、斷定自己不配得永生、我們就轉向外邦人去。"},{"number":47,"text":"因爲主曾這樣吩咐我們說、『我已經立你作外邦人的光、叫你施行救恩直到地極。』"}],"total":2},"ACT 13:47":{"label":"使徒行傳 13:47","verses":[{"number":47,"text":"因爲主曾這樣吩咐我們說、『我已經立你作外邦人的光、叫你施行救恩直到地極。』"}],"total":1},"ACT 15:13-18":{"label":"使徒行傳 15:13–18","verses":[{"number":13,"text":"他們住了聲、雅各就說、諸位弟兄、請聽我的話。"},{"number":14,"text":"方纔西門述說　神當初怎樣眷顧外邦人、從他們中間選取百姓歸於自己的名下。"},{"number":15,"text":"衆先知的話、也與這意思相合．"},{"number":16,"text":"正如經上所寫的、『此後我要回來、重新修造大衞倒塌的帳幕、把那破壞的、重新修造建立起來．"}],"total":6},"ACT 28:25-28":{"label":"使徒行傳 28:25–28","verses":[{"number":25,"text":"他們彼此不合、就散了．未散以先、保羅說了一句話、說、聖靈藉先知以賽亞、向你們祖宗所說的話、是不錯的。"},{"number":26,"text":"他說、『你去告訴這百姓說、你們聽是要聽見、卻不明白．看是要看見、卻不曉得．"},{"number":27,"text":"因爲這百姓、油蒙了心、耳朶發沉、眼睛閉着．恐怕眼睛看見、耳朶聽見、心裏明白、回轉過來、我就醫治他們。』"},{"number":28,"text":"所以你們當知道、　神這救恩、如今傳給外邦人、他們也必聽受。"}],"total":4},"AMO 9:11-12":{"label":"阿摩司書 9:11–12","verses":[{"number":11,"text":"到那日、我必建立大衞倒塌的帳幕、堵住其中的破口、把那破壞的建立起來、重新修造、像古時一樣．"},{"number":12,"text":"使以色列人得以東所餘剩的和所有稱爲我名下的國．此乃行這事的耶和華說的。"}],"total":2},"COL 1:15-17":{"label":"歌羅西書 1:15–17","verses":[{"number":15,"text":"愛子是那不能看見之　神的像、是首生的、在一切被造的以先．"},{"number":16,"text":"因爲萬有都是靠他造的、無論是天上的、地上的、能看見的、不能看見的、或是有位的、主治的、執政的、掌權的、一槪都是藉着他造的、又是爲他造的．"},{"number":17,"text":"他在萬有之先．萬有也靠他而立。"}],"total":3},"COL 2:16-17":{"label":"歌羅西書 2:16–17","verses":[{"number":16,"text":"所以不拘在飲食上、或節期、月朔、安息日、都不可讓人論斷你們．"},{"number":17,"text":"這些原是後事的影兒．那形體卻是基督。"}],"total":2},"DAN 2:34-35":{"label":"但以理書 2:34–35","verses":[{"number":34,"text":"你觀看、見有一塊非人手鑿出來的石頭、打在這像半鐵半泥的脚上、把脚砸碎、"},{"number":35,"text":"於是金、銀、銅、鐵、泥、都一同砸得粉碎、成如夏天禾塲上的糠粃、被風吹散、無處可尋．打碎這像的石頭、變成一座大山、充滿天下。"}],"total":2},"DAN 2:44-45":{"label":"但以理書 2:44–45","verses":[{"number":44,"text":"當那列王在位的時候、天上的　神必另立一國、永不敗壞、也不歸別國的人、卻要打碎滅絕那一切國、這國必存到永遠。"},{"number":45,"text":"你旣看見非人手鑿出來的一塊石頭、從山而出、打碎金、銀、銅、鐵、泥、那就是至大的　神把後來必有的事給王指明．這夢準是這樣、這講解也是確實的。"}],"total":2},"DAN 3:24-28":{"label":"但以理書 3:24–28","verses":[{"number":24,"text":"那時尼布甲尼撒王驚奇、急忙起來、對謀士說、我們捆起來扔在火裏的不是三個人麼．他們回答王說、王阿、是．"},{"number":25,"text":"王說、看哪、我見有四個人、並沒有捆綁、在火中遊行、也沒有受傷、那第四個的相貌、好像神子。"},{"number":26,"text":"於是尼布甲尼撒就近烈火窰門、說、至高　神的僕人沙得拉、米煞、亞伯尼歌出來、上這裏來罷．沙得拉、米煞、亞伯尼歌、就從火中出來了。"},{"number":27,"text":"那些總督、欽差、巡撫、和王的謀士、一同聚集看這三個人、見火無力傷他們的身體、頭髮也沒有燒焦、衣裳也沒有變色、並沒有火燎的氣味。"}],"total":5},"DAN 6:16-23":{"label":"但以理書 6:16–23","verses":[{"number":16,"text":"王下令、人就把但以理帶來、扔在獅子坑中．王對但以理說、你所常事奉的　神、他必救你。"},{"number":17,"text":"有人搬石頭放在坑口、王用自己的璽、和大臣的印、封閉那坑、使懲辦但以理的事、毫無更改。"},{"number":18,"text":"王回宮、終夜禁食、無人拿樂器到他面前．並且睡不着覺。"},{"number":19,"text":"次日黎明、王就起來、急忙往獅子坑那裏去、"}],"total":8},"DAN 7:9-14":{"label":"但以理書 7:9–14","verses":[{"number":9,"text":"我觀看、見有寶座設立、上頭坐着亙古常在者、他的衣服潔白如雪、頭髮如純淨的羊毛、寶座乃火燄、其輪乃烈火．"},{"number":10,"text":"從他面前有火像河發出、事奉他的有千千、在他面前侍立的有萬萬．他坐着要行審判、案卷都展開了。"},{"number":11,"text":"那時我觀看、見那獸因小角說誇大話的聲音被殺、身體損壞、扔在火中焚燒。"},{"number":12,"text":"其餘的獸、權柄都被奪去、生命卻仍存留、直到所定的時候和日期。"}],"total":6},"DAN 7:18-27":{"label":"但以理書 7:18–27","verses":[{"number":18,"text":"然而至高者的聖民、必要得國享受、直到永永遠遠。"},{"number":19,"text":"那時我願知道第四獸的眞情、他爲何與那三獸的眞情、大不相同、甚是可怕、有鐵牙銅爪、吞喫嚼碎、所剩下的用脚踐踏、"},{"number":20,"text":"頭有十角、和那另長的一角、在這角前有三角被他打落、這角有眼、有說誇大話的口、形狀強橫、過於他的同類。"},{"number":21,"text":"我觀看、見這角與聖民爭戰、勝了他們、"}],"total":10},"DAN 9:24-27":{"label":"但以理書 9:24–27","verses":[{"number":24,"text":"爲你本國之民、和你聖城、已經定了七十個七、要止住罪過、除淨罪惡、贖盡罪孽、引進永義、封住異象和豫言、並膏至聖者。"},{"number":25,"text":"你當知道、當明白、從出令重新建造耶路撒冷、直到有受膏君的時候、必有七個七、和六十二個七．正在艱難的時候、耶路撒冷城連街帶濠、都必重新建造。"},{"number":26,"text":"過了六十二個七、那受膏者必被剪除、一無所有、必有一王的民來毀滅這城、和聖所．至終必如洪水沖沒、必有爭戰．一直到底、荒涼的事已經定了。"},{"number":27,"text":"一七之內、他必與許多人堅定盟約、一七之半、他必使祭祀與供獻止息．那行毀壞可憎的如飛而來、並且有忿怒傾在那行毀壞的身上、直到所定的結局。"}],"total":4},"DAN 12:1-3":{"label":"但以理書 12:1–3","verses":[{"number":1,"text":"那時保佑你本國之民的天使長米迦勒、必站起來．並且有大艱難、從有國以來直到此時、沒有這樣的．你本國的民中、凡名錄在册上的、必得拯救。"},{"number":2,"text":"睡在塵埃中的、必有多人復醒．其中有得永生的、有受羞辱永遠被憎惡的。"},{"number":3,"text":"智慧人必發光、如同天上的光．那使多人歸義的、必發光如星、直到永永遠遠。"}],"total":3},"DEU 6:13-16":{"label":"申命記 6:13–16","verses":[{"number":13,"text":"你要敬畏耶和華你的　神、事奉他、指着他的名起誓。"},{"number":14,"text":"不可隨從別神、就是你們四圍國民的神．"},{"number":15,"text":"因爲在你們中間的耶和華你　神、是忌邪的　神．惟恐耶和華你　神的怒氣向你發作、就把你從地上除滅。"},{"number":16,"text":"你們不可試探耶和華你們的　神、像你們在瑪撒那樣試探他。"}],"total":4},"DEU 8:1-5":{"label":"申命記 8:1–5","verses":[{"number":1,"text":"我今日所吩咐的一切誡命、你們要謹守遵行、好叫你們存活、人數增多、且進去得耶和華向你們列祖起誓應許的那地。"},{"number":2,"text":"你也要記念耶和華你的　神在曠野引導你、這四十年、是要苦煉你、試驗你、要知道你心內如何、肯守他的誡命不肯。"},{"number":3,"text":"他苦煉你、任你飢餓、將你和你列祖所不認識的嗎哪賜給你喫、使你知道人活着、不是單靠食物、乃是靠耶和華口裏所出的一切話。"},{"number":4,"text":"這四十年、你的衣服沒有穿破、你的脚也沒有腫。"}],"total":5},"DEU 18:15-19":{"label":"申命記 18:15–19","verses":[{"number":15,"text":"耶和華你的　神要從你們弟兄中間、給你興起一位先知像我、你們要聽從他。"},{"number":16,"text":"正如你在何烈山大會的日子、求耶和華你　神一切的話說、求你不再叫我聽見耶和華我　神的聲音、也不再叫我看見這大火、免得我死亡。"},{"number":17,"text":"耶和華就對我說、他們所說的是。"},{"number":18,"text":"我必在他們弟兄中間、給他們興起一位先知像你、我要將當說的話傳給他、他要將我一切所吩咐的、都傳給他們。"}],"total":5},"DEU 21:22-23":{"label":"申命記 21:22–23","verses":[{"number":22,"text":"人若犯該死的罪、被治死了、你將他挂在木頭上。"},{"number":23,"text":"他的屍首不可留在木頭上過夜、必要當日將他葬埋、免得玷汚了耶和華你　神所賜你爲業之地．因爲被挂的人是在　神面前受咒詛的。"}],"total":2},"DEU 27:26":{"label":"申命記 27:26","verses":[{"number":26,"text":"不堅守遵行這律法言語的、必受咒詛．百姓都要說、阿們。"}],"total":1},"DEU 30:11-14":{"label":"申命記 30:11–14","verses":[{"number":11,"text":"我今日所吩咐你的誡命、不是你難行的、也不是離你遠的。"},{"number":12,"text":"不是在天上、使你說、誰替我們上天取下來、使我們聽見可以遵行呢．"},{"number":13,"text":"也不是在海外、使你說、誰替我們過海取了來、使我們聽見可以遵行呢。"},{"number":14,"text":"這話卻離你甚近、就在你口中、在你心裏、使你可以遵行。"}],"total":4},"DEU 32:43":{"label":"申命記 32:43","verses":[{"number":43,"text":"你們外邦人、當與主的百姓一同歡呼、因他要伸他僕人流血的寃、報應他的敵人、潔淨他的地、救贖他的百姓。"}],"total":1},"EPH 1:22":{"label":"以弗所書 1:22","verses":[{"number":22,"text":"又將萬有服在他的脚下、使他爲教會作萬有之首．"}],"total":1},"EPH 2:13-18":{"label":"以弗所書 2:13–18","verses":[{"number":13,"text":"你們從前遠離　神的人、如今卻在基督耶穌裏、靠着他的血、已經得親近了。"},{"number":14,"text":"因他使我們和睦、將兩下合而爲一、拆毀了中間隔斷的牆．"},{"number":15,"text":"而且以自己的身體、廢掉寃仇、就是那記在律法上的規條．爲要將兩下、藉着自己造成一個新人、如此便成就了和睦．"},{"number":16,"text":"旣在十字架上滅了寃仇、便藉這十字架、使兩下歸爲一體、與　神和好了．"}],"total":6},"EPH 4:7-13":{"label":"以弗所書 4:7–13","verses":[{"number":7,"text":"我們各人蒙恩、都是照基督所量給各人的恩賜。"},{"number":8,"text":"所以經上說、『他升上高天的時候、擄掠了仇敵、將各樣的恩賜賞給人。』"},{"number":9,"text":"（旣說升上、豈不是先降在地下麼．"},{"number":10,"text":"那降下的、就是遠升諸天之上要充滿萬有的。）"}],"total":7},"EPH 4:8-10":{"label":"以弗所書 4:8–10","verses":[{"number":8,"text":"所以經上說、『他升上高天的時候、擄掠了仇敵、將各樣的恩賜賞給人。』"},{"number":9,"text":"（旣說升上、豈不是先降在地下麼．"},{"number":10,"text":"那降下的、就是遠升諸天之上要充滿萬有的。）"}],"total":3},"EPH 5:2":{"label":"以弗所書 5:2","verses":[{"number":2,"text":"也要憑愛心行事、正如基督愛我們、爲我們捨了自己、當作馨香的供物、和祭物、獻與　神。"}],"total":1},"EPH 5:25-32":{"label":"以弗所書 5:25–32","verses":[{"number":25,"text":"你們作丈夫的、要愛你們的妻子、正如基督愛教會、爲教會捨己．"},{"number":26,"text":"要用水藉着道、把教會洗淨、成爲聖潔、"},{"number":27,"text":"可以獻給自己、作個榮耀的教會、毫無玷汚皺紋等類的病、乃是聖潔沒有瑕疵的。"},{"number":28,"text":"丈夫也當照樣愛妻子、如同愛自己的身子．愛妻子、便是愛自己了。"}],"total":8},"EST 4:13-16":{"label":"以斯帖記 4:13–16","verses":[{"number":13,"text":"末底改託人回覆以斯帖說、你莫想在王宮裏強過一切猶大人、得免這禍．"},{"number":14,"text":"此時你若閉口不言、猶大人必從別處得解脫、蒙拯救、你和你父家、必致滅亡．焉知你得了王后的位分、不是爲現今的機會麼。"},{"number":15,"text":"以斯帖就吩咐人回報末底改說、"},{"number":16,"text":"你當去招聚書珊城所有的猶大人、爲我禁食三晝三夜、不喫不喝．我和我的宮女、也要這樣禁食．然後我違例進去見王．我若死就死罷。"}],"total":4},"EST 7:1-6":{"label":"以斯帖記 7:1–6","verses":[{"number":1,"text":"王帶着哈曼來赴王后以斯帖的筵席．"},{"number":2,"text":"這第二次在酒席筵前、王又問以斯帖說、王后以斯帖阿、你要甚麼、我必賜給你、你求甚麼、就是國的一半、也必爲你成就。"},{"number":3,"text":"王后以斯帖回答說、我若在王眼前蒙恩、王若以爲美、我所願的、是願王將我的性命賜給我、我所求的、是求王將我的本族賜給我．"},{"number":4,"text":"因我和我的本族被賣了、要剪除殺戮滅絕我們．我們若被賣爲奴爲婢、我也閉口不言、但王的損失、敵人萬不能補足。"}],"total":6},"EXO 2:11-15":{"label":"出埃及記 2:11–15","verses":[{"number":11,"text":"後來摩西長大、他出去到他弟兄那裏、看他們的重擔、見一個埃及人打希伯來人的一個弟兄．"},{"number":12,"text":"他左右觀看、見沒有人、就把埃及人打死了、藏在沙土裏。"},{"number":13,"text":"第二天他出去見有兩個希伯來人爭鬬、就對那欺負人的說、你爲甚麼打你同族的人呢。"},{"number":14,"text":"那人說、誰立你作我們的首領和審判官呢、難道你要殺我、像殺那埃及人麼。摩西便懼怕、說、這事必是被人知道了。"}],"total":5},"EXO 3:1-15":{"label":"出埃及記 3:1–15","verses":[{"number":1,"text":"摩西牧養他岳父米甸祭司葉忒羅的羊羣、一日領羊羣往野外去、到了　神的山、就是何烈山。"},{"number":2,"text":"耶和華的使者從荊棘裏火燄中向摩西顯現．摩西觀看、不料、荊棘被火燒着、卻沒有燒燬。"},{"number":3,"text":"摩西說、我要過去看這大異象、這荊棘爲何沒有燒壞呢。"},{"number":4,"text":"耶和華　神見他過去要看、就從荊棘裏呼叫說、摩西、摩西．他說、我在這裏。"}],"total":15},"EXO 3:7-12":{"label":"出埃及記 3:7–12","verses":[{"number":7,"text":"耶和華說、我的百姓在埃及所受的困苦、我實在看見了．他們因受督工的轄制所發的哀聲、我也聽見了．我原知道他們的痛苦。"},{"number":8,"text":"我下來是要救他們脫離埃及人的手、領他們出了那地、到美好寬闊流奶與蜜之地、就是到迦南人、赫人、亞摩利人、比利洗人、希未人、耶布斯人之地。"},{"number":9,"text":"現在以色列人的哀聲達到我耳中、我也看見埃及人怎樣欺壓他們。"},{"number":10,"text":"故此我要打發你去見法老、使你可以將我的百姓以色列人從埃及領出來。"}],"total":6},"EXO 12:1-14":{"label":"出埃及記 12:1–14","verses":[{"number":1,"text":"耶和華在埃及地曉諭摩西亞倫說、"},{"number":2,"text":"你們要以本月爲正月、爲一年之首。"},{"number":3,"text":"你們吩咐以色列全會衆說、本月初十日、各人要按着父家取羊羔、一家一隻。"},{"number":4,"text":"若是一家的人太少、喫不了一隻羊羔、本人就要和他隔壁的鄰舍共取一隻、你們豫備羊羔、要按着人數和飯量計算。"}],"total":14},"EXO 12:21-28":{"label":"出埃及記 12:21–28","verses":[{"number":21,"text":"於是摩西召了以色列的衆長老來、對他們說、你們要按着家口取出羊羔、把這逾越節的羊羔宰了。"},{"number":22,"text":"拿一把牛膝草、蘸盆裏的血、打在門楣上、和左右的門框上．你們誰也不可出自己的房門直到早晨。"},{"number":23,"text":"因爲耶和華要巡行擊殺埃及人、他看見血在門楣上、和左右的門框上、就必越過那門、不容滅命的進你們的房屋、擊殺你們。"},{"number":24,"text":"這例你們要守着、作爲你們和你們子孫永遠的定例。"}],"total":8},"EXO 12:46":{"label":"出埃及記 12:46","verses":[{"number":46,"text":"應當在一個房子裏喫、不可把一點肉從房子裏帶到外頭去．羊羔的骨頭、一根也不可折斷。"}],"total":1},"EXO 13:1-2":{"label":"出埃及記 13:1–2","verses":[{"number":1,"text":"耶和華曉諭摩西說、"},{"number":2,"text":"以色列中凡頭生的、無論是人是牲畜、都是我的、要分別爲聖歸我。"}],"total":2},"EXO 13:11-16":{"label":"出埃及記 13:11–16","verses":[{"number":11,"text":"將來耶和華照他向你和你祖宗所起的誓、將你領進迦南人之地、把這地賜給你、"},{"number":12,"text":"那時你要將一切頭生的、並牲畜中頭生的、歸給耶和華．公的都要屬耶和華。"},{"number":13,"text":"凡頭生的驢、你要用羊羔代贖、若不代贖、就要打折他的頸項．凡你兒子中頭生的都要贖出來。"},{"number":14,"text":"日後、你的兒子問你說、這是甚麼意思、你就說、耶和華用大能的手將我們從埃及爲奴之家領出來。"}],"total":6},"EXO 14:21-31":{"label":"出埃及記 14:21–31","verses":[{"number":21,"text":"摩西向海伸杖、耶和華便用大東風、使海水一夜退去、水便分開、海就成了乾地。"},{"number":22,"text":"以色列人下海中走乾地、水在他們的左右作了牆垣。"},{"number":23,"text":"埃及人追趕他們、法老一切的馬匹、車輛、和馬兵、都跟着下到海中。"},{"number":24,"text":"到了晨更的時候、耶和華從雲火柱中向埃及的軍兵觀看、使埃及的軍兵混亂了。"}],"total":11},"EXO 16:1-18":{"label":"出埃及記 16:1–18","verses":[{"number":1,"text":"以色列全會衆從以琳起行、在出埃及後第二個月十五日、到了以琳和西乃中間、汛的曠野。"},{"number":2,"text":"以色列全會衆在曠野向摩西、亞倫發怨言、"},{"number":3,"text":"說、巴不得我們早死在埃及地耶和華的手下、那時我們坐在肉鍋旁邊、喫得飽足．你們將我們領出來、到這曠野、是要叫這全會衆都餓死阿。"},{"number":4,"text":"耶和華對摩西說、我要將糧食從天降給你們、百姓可以出去、每天收每天的分、我好試驗他們遵不遵我的法度。"}],"total":18},"EXO 17:1-7":{"label":"出埃及記 17:1–7","verses":[{"number":1,"text":"以色列全會衆都遵耶和華的吩咐、按着站口從汛的曠野往前行、在利非訂安營．百姓沒有水喝、"},{"number":2,"text":"所以與摩西爭鬧、說、給我們水喝罷。摩西對他們說、你們爲甚麼與我爭鬧、爲甚麼試探耶和華呢。"},{"number":3,"text":"百姓在那裏甚渴、要喝水、就向摩西發怨言、說、你爲甚麼將我們從埃及領出來、使我們和我們的兒女並牲畜、都渴死呢。"},{"number":4,"text":"摩西就呼求耶和華說、我向這百姓怎樣行呢、他們幾乎要拿石頭打死我。"}],"total":7},"EXO 19:5-6":{"label":"出埃及記 19:5–6","verses":[{"number":5,"text":"如今你們若實在聽從我的話、遵守我的約、就要在萬民中作屬我的子民、因爲全地都是我的．"},{"number":6,"text":"你們要歸我作祭司的國度、爲聖潔的國民．這些話你要告訴以色列人。"}],"total":2},"EXO 23:20":{"label":"出埃及記 23:20","verses":[{"number":20,"text":"看哪、我差遣使者在你前面、在路上保護你、領你到我所豫備的地方去。"}],"total":1},"EXO 24:3-8":{"label":"出埃及記 24:3–8","verses":[{"number":3,"text":"摩西下山、將耶和華的命令、典章、都述說與百姓聽．衆百姓齊聲說、耶和華所吩咐的、我們都必遵行。"},{"number":4,"text":"摩西將耶和華的命令都寫上、清早起來、在山下築一座壇、按以色列十二支派、立十二根柱子。"},{"number":5,"text":"又打發以色列人中的少年人去獻燔祭、又向耶和華獻牛爲平安祭。"},{"number":6,"text":"摩西將血一半盛在盆中、一半灑在壇上。"}],"total":6},"EXO 25:8-9":{"label":"出埃及記 25:8–9","verses":[{"number":8,"text":"又當爲我造聖所、使我可以住在他們中間。"},{"number":9,"text":"製造帳幕和其中的一切器具、都要照我所指示你的樣式。"}],"total":2},"EXO 25:17-22":{"label":"出埃及記 25:17–22","verses":[{"number":17,"text":"要用精金作施恩座、長二肘半、寬一肘半。"},{"number":18,"text":"要用金子錘出兩個基路伯來、安在施恩座的兩頭。"},{"number":19,"text":"這頭作一個基路伯、那頭作一個基路伯、二基路伯要接連一塊、在施恩座的兩頭。"},{"number":20,"text":"二基路伯要高張翅膀、遮掩施恩座．基路伯要臉對臉、朝着施恩座。"}],"total":6},"EXO 25:40":{"label":"出埃及記 25:40","verses":[{"number":40,"text":"要謹愼作這些物件、都要照着在山上指示你的樣式。"}],"total":1},"EXO 28:1-4":{"label":"出埃及記 28:1–4","verses":[{"number":1,"text":"你要從以色列人中使你的哥哥亞倫、和他的兒子拿答、亞比戶、以利亞撒、以他瑪、一同就近你、給我供祭司的職分。"},{"number":2,"text":"你要給你哥哥亞倫作聖衣爲榮耀、爲華美。"},{"number":3,"text":"又要吩咐一切心中有智慧的、就是我用智慧的靈所充滿的、給亞倫作衣服、使他分別爲聖、可以給我供祭司的職分。"},{"number":4,"text":"所要作的、就是胸牌、以弗得、外袍、雜色的內袍、冠冕、腰帶、使你哥哥亞倫和他兒子穿這聖服、可以給我供祭司的職分。"}],"total":4},"EXO 29:1-9":{"label":"出埃及記 29:1–9","verses":[{"number":1,"text":"你使亞倫和他兒子成聖、給我供祭司的職分、要如此行．取一隻公牛犢、兩隻無殘疾的公綿羊、"},{"number":2,"text":"無酵餅、和調油的無酵餅、與抹油的無酵薄餅．這都要用細麥麵作成。"},{"number":3,"text":"這餅要裝在一個筐子裏、連筐子帶來、又把公牛和兩隻公綿羊牽來。"},{"number":4,"text":"要使亞倫和他兒子到會幕門口來、用水洗身。"}],"total":9},"EXO 33:18-23":{"label":"出埃及記 33:18–23","verses":[{"number":18,"text":"摩西說、求你顯出你的榮耀給我看。"},{"number":19,"text":"耶和華說、我要顯我一切的恩慈、在你面前經過、宣告我的名．我要恩待誰、就恩待誰．要憐憫誰、就憐憫誰。"},{"number":20,"text":"又說、你不能看見我的面、因爲人見我的面不能存活。"},{"number":21,"text":"耶和華說、看哪、在我這裏有地方、你要站在磐石上．"}],"total":6},"EXO 34:5-9":{"label":"出埃及記 34:5–9","verses":[{"number":5,"text":"耶和華在雲中降臨、和摩西一同站在那裏、宣告耶和華的名。"},{"number":6,"text":"耶和華在他面前宣告說、耶和華、耶和華、是有憐憫、有恩典的　神、不輕易發怒、並有豐盛的慈愛和誠實。"},{"number":7,"text":"爲千萬人存留慈愛、赦免罪孽、過犯、和罪惡．萬不以有罪的爲無罪、必追討他的罪、自父及子、直到三四代。"},{"number":8,"text":"摩西急忙伏地下拜、"}],"total":5},"EXO 34:29-35":{"label":"出埃及記 34:29–35","verses":[{"number":29,"text":"摩西手裏拿着兩塊法版下、西乃山的時候、不知道自己的面皮、因耶和華和他說話就發了光。"},{"number":30,"text":"亞倫和以色列衆人看見摩西的面皮發光、就怕挨近他。"},{"number":31,"text":"摩西叫他們來、於是亞倫和會衆的官長都到他那裏去、摩西就與他們說話。"},{"number":32,"text":"隨後以色列衆人都近前來、他就把耶和華在西乃山與他所說的一切話、都吩咐他們。"}],"total":7},"EXO 40:34-38":{"label":"出埃及記 40:34–38","verses":[{"number":34,"text":"當時雲彩遮蓋會幕、耶和華的榮光就充滿了帳幕。"},{"number":35,"text":"摩西不能進會幕、因爲雲彩停在其上、並且耶和華的榮光、充滿了帳幕。"},{"number":36,"text":"每逢雲彩從帳幕收上去、以色列人就起程前往．"},{"number":37,"text":"雲彩若不收上去、他們就不起程、直等到雲彩收上去。"}],"total":5},"EZK 17:22-24":{"label":"以西結書 17:22–24","verses":[{"number":22,"text":"主耶和華如此說、我要將香柏樹梢擰去栽上、就是從儘尖的嫩枝中折一嫩枝、栽於極高的山上．"},{"number":23,"text":"在以色列高處的山栽上．他就生枝子、結果子、成爲佳美的香柏樹、各類飛鳥都必宿在其下、就是宿在枝子的蔭下。"},{"number":24,"text":"田野的樹木都必知道我耶和華使高樹矮小、矮樹高大、青樹枯乾、枯樹發旺．我耶和華如此說、也如此行了。"}],"total":3},"EZK 21:25-27":{"label":"以西結書 21:25–27","verses":[{"number":25,"text":"你這受死傷行惡的以色列王阿、罪孽的盡頭到了、受報的日子已到．"},{"number":26,"text":"主耶和華如此說、當除掉冠、摘下冕、景况必不再像先前．要使卑者升爲高、使高者降爲卑。"},{"number":27,"text":"我要將這國傾覆、傾覆、而又傾覆、這國也必不再有、直等到那應得的人來到、我就賜給他。"}],"total":3},"EZK 34:1-31":{"label":"以西結書 34:1–31","verses":[{"number":1,"text":"耶和華的話臨到我說、"},{"number":2,"text":"人子阿、你要向以色列的牧人發豫言攻擊他們、說、主耶和華如此說、禍哉、以色列的牧人、只知牧養自己．牧人豈不當牧養羣羊麼。"},{"number":3,"text":"你們喫脂油、穿羊毛、宰肥壯的、卻不牧養羣羊。"},{"number":4,"text":"瘦弱的、你們沒有養壯、有病的、你們沒有醫治、受傷的、你們沒有纏裹、被逐的、你們沒有領回、失喪的、你們沒有尋找．但用強暴嚴嚴的轄制。"}],"total":31},"EZK 36:25-27":{"label":"以西結書 36:25–27","verses":[{"number":25,"text":"我必用清水灑在你們身上、你們就潔淨了．我要潔淨你們、使你們脫離一切的汚穢、棄掉一切的偶像。"},{"number":26,"text":"我也要賜給你們一個新心、將新靈放在你們裏面．又從你們的肉體中除掉石心、賜給你們肉心。"},{"number":27,"text":"我必將我的靈、放在你們裏面、使你們順從我的律例、謹守遵行我的典章。"}],"total":3},"EZK 37:1-14":{"label":"以西結書 37:1–14","verses":[{"number":1,"text":"耶和華的靈、降在我身上、耶和華藉他的靈帶我出去、將我放在平原中．這平原徧滿骸骨。"},{"number":2,"text":"他使我從骸骨的四圍經過．誰知在平原的骸骨甚多、而且極其枯乾。"},{"number":3,"text":"他對我說、人子阿、這些骸骨能復活麼．我說、主耶和華阿、你是知道的。"},{"number":4,"text":"他又對我說、你向這些骸骨發豫言、說、枯乾的骸骨阿、要聽耶和華的話。"}],"total":14},"EZK 37:24-28":{"label":"以西結書 37:24–28","verses":[{"number":24,"text":"我的僕人大衞、必作他們的王．衆民必歸一個牧人．他們必順從我的典章、謹守遵行我的律例。"},{"number":25,"text":"他們必住在我賜給我僕人雅各的地上、就是你們列祖所住之地．他們和他們的子孫、並子孫的子孫、都永遠住在那裏．我的僕人大衞、必作他們的王、直到永遠。"},{"number":26,"text":"並且我要與他們立平安的約、作爲永約．我也要將他們安置在本地、使他們的人數增多、又在他們中間設立我的聖所、直到永遠。"},{"number":27,"text":"我的居所必在他們中間．我要作他們的　神、他們要作我的子民。"}],"total":5},"EZK 47:1-12":{"label":"以西結書 47:1–12","verses":[{"number":1,"text":"他帶我回到殿門、見殿的門檻下有水往東流出．（原來殿面朝東）這水從檻下、由殿的右邊、在祭壇的南邊往下流。"},{"number":2,"text":"他帶我出北門、又領我從外邊轉到朝東的外門、見水從右邊流出。"},{"number":3,"text":"他手拿準繩往東出去的時候、量了一千肘、使我𧼮過水、水到踝子骨。"},{"number":4,"text":"他又量了一千肘、使我𧼮過水、水就到膝。再量了一千肘、使我𧼮過水、水便到腰。"}],"total":12},"EZK 48:35":{"label":"以西結書 48:35","verses":[{"number":35,"text":"城四圍共一萬八千肘．從此以後、這城的名字、必稱爲耶和華的所在。"}],"total":1},"GAL 3:6-9":{"label":"加拉太書 3:6–9","verses":[{"number":6,"text":"正如『亞伯拉罕信　神這就算爲他的義。』"},{"number":7,"text":"所以你們要知道那以信爲本的人、就是亞伯拉罕的子孫。"},{"number":8,"text":"並且聖經旣然豫先看明、　神要叫外邦人因信稱義、就早已傳福音給亞伯拉罕、說、『萬國都必因你得福。』"},{"number":9,"text":"可見那以信爲本的人、和有信心的亞伯拉罕一同得福。"}],"total":4},"GAL 3:8-16":{"label":"加拉太書 3:8–16","verses":[{"number":8,"text":"並且聖經旣然豫先看明、　神要叫外邦人因信稱義、就早已傳福音給亞伯拉罕、說、『萬國都必因你得福。』"},{"number":9,"text":"可見那以信爲本的人、和有信心的亞伯拉罕一同得福。"},{"number":10,"text":"凡以行律法爲本的、都是被咒詛的．因爲經上記着、『凡不常照律法書上所記一切之事去行的、就被咒詛。』"},{"number":11,"text":"沒有一個人靠着律法在　神面前稱義、這是明顯的．因爲經上說、『義人必因信得生。』"}],"total":9},"GAL 3:10-14":{"label":"加拉太書 3:10–14","verses":[{"number":10,"text":"凡以行律法爲本的、都是被咒詛的．因爲經上記着、『凡不常照律法書上所記一切之事去行的、就被咒詛。』"},{"number":11,"text":"沒有一個人靠着律法在　神面前稱義、這是明顯的．因爲經上說、『義人必因信得生。』"},{"number":12,"text":"律法原不本乎信、只說、『行這些事的、就必因此活着。』"},{"number":13,"text":"基督旣爲我們受了咒詛、就贖出我們脫離律法的咒詛．因爲經上記着、『凡掛在木頭上都是被咒詛的。』"}],"total":5},"GAL 3:11":{"label":"加拉太書 3:11","verses":[{"number":11,"text":"沒有一個人靠着律法在　神面前稱義、這是明顯的．因爲經上說、『義人必因信得生。』"}],"total":1},"GAL 3:14":{"label":"加拉太書 3:14","verses":[{"number":14,"text":"這便叫亞伯拉罕的福、因基督耶穌可以臨到外邦人、使我們因信得着所應許的聖靈。"}],"total":1},"GAL 3:29":{"label":"加拉太書 3:29","verses":[{"number":29,"text":"你們旣屬乎基督、就是亞伯拉罕的後裔、是照着應許承受產業的了。"}],"total":1},"GAL 4:21-31":{"label":"加拉太書 4:21–31","verses":[{"number":21,"text":"你們這願意在律法以下的人、請告訴我、你們豈沒有聽見律法麼。"},{"number":22,"text":"因爲律法上記着、亞伯拉罕有兩個兒子、一個是使女生的、一個是自主之婦人生的。"},{"number":23,"text":"然而那使女所生的、是按着血氣生的．那自主之婦人所生的、是憑着應許生的。"},{"number":24,"text":"這都是比方．那兩個婦人、就是兩約．一約是出於西乃山、生子爲奴、乃是夏甲。"}],"total":11},"GEN 1:26-28":{"label":"創世記 1:26–28","verses":[{"number":26,"text":"神說、我們要照着我們的形像、按着我們的樣式造人、使他們管理海裏的魚、空中的鳥、地上的牲畜、和全地、並地上所爬的一切昆蟲。"},{"number":27,"text":"神就照着自己的形像造人、乃是照着他的形像造男造女。"},{"number":28,"text":"神就賜福給他們．又對他們說、要生養衆多、遍滿地面、治理這地．也要管理海裏的魚、空中的鳥．和地上各樣行動的活物。"}],"total":3},"GEN 2:1-3":{"label":"創世記 2:1–3","verses":[{"number":1,"text":"天地萬物都造齊了。"},{"number":2,"text":"到第七日、　神造物的工已經完畢、就在第七日歇了他一切的工、安息了。"},{"number":3,"text":"神賜福給第七日、定爲聖日、因爲在這日　神歇了他一切創造的工、就安息了。"}],"total":3},"GEN 2:7":{"label":"創世記 2:7","verses":[{"number":7,"text":"耶和華　神用地上的塵土造人、將生氣吹在他鼻孔裏、他就成了有靈的活人、名叫亞當。"}],"total":1},"GEN 2:18-24":{"label":"創世記 2:18–24","verses":[{"number":18,"text":"耶和華　神說、那人獨居不好、我要爲他造一個配偶幫助他。"},{"number":19,"text":"耶和華　神用土所造成的野地各樣走獸、和空中各樣飛鳥、都帶到那人面前看他叫甚麼．那人怎樣叫各樣的活物、那就是他的名字。"},{"number":20,"text":"那人便給一切牲畜、和空中飛鳥、野地走獸都起了名．只是那人沒有遇見配偶幫助他。"},{"number":21,"text":"耶和華　神使他沉睡、他就睡了．於是取下他的一條肋骨、又把肉合起來。"}],"total":7},"GEN 3:15":{"label":"創世記 3:15","verses":[{"number":15,"text":"我又要叫你和女人彼此爲仇、你的後裔和女人的後裔、也彼此爲仇．女人的後裔要傷你的頭、你要傷他的脚跟。"}],"total":1},"GEN 3:21":{"label":"創世記 3:21","verses":[{"number":21,"text":"耶和華　神爲亞當和他妻子用皮子作衣服、給他們穿。"}],"total":1},"GEN 4:8-10":{"label":"創世記 4:8–10","verses":[{"number":8,"text":"該隱與他兄弟亞伯說話、二人正在田間、該隱起來打他兄弟亞伯、把他殺了。"},{"number":9,"text":"耶和華對該隱說、你兄弟亞伯在哪裏．他說、我不知道、我豈是看守我兄弟的嗎。"},{"number":10,"text":"耶和華說、你作了甚麼事呢、你兄弟的血、有聲音從地裏向我哀告。"}],"total":3},"GEN 6:13-22":{"label":"創世記 6:13–22","verses":[{"number":13,"text":"神就對挪亞說、凡有血氣的人、他的盡頭已經來到我面前、因爲地上滿了他們的強暴、我要把他們和地一倂毀滅。"},{"number":14,"text":"你要用歌斐木造一隻方舟、分一間一間的造、裏外抹上松香。"},{"number":15,"text":"方舟的造法乃是這樣、要長三百肘、寬五十肘、高三十肘。"},{"number":16,"text":"方舟上邊要留透光處、高一肘．方舟的門要開在旁邊．方舟要分上、中、下三層。"}],"total":10},"GEN 7:17-23":{"label":"創世記 7:17–23","verses":[{"number":17,"text":"洪水氾濫在地上四十天、水往上長、把方舟從地上漂起。"},{"number":18,"text":"水勢浩大、在地上大大的往上長、方舟在水面上漂來漂去。"},{"number":19,"text":"水勢在地上極其浩大、天下的高山都淹沒了。"},{"number":20,"text":"水勢比山高過十五肘、山嶺都淹沒了。"}],"total":7},"GEN 8:15-22":{"label":"創世記 8:15–22","verses":[{"number":15,"text":"神對挪亞說、"},{"number":16,"text":"你和你的妻子、兒子、兒婦、都可以出方舟。"},{"number":17,"text":"在你那裏凡有血肉的活物、就是飛鳥、牲畜、和一切爬在地上的昆蟲、都要帶出來、叫他在地上多多滋生、大大興旺。"},{"number":18,"text":"於是挪亞和他的妻子、兒子、兒婦、都出來了。"}],"total":8},"GEN 12:1-3":{"label":"創世記 12:1–3","verses":[{"number":1,"text":"耶和華對亞伯蘭說、你要離開本地、本族、父家、往我所要指示你的地去。"},{"number":2,"text":"我必叫你成爲大國．我必賜福給你、叫你的名爲大、你也要叫別人得福．"},{"number":3,"text":"爲你祝福的、我必賜福與他、那咒詛你的、我必咒詛他、地上的萬族都要因你得福。"}],"total":3},"GEN 14:18-20":{"label":"創世記 14:18–20","verses":[{"number":18,"text":"又有撒冷王麥基洗德、帶着餅和酒、出來迎接．他是至高　神的祭司。"},{"number":19,"text":"他爲亞伯蘭祝福、說、願天地的主、至高的　神、賜福與亞伯蘭．"},{"number":20,"text":"至高的　神把敵人交在你手裏、是應當稱頌的。亞伯蘭就把所得的、拿出十分之一來、給麥基洗德。"}],"total":3},"GEN 15:1-6":{"label":"創世記 15:1–6","verses":[{"number":1,"text":"這事以後、耶和華在異象中有話對亞伯蘭說、亞伯蘭你不要懼怕、我是你的盾牌、必大大的賞賜你。"},{"number":2,"text":"亞伯蘭說、主耶和華阿、我旣無子、你還賜我甚麼呢．並且要承受我家業的、是大馬色人以利以謝。"},{"number":3,"text":"亞伯蘭又說、你沒有給我兒子、那生在我家中的人、就是我的後嗣。"},{"number":4,"text":"耶和華又有話對他說、這人必不成爲你的後嗣、你本身所生的、纔成爲你的後嗣。"}],"total":6},"GEN 17:1-8":{"label":"創世記 17:1–8","verses":[{"number":1,"text":"亞伯蘭年九十九歲的時候、耶和華向他顯現、對他說、我是全能的　神、你當在我面前作完全人。"},{"number":2,"text":"我就與你立約、使你的後裔極其繁多。"},{"number":3,"text":"亞伯蘭俯伏在地、　神又對他說、"},{"number":4,"text":"我與你立約、你要作多國的父。"}],"total":8},"GEN 18:18":{"label":"創世記 18:18","verses":[{"number":18,"text":"亞伯拉罕必要成爲強大的國、地上的萬國都必因他得福。"}],"total":1},"GEN 22:1-14":{"label":"創世記 22:1–14","verses":[{"number":1,"text":"這些事以後、　神要試驗亞伯拉罕、就呼叫他說、亞伯拉罕、他說、我在這裏。"},{"number":2,"text":"神說、你帶着你的兒子、就是你獨生的兒子、你所愛的以撒、往摩利亞地去、在我所要指示你的山上、把他獻爲燔祭。"},{"number":3,"text":"亞伯拉罕清早起來、備上驢、帶着兩個僕人和他兒子以撒、也劈好了燔祭的柴、就起身往　神所指示他的地方去了。"},{"number":4,"text":"到了第三日、亞伯拉罕舉目遠遠的看見那地方。"}],"total":14},"GEN 22:15-18":{"label":"創世記 22:15–18","verses":[{"number":15,"text":"耶和華的使者第二次從天上呼叫亞伯拉罕說、"},{"number":16,"text":"耶和華說你旣行了這事、不留下你的兒子、就是你獨生的兒子、我便指着自己起誓說、"},{"number":17,"text":"論福、我必賜大福給你、論子孫、我必叫你的子孫多起來、如同天上的星、海邊的沙、你子孫必得着仇敵的城門。"},{"number":18,"text":"並且地上萬國都必因你的後裔得福、因爲你聽從了我的話．"}],"total":4},"GEN 26:2-5":{"label":"創世記 26:2–5","verses":[{"number":2,"text":"耶和華向以撒顯現、說、你不要下埃及去、要住在我所指示你的地。"},{"number":3,"text":"你寄居在這地、我必與你同在、賜福給你、因爲我要將這些地都賜給你和你的後裔、我必堅定我向你父亞伯拉罕所起的誓。"},{"number":4,"text":"我要加增你的後裔、像天上的星那樣多．又要將這些地都賜給你的後裔．並且地上萬國必因你的後裔得福．"},{"number":5,"text":"都因亞伯拉罕聽從我的話、遵守我的吩咐、和我的命令、律例、法度。"}],"total":4},"GEN 28:10-17":{"label":"創世記 28:10–17","verses":[{"number":10,"text":"雅各出了別是巴向哈蘭走去。"},{"number":11,"text":"到了一個地方、因爲太陽落了、就在那裏住宿．便拾起那地方的一塊石頭、枕在頭下、在那裏躺臥睡了。"},{"number":12,"text":"夢見一個梯子立在地上、梯子的頭頂着天、有　神的使者在梯子上、上去下來。"},{"number":13,"text":"耶和華站在梯子以上、說、我是耶和華你祖亞伯拉罕的　神、也是以撒的　神、我要將你現在所躺臥之地賜給你、和你的後裔．"}],"total":8},"GEN 28:13-15":{"label":"創世記 28:13–15","verses":[{"number":13,"text":"耶和華站在梯子以上、說、我是耶和華你祖亞伯拉罕的　神、也是以撒的　神、我要將你現在所躺臥之地賜給你、和你的後裔．"},{"number":14,"text":"你的後裔必像地上的塵沙那樣多、必向東西南北開展．地上萬族必因你和你的後裔得福．"},{"number":15,"text":"我也與你同在、你無論往那裏去、我必保佑你、領你歸回這地、總不離棄你、直到我成全了向你所應許的。"}],"total":3},"GEN 37:12-36":{"label":"創世記 37:12–36","verses":[{"number":12,"text":"約瑟的哥哥們往示劍去、放他們父親的羊。"},{"number":13,"text":"以色列對約瑟說、你哥哥們不是在示劍放羊麼、你來、我要打發你往他們那裏去。約瑟說、我在這裏。"},{"number":14,"text":"以色列說、你去看看你哥哥們平安不平安、羣羊平安不平安、就回來報信給我．於是打發他出希伯崙谷、他就往示劍去了。"},{"number":15,"text":"有人遇見他在田野走迷了路、就問他說、你找甚麼。"}],"total":25},"GEN 45:1-8":{"label":"創世記 45:1–8","verses":[{"number":1,"text":"約瑟在左右站着的人面前、情不自禁、吩咐一聲說、人都要離開我出去．約瑟和弟兄們相認的時候、並沒有一人站在他面前。"},{"number":2,"text":"他就放聲大哭、埃及人、和法老家中的人都聽見了。"},{"number":3,"text":"約瑟對他弟兄們說、我是約瑟、我的父親還在麼．他弟兄不能回答、因爲在他面前都驚惶。"},{"number":4,"text":"約瑟又對他弟兄們說、請你們近前來、他們就近前來．他說、我是你們的兄弟約瑟、就是你們所賣到埃及的。"}],"total":8},"GEN 49:8-12":{"label":"創世記 49:8–12","verses":[{"number":8,"text":"猶大阿、你弟兄們必讚美你、你手必掐住仇敵的頸項、你父親的兒子們必向你下拜。"},{"number":9,"text":"猶大是個小獅子．我兒阿、你抓了食便上去．你屈下身去、臥如公獅、蹲如母獅、誰敢惹你。"},{"number":10,"text":"圭必不離猶大、杖必不離他兩脚之間、直等細羅來到、萬民都必歸順。"},{"number":11,"text":"猶大把小驢拴在葡萄樹上、把驢駒拴在美好的葡萄樹上、他在葡萄酒中洗了衣服、在葡萄汁中洗了袍褂。"}],"total":5},"GEN 50:15-21":{"label":"創世記 50:15–21","verses":[{"number":15,"text":"約瑟的哥哥們見父親死了、就說、或者約瑟懷恨我們、照着我們從前待他一切的惡、足足的報復我們。"},{"number":16,"text":"他們就打發人去見約瑟說、你父親未死以先、吩咐說、"},{"number":17,"text":"你們要對約瑟這樣說、從前你哥哥們惡待你、求你饒恕他們的過犯、和罪惡．如今求你饒恕你父親　神之僕人的過犯．他們對約瑟說這話、約瑟就哭了。"},{"number":18,"text":"他的哥哥們又來俯伏在他面前說、我們是你的僕人。"}],"total":7},"HAB 2:3-4":{"label":"哈巴谷書 2:3–4","verses":[{"number":3,"text":"因爲這默示有一定的日期、快要應驗、並不虛謊．雖然遲延、還要等候．因爲必然臨到、不再遲延。"},{"number":4,"text":"迦勒底人自高自大、心不正直．惟義人因信得生。"}],"total":2},"HAG 2:6-9":{"label":"哈該書 2:6–9","verses":[{"number":6,"text":"萬軍之耶和華如此說、過不多時我必再一次震動天地、滄海、與旱地．"},{"number":7,"text":"我必震動萬國．萬國的珍寶、必都運來．我就使這殿滿了榮耀．這是萬軍之耶和華說的。"},{"number":8,"text":"萬軍之耶和華說、銀子是我的、金子也是我的。"},{"number":9,"text":"這殿後來的榮耀、必大過先前的榮耀．在這地方我必賜平安．這是萬軍之耶和華說的。"}],"total":4},"HAG 2:20-23":{"label":"哈該書 2:20–23","verses":[{"number":20,"text":"這月二十四日、耶和華的話二次臨到哈該說、"},{"number":21,"text":"你要告訴猶大省長所羅巴伯說、我必震動天地．"},{"number":22,"text":"我必傾覆列國的寶座、除滅列邦的勢力、並傾覆戰車和坐在其上的．馬必跌倒、騎馬的敗落、各人被弟兄的刀所殺。"},{"number":23,"text":"萬軍之耶和華說、我僕人撒拉鐵的兒子所羅巴伯阿、到那日、我必以你爲印、因我揀選了你．這是萬軍之耶和華說的。"}],"total":4},"HEB 1:5":{"label":"希伯來書 1:5","verses":[{"number":5,"text":"所有的天使、　神從來對那一個說、『你是我的兒子、我今日生你。』又指着那一個說、『我要作他的父、他要作我的子。』"}],"total":1},"HEB 1:6":{"label":"希伯來書 1:6","verses":[{"number":6,"text":"再者、　神使長子到世上來的時候、就說、『　神的使者都要拜他。』"}],"total":1},"HEB 1:7-14":{"label":"希伯來書 1:7–14","verses":[{"number":7,"text":"論到使者、又說、『　神以風爲使者、以火燄爲僕役。』"},{"number":8,"text":"論到子卻說、『　神阿、你的寶座是永永遠遠的、你的國權是正直的。"},{"number":9,"text":"你喜愛公義、恨惡罪惡．所以　神、就是你的　神、用喜樂油膏你、勝過膏你的同伴。』"},{"number":10,"text":"又說、『主阿、你起初立了地的根基、天也是你手所造的．"}],"total":8},"HEB 1:8-9":{"label":"希伯來書 1:8–9","verses":[{"number":8,"text":"論到子卻說、『　神阿、你的寶座是永永遠遠的、你的國權是正直的。"},{"number":9,"text":"你喜愛公義、恨惡罪惡．所以　神、就是你的　神、用喜樂油膏你、勝過膏你的同伴。』"}],"total":2},"HEB 1:10-12":{"label":"希伯來書 1:10–12","verses":[{"number":10,"text":"又說、『主阿、你起初立了地的根基、天也是你手所造的．"},{"number":11,"text":"天地都要滅沒、你卻要長存．天地都要像衣服漸漸舊了．"},{"number":12,"text":"你要將天地捲起來、像一件外衣、天地就都改變了．惟有你永不改變、你的年數沒有窮盡。』"}],"total":3},"HEB 1:13":{"label":"希伯來書 1:13","verses":[{"number":13,"text":"所有的天使、　神從來對那一個說、『你坐在我的右邊、等我使你仇敵作你的脚凳。』"}],"total":1},"HEB 2:5-10":{"label":"希伯來書 2:5–10","verses":[{"number":5,"text":"我們所說將來的世界、　神原沒有交給天使管轄。"},{"number":6,"text":"但有人在經上某處證明說、『人算甚麼、你竟顧念他、世人算甚麼、你竟眷顧他．"},{"number":7,"text":"你叫他比天使微小一點、賜他榮耀尊貴爲冠冕、並將你手所造的都派他管理．"},{"number":8,"text":"叫萬物都服在他的脚下。』旣叫萬物都服他、就沒有剩下一樣不服他的。只是如今我們還不見萬物都服他。"}],"total":6},"HEB 2:10":{"label":"希伯來書 2:10","verses":[{"number":10,"text":"原來那爲萬物所屬、爲萬物所本的、要領許多的兒子進榮耀裏去、使救他們的元帥、因受苦難得以完全、本是合宜的。"}],"total":1},"HEB 2:11-18":{"label":"希伯來書 2:11–18","verses":[{"number":11,"text":"因那使人成聖的、和那些得以成聖的、都是出於一．所以他稱他們爲弟兄、也不以爲恥、"},{"number":12,"text":"說、『我要將你的名傳與我的弟兄、在會中我要頌揚你。』"},{"number":13,"text":"又說、『我要倚賴他。』又說、『看哪、我與　神所給我的兒女。』"},{"number":14,"text":"兒女旣同有血肉之體、他也照樣親自成了血肉之體．特要藉着死、敗壞那掌死權的就是魔鬼．"}],"total":8},"HEB 2:12":{"label":"希伯來書 2:12","verses":[{"number":12,"text":"說、『我要將你的名傳與我的弟兄、在會中我要頌揚你。』"}],"total":1},"HEB 2:14":{"label":"希伯來書 2:14","verses":[{"number":14,"text":"兒女旣同有血肉之體、他也照樣親自成了血肉之體．特要藉着死、敗壞那掌死權的就是魔鬼．"}],"total":1},"HEB 2:14-17":{"label":"希伯來書 2:14–17","verses":[{"number":14,"text":"兒女旣同有血肉之體、他也照樣親自成了血肉之體．特要藉着死、敗壞那掌死權的就是魔鬼．"},{"number":15,"text":"並要釋放那些一生因怕死而爲奴僕的人。"},{"number":16,"text":"他並不救拔天使、乃是救拔亞伯拉罕的後裔。"},{"number":17,"text":"所以他凡事該與他的弟兄相同、爲要在　神的事上、成爲慈悲忠信的大祭司、爲百姓的罪獻上挽回祭。"}],"total":4},"HEB 3:1-6":{"label":"希伯來書 3:1–6","verses":[{"number":1,"text":"同蒙天召的聖潔弟兄阿、你們應當思想我們所認爲使者、爲大祭司的耶穌．"},{"number":2,"text":"他爲那設立他的盡忠、如同摩西在　神的全家盡忠一樣。"},{"number":3,"text":"他比摩西算是更配多得榮耀、好像建造房屋的比房屋更尊榮。"},{"number":4,"text":"因爲房屋都必有人建造．但建造萬物的就是　神。"}],"total":6},"HEB 3:7-19":{"label":"希伯來書 3:7–19","verses":[{"number":7,"text":"聖靈有話說、『你們今日若聽他的話、"},{"number":8,"text":"就不可硬着心、像在曠野惹他發怒、試探他的時候一樣．"},{"number":9,"text":"在那裏、你們的祖宗試我探我、並且觀看我的作爲、有四十年之久。"},{"number":10,"text":"所以我厭煩那世代的人、說、他們心裏常常迷糊、竟不曉得我的作爲．"}],"total":13},"HEB 4:1-11":{"label":"希伯來書 4:1–11","verses":[{"number":1,"text":"我們旣蒙留下有進入他安息的應許、就當畏懼、免得我們中間、或有人似乎是趕不上了。"},{"number":2,"text":"因爲有福音傳給我們、像傳給他們一樣．只是所聽見的道與他們無益、因爲他們沒有信心與所聽見的道調和。"},{"number":3,"text":"但我們已經相信的人、得以進入那安息、正如　神所說、『我在怒中起誓說、他們斷不可進入我的安息。』其實造物之工、從創世以來已經成全了。"},{"number":4,"text":"論到第七日、有一處說、『到第七日　神就歇了他一切的工。』"}],"total":11},"HEB 4:6-11":{"label":"希伯來書 4:6–11","verses":[{"number":6,"text":"旣有必進安息的人、那先前聽見福音的、因爲不信從、不得進去．"},{"number":7,"text":"所以過了多年、就在大衞的書上、又限定一日、如以上所引的說、『你們今日若聽他的話、就不可硬着心。』"},{"number":8,"text":"若是約書亞已叫他們享了安息、後來　神就不再題別的日子了。"},{"number":9,"text":"這樣看來、必另有一安息日的安息、爲　神的子民存留。"}],"total":6},"HEB 5:1-10":{"label":"希伯來書 5:1–10","verses":[{"number":1,"text":"凡從人間挑選的大祭司、是奉派替人辦理屬　神的事、爲要獻上禮物、和贖罪祭．"},{"number":2,"text":"他能體諒那愚蒙的、和失迷的人、因爲他自己也是被輭弱所困．"},{"number":3,"text":"故此他理當爲百姓和自己獻祭贖罪。"},{"number":4,"text":"這大祭司的尊榮、沒有人自取、惟要蒙　神所召、像亞倫一樣。"}],"total":10},"HEB 5:5-10":{"label":"希伯來書 5:5–10","verses":[{"number":5,"text":"如此、基督也不是自取榮耀作大祭司、乃是在乎向他說『你是我的兒子、我今日生你。』的那一位．"},{"number":6,"text":"就如經上又有一處說、『你是照着麥基洗德的等次永遠爲祭司。』"},{"number":7,"text":"基督在肉體的時候、旣大聲哀哭、流淚禱告懇求那能救他免死的主、就因他的虔誠、蒙了應允。"},{"number":8,"text":"他雖然爲兒子、還是因所受的苦難學了順從．"}],"total":6},"HEB 7:1-28":{"label":"希伯來書 7:1–28","verses":[{"number":1,"text":"這麥基洗德、就是撒冷王、又是至高　神的祭司、本是長遠爲祭司的．他當亞伯拉罕殺敗諸王回來的時候、就迎接他、給他祝福。"},{"number":2,"text":"亞伯拉罕也將自己所得來的、取十分之一給他．他頭一個名繙出來、就是仁義王、他又名撒冷王、就是平安王的意思．"},{"number":3,"text":"他無父、無母、無族譜、無生之始、無命之終、乃是與　神的兒子相似。"},{"number":4,"text":"你們想一想、先祖亞伯拉罕、將自己所擄來上等之物取十分之一給他、這人是何等尊貴呢。"}],"total":28},"HEB 7:11-28":{"label":"希伯來書 7:11–28","verses":[{"number":11,"text":"從前百姓在利未人祭司職任以下受律法、倘若藉這職任能得完全、又何用另外興起一位祭司、照麥基洗德的等次、不照亞倫的等次呢。"},{"number":12,"text":"祭司的職任旣已更改、律法也必須更改。"},{"number":13,"text":"因爲這話所指的人、本屬別的支派、那支派裏從來沒有一人伺候祭壇。"},{"number":14,"text":"我們的主分明是從猶大出來的．但這支派、摩西並沒有題到祭司。"}],"total":18},"HEB 7:14":{"label":"希伯來書 7:14","verses":[{"number":14,"text":"我們的主分明是從猶大出來的．但這支派、摩西並沒有題到祭司。"}],"total":1},"HEB 7:23-28":{"label":"希伯來書 7:23–28","verses":[{"number":23,"text":"那些成爲祭司的、數目本來多、是因爲有死阻隔不能長久．"},{"number":24,"text":"這位旣是永遠常存的、他祭司的職任、就長久不更換。"},{"number":25,"text":"凡靠着他進到　神面前的人、他都能拯救到底．因爲他是長遠活着、替他們祈求。"},{"number":26,"text":"像這樣聖潔、無邪惡、無玷汚、遠離罪人、高過諸天的大祭司、原是與我們合宜的。"}],"total":6},"HEB 7:25":{"label":"希伯來書 7:25","verses":[{"number":25,"text":"凡靠着他進到　神面前的人、他都能拯救到底．因爲他是長遠活着、替他們祈求。"}],"total":1},"HEB 7:26-28":{"label":"希伯來書 7:26–28","verses":[{"number":26,"text":"像這樣聖潔、無邪惡、無玷汚、遠離罪人、高過諸天的大祭司、原是與我們合宜的。"},{"number":27,"text":"他不像那些大祭司、每日必須先爲自己的罪、後爲百姓的罪獻祭、因爲他只一次將自己獻上、就把這事成全了。"},{"number":28,"text":"律法本是立輭弱的人爲大祭司．但在律法以後起誓的話、是立兒子爲大祭司、乃是成全到永遠的。"}],"total":3},"HEB 8:1-2":{"label":"希伯來書 8:1–2","verses":[{"number":1,"text":"我們所講的事、其中第一要緊的、就是我們有這樣的大祭司、已經坐在天上至大者寶座的右邊、"},{"number":2,"text":"在聖所、就是眞帳幕裏、作執事．這帳幕是主所支的、不是人所支的。"}],"total":2},"HEB 8:1-5":{"label":"希伯來書 8:1–5","verses":[{"number":1,"text":"我們所講的事、其中第一要緊的、就是我們有這樣的大祭司、已經坐在天上至大者寶座的右邊、"},{"number":2,"text":"在聖所、就是眞帳幕裏、作執事．這帳幕是主所支的、不是人所支的。"},{"number":3,"text":"凡大祭司都是爲獻禮物和祭物設立的．所以這位大祭司也必須有所獻的。"},{"number":4,"text":"他若在地上、必不得爲祭司、因爲已經有照律法獻禮物的祭司。"}],"total":5},"HEB 8:6-13":{"label":"希伯來書 8:6–13","verses":[{"number":6,"text":"如今耶穌所得的職任是更美的、正如他作更美之約的中保．這約原是憑更美之應許立的。"},{"number":7,"text":"那前約若沒有瑕疵、就無處尋求後約了。"},{"number":8,"text":"所以主指責他的百姓說、『日子將到、我要與以色列家、和猶大家、另立新約．"},{"number":9,"text":"不像我拉着他們祖宗的手、領他們出埃及的時候、與他們所立的約．因爲他們不恆心守我的約、我也不理他們．這是主說的。』"}],"total":8},"HEB 8:8-12":{"label":"希伯來書 8:8–12","verses":[{"number":8,"text":"所以主指責他的百姓說、『日子將到、我要與以色列家、和猶大家、另立新約．"},{"number":9,"text":"不像我拉着他們祖宗的手、領他們出埃及的時候、與他們所立的約．因爲他們不恆心守我的約、我也不理他們．這是主說的。』"},{"number":10,"text":"主又說、『那些日子以後、我與以色列家所立的約乃是這樣．我要將我的律法放在他們裏面、寫在他們心上、我要作他們的　神、他們要作我的子民．"},{"number":11,"text":"他們不用各人教導自己的鄉鄰、和自己的弟兄、說、你該認識主．因爲他們從最小的到至大的、都必認識我。"}],"total":5},"HEB 9:1-12":{"label":"希伯來書 9:1–12","verses":[{"number":1,"text":"原來前約有禮拜的條例、和屬世界的聖幕。"},{"number":2,"text":"因爲有豫備的帳幕、頭一層叫作聖所．裏面有燈臺、桌子、和陳設餅。"},{"number":3,"text":"第二幔子後、又有一層帳幕、叫作至聖所．"},{"number":4,"text":"有金香爐、有包金的約櫃、櫃裏有盛嗎哪的金罐、和亞倫發過芽的杖、並兩塊約版．"}],"total":12},"HEB 9:5":{"label":"希伯來書 9:5","verses":[{"number":5,"text":"櫃上面有榮耀基路伯的影罩着施恩座．這幾件我現在不能一一細說。"}],"total":1},"HEB 9:6-14":{"label":"希伯來書 9:6–14","verses":[{"number":6,"text":"這些物件旣如此豫備齊了、衆祭司就常進頭一層帳幕、行拜　神的禮．"},{"number":7,"text":"至於第二層帳幕、惟有大祭司一年一次獨自進去、沒有不帶着血、爲自己和百姓的過錯獻上．"},{"number":8,"text":"聖靈用此指明、頭一層帳幕仍存的時候、進入至聖所的路還未顯明．"},{"number":9,"text":"那頭一層帳幕作現今的一個表樣、所獻的禮物和祭物、就着良心說、都不能叫禮拜的人得以完全．"}],"total":9},"HEB 9:7-14":{"label":"希伯來書 9:7–14","verses":[{"number":7,"text":"至於第二層帳幕、惟有大祭司一年一次獨自進去、沒有不帶着血、爲自己和百姓的過錯獻上．"},{"number":8,"text":"聖靈用此指明、頭一層帳幕仍存的時候、進入至聖所的路還未顯明．"},{"number":9,"text":"那頭一層帳幕作現今的一個表樣、所獻的禮物和祭物、就着良心說、都不能叫禮拜的人得以完全．"},{"number":10,"text":"這些事連那飲食和諸般洗濯的規矩、都不過是屬肉體的條例、命定到振興的時候爲止。"}],"total":8},"HEB 9:13-14":{"label":"希伯來書 9:13–14","verses":[{"number":13,"text":"若山羊和公牛的血、並母牛犢的灰、灑在不潔的人身上、尚且叫人成聖、身體潔淨．"},{"number":14,"text":"何况基督藉着永遠的靈、將自己無瑕無疵獻給　神、他的血豈不更能洗淨你們的心除去你們的死行、使你們事奉那永生　神麼。"}],"total":2},"HEB 9:14":{"label":"希伯來書 9:14","verses":[{"number":14,"text":"何况基督藉着永遠的靈、將自己無瑕無疵獻給　神、他的血豈不更能洗淨你們的心除去你們的死行、使你們事奉那永生　神麼。"}],"total":1},"HEB 9:18-22":{"label":"希伯來書 9:18–22","verses":[{"number":18,"text":"所以前約也不是不用血立的。"},{"number":19,"text":"因爲摩西當日照着律法、將各樣誡命傳給衆百姓、就拿朱紅色絨和牛膝草、把牛犢山羊的血和水、灑在書上、又灑在衆百姓身上、說、"},{"number":20,"text":"『這血就是　神與你們立約的憑據。』"},{"number":21,"text":"他又照樣把血灑在帳幕、和各樣器皿上。"}],"total":5},"HEB 9:22":{"label":"希伯來書 9:22","verses":[{"number":22,"text":"按着律法、凡物差不多都是用血潔淨的、若不流血、罪就不得赦免了。"}],"total":1},"HEB 9:24-28":{"label":"希伯來書 9:24–28","verses":[{"number":24,"text":"因爲基督並不是進了人手所造的聖所、（這不過是眞聖所的影像）乃是進了天堂、如今爲我們顯在　神面前．"},{"number":25,"text":"也不是多次將自己獻上、像那大祭司每年帶着牛羊的血進入聖所．"},{"number":26,"text":"如果這樣、他從創世以來、就必多次受苦了．但如今在這末世顯現一次、把自己獻爲祭、好除掉罪。"},{"number":27,"text":"按着定命、人人都有一死、死後且有審判．"}],"total":5},"HEB 9:26-28":{"label":"希伯來書 9:26–28","verses":[{"number":26,"text":"如果這樣、他從創世以來、就必多次受苦了．但如今在這末世顯現一次、把自己獻爲祭、好除掉罪。"},{"number":27,"text":"按着定命、人人都有一死、死後且有審判．"},{"number":28,"text":"像這樣、基督旣然一次被獻、擔當了多人的罪、將來要向那等候他的人第二次顯現、並與罪無關、乃是爲拯救他們。"}],"total":3},"HEB 9:28":{"label":"希伯來書 9:28","verses":[{"number":28,"text":"像這樣、基督旣然一次被獻、擔當了多人的罪、將來要向那等候他的人第二次顯現、並與罪無關、乃是爲拯救他們。"}],"total":1},"HEB 10:1-4":{"label":"希伯來書 10:1–4","verses":[{"number":1,"text":"律法旣是將來美事的影兒、不是本物的眞像、總不能藉着每年常獻一樣的祭物、叫那近前來的人得以完全。"},{"number":2,"text":"若不然、獻祭的事豈不早已止住了麼．因爲禮拜的人、良心旣被潔淨、就不再覺得有罪了。"},{"number":3,"text":"但這些祭物是叫人每年想起罪來。"},{"number":4,"text":"因爲公牛和山羊的血、斷不能除罪。"}],"total":4},"HEB 10:1-14":{"label":"希伯來書 10:1–14","verses":[{"number":1,"text":"律法旣是將來美事的影兒、不是本物的眞像、總不能藉着每年常獻一樣的祭物、叫那近前來的人得以完全。"},{"number":2,"text":"若不然、獻祭的事豈不早已止住了麼．因爲禮拜的人、良心旣被潔淨、就不再覺得有罪了。"},{"number":3,"text":"但這些祭物是叫人每年想起罪來。"},{"number":4,"text":"因爲公牛和山羊的血、斷不能除罪。"}],"total":14},"HEB 10:5-10":{"label":"希伯來書 10:5–10","verses":[{"number":5,"text":"所以基督到世上來的時候、就說、『　神阿、祭物和禮物是你不願意的、你曾給我豫備了身體．"},{"number":6,"text":"燔祭和贖罪祭是你不喜歡的．"},{"number":7,"text":"那時我說、　神阿、我來了爲要照你的旨意行．我的事在經卷上已經記載了。』"},{"number":8,"text":"以上說、祭物和禮物、燔祭和贖罪祭、是你不願意的、也是你不喜歡的、（這都是按着律法獻的）"}],"total":6},"HEB 10:10-14":{"label":"希伯來書 10:10–14","verses":[{"number":10,"text":"我們憑這旨意、靠耶穌基督只一次獻上他的身體、就得以成聖。"},{"number":11,"text":"凡祭司天天站着事奉　神、屢次獻上一樣的祭物．這祭物永不能除罪。"},{"number":12,"text":"但基督獻了一次永遠的贖罪祭、就在　神的右邊坐下了．"},{"number":13,"text":"從此等候他仇敵成了他的脚凳。"}],"total":5},"HEB 10:15-18":{"label":"希伯來書 10:15–18","verses":[{"number":15,"text":"聖靈也對我們作見證．因爲他旣已說過、"},{"number":16,"text":"『主說、那些日子以後、我與他們所立的約乃是這樣．我要將我的律法寫在他們心上、又要放在他們的裏面。』"},{"number":17,"text":"以後就說、『我不再記念他們的罪愆、和他們的過犯。』"},{"number":18,"text":"這些罪過旣已赦免、就不用再爲罪獻祭了。"}],"total":4},"HEB 10:37-39":{"label":"希伯來書 10:37–39","verses":[{"number":37,"text":"『因爲還有一點點時候、那要來的就來、並不遲延。"},{"number":38,"text":"只是義人必因信得生、他若退後、我心裏就不喜歡他。』"},{"number":39,"text":"我們卻不是退後入沉淪的那等人、乃是有信心以致靈魂得救的人。"}],"total":3},"HEB 11:17-19":{"label":"希伯來書 11:17–19","verses":[{"number":17,"text":"亞伯拉罕因着信、被試驗的時候、就把以撒獻上．這便是那歡喜領受應許的、將自己獨生的兒子獻上。"},{"number":18,"text":"論到這兒子曾有話說、『從以撒生的纔要稱爲你的後裔．』"},{"number":19,"text":"他以爲　神還能叫人從死裏復活．他也彷彿從死中得回他的兒子來。"}],"total":3},"HEB 11:31":{"label":"希伯來書 11:31","verses":[{"number":31,"text":"妓女喇合因着信、曾和和平平的接待探子、就不與那些不順從的人一同滅亡。"}],"total":1},"HEB 11:32-40":{"label":"希伯來書 11:32–40","verses":[{"number":32,"text":"我又何必再說呢．若要一一細說、基甸、巴拉、參孫、耶弗他、大衞、撒母耳、和衆先知的事、時候就不彀了。"},{"number":33,"text":"他們因着信、制伏了敵國、行了公義、得了應許、堵了獅子的口。"},{"number":34,"text":"滅了烈火的猛勢、脫了刀劍的鋒刃、輭弱變爲剛強、爭戰顯出勇敢、打退外邦的全軍。"},{"number":35,"text":"有婦人得自己的死人復活、又有人忍受嚴刑、不肯苟且得釋放、爲要得着更美的復活．"}],"total":9},"HEB 11:33-34":{"label":"希伯來書 11:33–34","verses":[{"number":33,"text":"他們因着信、制伏了敵國、行了公義、得了應許、堵了獅子的口。"},{"number":34,"text":"滅了烈火的猛勢、脫了刀劍的鋒刃、輭弱變爲剛強、爭戰顯出勇敢、打退外邦的全軍。"}],"total":2},"HEB 12:24":{"label":"希伯來書 12:24","verses":[{"number":24,"text":"並新約的中保耶穌、以及所灑的血．這血所說的比亞伯的血所說的更美。"}],"total":1},"HEB 12:26-29":{"label":"希伯來書 12:26–29","verses":[{"number":26,"text":"當時他的聲音震動了地．但如今他應許說、『再一次我不單要震動地、還要震動天。』"},{"number":27,"text":"這再一次的話、是指明被震動的、就是受造之物、都要挪去、使那不被震動的常存。"},{"number":28,"text":"所以我們旣得了不能震動的國、就當感恩、照　神所喜悅的、用虔誠敬畏的心事奉　神。"},{"number":29,"text":"因爲我們的　神乃是烈火。"}],"total":4},"HEB 13:11-13":{"label":"希伯來書 13:11–13","verses":[{"number":11,"text":"原來牲畜的血、被大祭司帶入聖所作贖罪祭、牲畜的身子、被燒在營外。"},{"number":12,"text":"所以耶穌、要用自己的血叫百姓成聖、也就在城門外受苦。"},{"number":13,"text":"這樣、我們也當出到營外就了他去、忍受他所受的凌辱。"}],"total":3},"HEB 13:15":{"label":"希伯來書 13:15","verses":[{"number":15,"text":"我們應當靠着耶穌、常常以頌讚爲祭、獻給　神、這就是那承認主名之人嘴唇的果子。"}],"total":1},"HEB 13:20":{"label":"希伯來書 13:20","verses":[{"number":20,"text":"但願賜平安的　神、就是那憑永約之血使羣羊的大牧人我主耶穌、從死裏復活的　神、"}],"total":1},"HOS 1:10":{"label":"何西阿書 1:10","verses":[{"number":10,"text":"然而以色列的人數必如海沙、不可量、不可數．從前在甚麼地方對他們說、你們不是我的子民、將來在那裏必對他們說、你們是永生　神的兒子。"}],"total":1},"HOS 2:14-20":{"label":"何西阿書 2:14–20","verses":[{"number":14,"text":"後來我必勸導他、領他到曠野、對他說安慰的話．"},{"number":15,"text":"他從那裏出來、我必賜他葡萄園、又賜他亞割谷作爲指望的門、他必在那裏應聲、、與幼年的日子一樣、與從埃及地上來的時候相同。"},{"number":16,"text":"耶和華說、那日你必稱呼我伊施、不再稱呼我巴力、"},{"number":17,"text":"因爲我必從我民的口中除掉諸巴力的名號、這名號不再題起。"}],"total":7},"HOS 2:23":{"label":"何西阿書 2:23","verses":[{"number":23,"text":"我必將他種在這地、素不蒙憐憫的、我必憐憫、本非我民的、我必對他說、你是我的民、他必說、你是我的　神。"}],"total":1},"HOS 6:1-3":{"label":"何西阿書 6:1–3","verses":[{"number":1,"text":"來罷、我們歸向耶和華．他撕裂我們、也必醫治．他打傷我們、也必纏裹。"},{"number":2,"text":"過兩天他必使我們甦醒、第三天他必使我們興起、我們就在他面前得以存活。"},{"number":3,"text":"我們務要認識耶和華、竭力追求認識他．他出現確如晨光、他必臨到我們像甘雨、像滋潤田地的春雨。"}],"total":3},"HOS 11:1":{"label":"何西阿書 11:1","verses":[{"number":1,"text":"以色列年幼的時候我愛他、就從埃及召出我的兒子來。"}],"total":1},"HOS 13:14":{"label":"何西阿書 13:14","verses":[{"number":14,"text":"我必救贖他們脫離陰間、救贖他們脫離死亡．死亡阿、你的災害在哪裏呢．陰間哪、你的毀滅在哪裏呢．在我眼前絕無後悔之事。"}],"total":1},"ISA 2:1-5":{"label":"以賽亞書 2:1–5","verses":[{"number":1,"text":"亞摩斯的兒子以賽亞得默示、論到猶大、和耶路撒冷。"},{"number":2,"text":"末後的日子、耶和華殿的山必堅立、超乎諸山、高舉過於萬嶺．萬民都要流歸這山"},{"number":3,"text":"必有許多國的民前往、說、來罷、我們登耶和華的山、奔雅各　神的殿．主必將他的道教訓我們、我們也要行他的路．因爲訓誨必出於錫安、耶和華的言語、必出於耶路撒冷。"},{"number":4,"text":"他必在列國中施行審判、爲許多國民斷定是非．他們要將刀打成犂頭、把槍打成鐮刀．這國不舉刀攻擊那國、他們也不再學習戰事。"}],"total":5},"ISA 4:2-6":{"label":"以賽亞書 4:2–6","verses":[{"number":2,"text":"到那日、耶和華發生的苗、必華美尊榮、地的出產、必爲以色列逃脫的人顯爲榮華茂盛。"},{"number":3,"text":"那時、賸在錫安留在耶路撒冷的、就是一切住耶路撒冷、在生命册上記名的、必稱爲聖。"},{"number":4,"text":"主以公義的靈、和焚燒的靈、將錫安女子的汚穢洗去、又將耶路撒冷中殺人的血除淨。"},{"number":5,"text":"耶和華也必在錫安全山、並各會衆以上、使白日有煙雲、黑夜有火燄的光．因爲在全榮耀之上必有遮蔽。"}],"total":5},"ISA 5:1-7":{"label":"以賽亞書 5:1–7","verses":[{"number":1,"text":"我要爲我所親愛的唱歌、是我所愛者的歌、論他葡萄園的事。我所親愛的有葡萄園、在肥美的山岡上．"},{"number":2,"text":"他刨挖園子、撿去石頭、栽種上等的葡萄樹、在園中蓋了一座樓、又鑿出壓酒池．指望結好葡萄、反倒結了野葡萄。"},{"number":3,"text":"耶路撒冷的居民、和猶大人哪、請你們現今在我與我的葡萄園中、斷定是非。"},{"number":4,"text":"我爲我葡萄園所作之外、還有甚麼可作的呢．我指望結好葡萄、怎麼倒結了野葡萄呢。"}],"total":7},"ISA 6:1-13":{"label":"以賽亞書 6:1–13","verses":[{"number":1,"text":"當烏西雅王崩的那年、我見主坐在高高的寶座上．他的衣裳垂下、遮滿聖殿。"},{"number":2,"text":"其上有撒拉弗侍立．各有六個翅膀．用兩個翅膀遮臉、兩個翅膀遮脚、兩個翅膀飛翔．"},{"number":3,"text":"彼此呼喊說、聖哉、聖哉、聖哉、萬軍之耶和華．他的榮光充滿全地。"},{"number":4,"text":"因呼喊者的聲音、門檻的根基震動、殿充滿了煙雲。"}],"total":13},"ISA 7:10-17":{"label":"以賽亞書 7:10–17","verses":[{"number":10,"text":"耶和華又曉諭亞哈斯說、"},{"number":11,"text":"你向耶和華你的　神求一個兆頭．或求顯在深處、或求顯在高處。"},{"number":12,"text":"亞哈斯說、我不求、我不試探耶和華。"},{"number":13,"text":"以賽亞說、大衞家阿、你們當聽．你們使人厭煩豈算小事、還要使我的　神厭煩麼。"}],"total":8},"ISA 8:12-15":{"label":"以賽亞書 8:12–15","verses":[{"number":12,"text":"這百姓說、同謀背叛、你們不要說、同謀背叛．他們所怕的、你們不要怕、也不要畏懼。"},{"number":13,"text":"但要尊萬軍之耶和華爲聖．以他爲你們所當怕的、所當畏懼的。"},{"number":14,"text":"他必作爲聖所．卻向以色列兩家作絆脚的石頭、跌人的磐石．向耶路撒冷的居民、作爲圈套和網羅。"},{"number":15,"text":"許多人必在其上絆脚跌倒、而且跌碎、並陷入網羅、被纏住。"}],"total":4},"ISA 8:17-18":{"label":"以賽亞書 8:17–18","verses":[{"number":17,"text":"我要等候那掩面不顧雅各家的耶和華、我也要仰望他。"},{"number":18,"text":"看哪、我與耶和華所給我的兒女、就是從住在錫安山萬軍之耶和華來的、在以色列中作爲豫兆和奇蹟。"}],"total":2},"ISA 9:1-2":{"label":"以賽亞書 9:1–2","verses":[{"number":1,"text":"但那受過痛苦的、必不再見幽暗。從前　神使西布倫地、和拿弗他利地被藐視．末後卻使這沿海的路、約但河外、外邦人的加利利地、得着榮耀。"},{"number":2,"text":"在黑暗中行走的百姓、看見了大光．住在死蔭之地的人、有光照耀他們。"}],"total":2},"ISA 9:6-7":{"label":"以賽亞書 9:6–7","verses":[{"number":6,"text":"因有一嬰孩爲我們而生、有一子賜給我們．政權必擔在他的肩頭上．他名稱爲奇妙、策士、全能的　神、永在的父、和平的君。"},{"number":7,"text":"他的政權與平安必加增無窮．他必在大衞的寶座上、治理他的國、以公平公義使國堅定穩固、從今直到永遠。萬軍之耶和華的熱心、必成就這事。"}],"total":2},"ISA 11:1-10":{"label":"以賽亞書 11:1–10","verses":[{"number":1,"text":"從耶西的本必發一條、從他根生的枝子必結果實。"},{"number":2,"text":"耶和華的靈必住在他身上、就是使他有智慧和聰明的靈、謀畧和能力的靈、知識和敬畏耶和華的靈。"},{"number":3,"text":"他必以敬畏耶和華爲樂．行審判不憑眼見、斷是非也不憑耳聞．"},{"number":4,"text":"卻要以公義審判貧窮人、以正直判斷世上的謙卑人．以口中的杖擊打世界．以嘴裏的氣殺戮惡人。"}],"total":10},"ISA 16:5":{"label":"以賽亞書 16:5","verses":[{"number":5,"text":"必有寶座因慈愛堅立．必有一位誠誠實實坐在其上、在大衞帳幕中施行審判、尋求公平、速行公義。"}],"total":1},"ISA 22:20-25":{"label":"以賽亞書 22:20–25","verses":[{"number":20,"text":"到那日我必召我僕人希勒家的兒子以利亞敬來．"},{"number":21,"text":"將你的外袍給他穿上、將你的腰帶給他繫緊、將你的政權交在他手中．他必作耶路撒冷居民和猶大家的父。"},{"number":22,"text":"我必將大衞家的鑰匙放在他肩頭上．他開、無人能關．他關、無人能開。"},{"number":23,"text":"我必將他安穩、像釘子釘在堅固處．他必作爲他父家榮耀的寶座。"}],"total":6},"ISA 25:6-9":{"label":"以賽亞書 25:6–9","verses":[{"number":6,"text":"在這山上萬軍之耶和華、必爲萬民用肥甘設擺筵席、用陳酒和滿髓的肥甘、並澄清的陳酒、設擺筵席。"},{"number":7,"text":"他又必在這山上、除滅遮蓋萬民之物、和遮蔽萬國蒙臉的帕子。"},{"number":8,"text":"他已經吞滅死亡直到永遠．主耶和華必擦去各人臉上的眼淚、又除掉普天下他百姓的羞辱．因爲這是耶和華說的。"},{"number":9,"text":"到那日人必說、看哪、這是我們的　神．我們素來等候他、他必拯救我們、這是耶和華、我們素來等候他、我們必因他的救恩．歡喜快樂。"}],"total":4},"ISA 26:19":{"label":"以賽亞書 26:19","verses":[{"number":19,"text":"死人要復活．屍首要興起。睡在塵埃的阿、要醒起歌唱．因你的甘露好像菜蔬上的甘露、地也要交出死人來。"}],"total":1},"ISA 28:16":{"label":"以賽亞書 28:16","verses":[{"number":16,"text":"所以主耶和華如此說、看哪、我在錫安放一塊石頭、作爲根基、是試驗過的石頭、是穩固根基、寶貴的房角石、信靠的人必不着急。"}],"total":1},"ISA 29:18-19":{"label":"以賽亞書 29:18–19","verses":[{"number":18,"text":"那時、聾子必聽見這書上的話．瞎子的眼、必從迷矇黑暗中得以看見。"},{"number":19,"text":"謙卑人、必因耶和華增添歡喜．人間貧窮的、必因以色列的聖者快樂。"}],"total":2},"ISA 32:1-2":{"label":"以賽亞書 32:1–2","verses":[{"number":1,"text":"看哪、必有一王憑公義行政．必有首領藉公平掌權。"},{"number":2,"text":"必有一人像避風所、和避暴雨的隱密處、又像河流在乾旱之地、像大磐石的影子在疲乏之地。"}],"total":2},"ISA 35:4-6":{"label":"以賽亞書 35:4–6","verses":[{"number":4,"text":"對膽怯的人說、你們要剛強、不要懼怕．看哪、你們的　神必來報仇、必來施行極大的報應、他必來拯救你們。"},{"number":5,"text":"那時瞎子的眼必睜開、聾子的耳必開通。"},{"number":6,"text":"那時瘸子必跳躍像鹿、啞吧的舌頭必能歌唱．在曠野必有水發出、在沙漠必有河湧流。"}],"total":3},"ISA 40:1-5":{"label":"以賽亞書 40:1–5","verses":[{"number":1,"text":"你們的　神說、你們要安慰、安慰我的百姓。"},{"number":2,"text":"要對耶路撒冷說安慰的話、又向他宣告說、他爭戰的日子已滿了、他的罪孽赦免了、他爲自己的一切罪、從耶和華手中加倍受罰。"},{"number":3,"text":"有人聲喊着說、在曠野豫備耶和華的路、在沙漠地修平我們　神的道。"},{"number":4,"text":"一切山窪都要填滿、大小山岡都要削平、高高低低的要改爲平坦、崎崎嶇嶇的必成爲平原。"}],"total":5},"ISA 40:9-11":{"label":"以賽亞書 40:9–11","verses":[{"number":9,"text":"報好信息給錫安的阿、你要登高山．報好信息給耶路撒冷的阿、你要極力揚聲．揚聲不要懼怕、對猶大的城邑說、看哪、你們的　神。"},{"number":10,"text":"主耶和華必像大能者臨到、他的膀臂必爲他掌權．他的賞賜在他那裏、他的報應在他面前。"},{"number":11,"text":"他必像牧人牧養自己的羊羣、用膀臂聚集羊羔抱在懷中、慢慢引導那乳養小羊的。"}],"total":3},"ISA 42:1-9":{"label":"以賽亞書 42:1–9","verses":[{"number":1,"text":"看哪、我的僕人、我所扶持、所揀選、心裏所喜悅的、我已將我的靈賜給他、他必將公理傳給外邦。"},{"number":2,"text":"他不喧嚷、不揚聲、也不使街上聽見他的聲音。"},{"number":3,"text":"壓傷的蘆葦、他不折斷．將殘的燈火、他不吹滅．他憑眞實將公理傳開。"},{"number":4,"text":"他不灰心、也不喪膽、直到他在地上設立公理．海島都等候他的訓誨。"}],"total":9},"ISA 43:16-21":{"label":"以賽亞書 43:16–21","verses":[{"number":16,"text":"耶和華在滄海中開道、在大水中開路．"},{"number":17,"text":"使車輛、馬匹、軍兵、勇士、都出來、一同躺下不再起來、他們滅沒好像熄滅的燈火．"},{"number":18,"text":"耶和華如此說、你們不要記念從前的事、也不要思想古時的事。"},{"number":19,"text":"看哪、我要作一件新事、如今要發現、你們豈不知道麼．我必在曠野開道路、在沙漠開江河。"}],"total":6},"ISA 44:1-5":{"label":"以賽亞書 44:1–5","verses":[{"number":1,"text":"我的僕人雅各、我所揀選的以色列阿、現在你當聽。"},{"number":2,"text":"造作你、又從你出胎造就你、並要幫助你的耶和華如此說、我的僕人雅各、我所揀選的耶書崙哪、不要害怕．"},{"number":3,"text":"因爲我要將水澆灌口渴的人、將河澆灌乾旱之地．我要將我的靈澆灌你的後裔、將我的福澆灌你的子孫。"},{"number":4,"text":"他們要發生在草中、像溪水旁的柳樹。"}],"total":5},"ISA 45:22-25":{"label":"以賽亞書 45:22–25","verses":[{"number":22,"text":"地極的人都當仰望我、就必得救．因爲我是　神、再沒有別神。"},{"number":23,"text":"我指着自己起誓、我口所出的話是憑公義、並不反回、萬膝必向我跪拜、萬口必憑我起誓。"},{"number":24,"text":"人論我說、公義、能力、惟獨在乎耶和華．人都必歸向他、凡向他發怒的、必至蒙羞。"},{"number":25,"text":"以色列的後裔、都必因耶和華得稱爲義、並要誇耀。"}],"total":4},"ISA 48:16":{"label":"以賽亞書 48:16","verses":[{"number":16,"text":"你們要就近我來聽這話．我從起頭並未曾在隱密處說話、自從有這事、我就在那裏．現在主耶和華差遣我和他的靈來。。"}],"total":1},"ISA 49:1-7":{"label":"以賽亞書 49:1–7","verses":[{"number":1,"text":"衆海島阿、當聽我言．遠方的衆民哪、留心而聽．自我出胎、耶和華就選召我、自出母腹、他就題我的名。"},{"number":2,"text":"他使我的口如快刀、將我藏在他手蔭之下．又使我成爲磨亮的箭、將我藏在他箭袋之中。"},{"number":3,"text":"對我說、你是我的僕人以色列、我必因你得榮耀。"},{"number":4,"text":"我卻說、我勞碌是徒然、我盡力是虛無虛空、然而我當得的理必在耶和華那裏、我的賞賜必在我　神那裏。"}],"total":7},"ISA 49:8-13":{"label":"以賽亞書 49:8–13","verses":[{"number":8,"text":"耶和華如此說、在悅納的時候我應允了你、在拯救的日子我濟助了你、我要保護你、使你作衆民的中保、復興徧地、使人承受荒涼之地爲業。"},{"number":9,"text":"對那被捆綁的人說、出來罷．對那在黑暗的人說、顯露罷．他們在路上必得飲食、在一切淨光的高處必有食物。"},{"number":10,"text":"不饑不渴、炎熱和烈日必不傷害他們、因爲憐恤他們的、必引導他們、領他們到水泉旁邊。"},{"number":11,"text":"我必使我的衆山成爲大道、我的大路也被修高。"}],"total":6},"ISA 50:4-9":{"label":"以賽亞書 50:4–9","verses":[{"number":4,"text":"主耶和華賜我受教者的舌頭、使我知道怎樣用言語扶助疲乏的人．主每早晨題醒、題醒我的耳朶、使我能聽、像受教者一樣。"},{"number":5,"text":"主耶和華開通我的耳朶、我並沒有違背、也沒有退後。"},{"number":6,"text":"人打我的背、我任他打．人拔我顋頰的鬍鬚、我由他拔．人辱我吐我、我並不掩面。"},{"number":7,"text":"主耶和華必幫助我、所以我不抱愧．我硬着臉面好像堅石、我也知道我必不至蒙羞。"}],"total":6},"ISA 52:7-10":{"label":"以賽亞書 52:7–10","verses":[{"number":7,"text":"那報佳音、傳平安、報好信、傳救恩的、對錫安說、你的　神作王了．這人的脚登山何等佳美。"},{"number":8,"text":"聽阿、你守望之人的聲音．他們揚起聲來、一同歌唱．因爲耶和華歸回錫安的時候、他們必親眼看見。"},{"number":9,"text":"耶路撒冷的荒塲阿、要發起歡聲、一同歌唱．因爲耶和華安慰了他的百姓、救贖了耶路撒冷。"},{"number":10,"text":"耶和華在萬國眼前露出聖臂．地極的人都看見我們　神的救恩了。"}],"total":4},"ISA 52:13-15":{"label":"以賽亞書 52:13–15","verses":[{"number":13,"text":"我的僕人行事必有智慧、必被高舉上升、且成爲至高。"},{"number":14,"text":"許多人因他驚奇、（他的面貌比別人憔悴、他的形容比世人枯槁。）"},{"number":15,"text":"這樣、他必洗淨許多國民．君王要向他閉口．因所未曾傳與他們的、他們必看見．未曾聽見的、他們要明白。"}],"total":3},"ISA 53:1-12":{"label":"以賽亞書 53:1–12","verses":[{"number":1,"text":"我們所傳的、有誰信呢．耶和華的膀臂向誰顯露呢。"},{"number":2,"text":"他在耶和華面前生長如嫩芽、像根出於乾地．他無佳形美容、我們看見他的時候、也無美貌使我們羨慕他。"},{"number":3,"text":"他被藐視、被人厭棄、多受痛苦、常經憂患。他被藐視、好像被人掩面不看的一樣．我們也不尊重他。"},{"number":4,"text":"他誠然擔當我們的憂患、背負我們的痛苦．我們卻以爲他受責罰、被　神擊打苦待了。"}],"total":12},"ISA 54:1-3":{"label":"以賽亞書 54:1–3","verses":[{"number":1,"text":"你這不懷孕不生養的、要歌唱．你這未曾經過產難的、要發聲歌唱、揚聲歡呼．因爲沒有丈夫的、比有丈夫的兒女更多．這是耶和華說的。"},{"number":2,"text":"要擴張你帳幕之地、張大你居所的幔子、不要限止、要放長你的繩子、堅固你的橛子。"},{"number":3,"text":"因爲你要向左向右開展．你的後裔必得多國爲業、又使荒涼的城邑有人居住。"}],"total":3},"ISA 54:13":{"label":"以賽亞書 54:13","verses":[{"number":13,"text":"你的兒女都要受耶和華的教訓．你的兒女必大享平安。"}],"total":1},"ISA 55:1-5":{"label":"以賽亞書 55:1–5","verses":[{"number":1,"text":"你們一切乾渴的都當就近水來．沒有銀錢的也可以來．你們都來、買了喫．不用銀錢、不用價值、也來買酒和奶。"},{"number":2,"text":"你們爲何花錢買那不足爲食物的、用勞碌得來的買那不使人飽足的呢．你們要留意聽我的話、就能喫那美物、得享肥甘、心中喜樂。"},{"number":3,"text":"你們當就近我來．側耳而聽、就必得活．我必與你們立永約、就是應許大衞那可靠的恩典。"},{"number":4,"text":"我已立他作萬民的見證、爲萬民的君王和司令。"}],"total":5},"ISA 56:6-8":{"label":"以賽亞書 56:6–8","verses":[{"number":6,"text":"還有那些與耶和華聯合的外邦人、要事奉他、要愛耶和華的名、要作他的僕人、就是凡守安息日不干犯、又持守他約的人．"},{"number":7,"text":"我必領他們到我的聖山、使他們在禱告我的殿中喜樂．他們的燔祭、和平安祭、在我壇上必蒙悅納．因我的殿必稱爲萬民禱告的殿。"},{"number":8,"text":"主耶和華、就是招聚以色列被趕散的、說、在這被招聚的人以外、我還要招聚別人歸倂他們。"}],"total":3},"ISA 57:19":{"label":"以賽亞書 57:19","verses":[{"number":19,"text":"我造就嘴唇的果子．願平安康泰歸與遠處的人、也歸與近處的人．並且我要醫治他．這是耶和華說的。"}],"total":1},"ISA 58:6":{"label":"以賽亞書 58:6","verses":[{"number":6,"text":"我所揀選的禁食、不是要鬆開凶惡的繩、解下軛上的索、使被欺壓的得自由、折斷一切的軛麼。"}],"total":1},"ISA 59:16-21":{"label":"以賽亞書 59:16–21","verses":[{"number":16,"text":"他見無人拯救、無人代求、甚爲詫異．就用自己的膀臂施行拯救．以公義扶持自己。"},{"number":17,"text":"他以公義爲鎧甲、以拯救爲頭盔、以報仇爲衣服、以熱心爲外袍。"},{"number":18,"text":"他必按人的行爲施報、惱怒他的敵人、報復他的仇敵、向衆海島施行報應。"},{"number":19,"text":"如此、人從日落之處、必敬畏耶和華的名．從日出之地、也必敬畏他的榮耀．因爲仇敵好像急流的河水沖來、是耶和華之氣所驅逐的。"}],"total":6},"ISA 60:1-7":{"label":"以賽亞書 60:1–7","verses":[{"number":1,"text":"興起發光．因爲你的光已經來到、耶和華的榮耀發現照耀你．"},{"number":2,"text":"看哪、黑暗遮蓋大地、幽暗遮蓋萬民．耶和華卻要顯現照耀你、他的榮耀要現在你身上．"},{"number":3,"text":"萬國要來就你的光、君王要來就你發現的光輝。"},{"number":4,"text":"你舉目向四方觀看．衆人都聚集來到你這裏．你的衆子從遠方而來、你的衆女也被懷抱而來。"}],"total":7},"ISA 61:1-3":{"label":"以賽亞書 61:1–3","verses":[{"number":1,"text":"主耶和華的靈在我身上．因爲耶和華用膏膏我、叫我傳好信息給謙卑的人、差遣我醫好傷心的人、報告被擄的得釋放、被囚的出監牢．"},{"number":2,"text":"報告耶和華的恩年、和我們　神報仇的日子、安慰一切悲哀的人．"},{"number":3,"text":"賜華冠與錫安悲哀的人、代替灰塵、喜樂油、代替悲哀、讚美衣、代替憂傷之靈．使他們稱爲公義樹、是耶和華所栽的、叫他得榮耀。"}],"total":3},"ISA 62:11":{"label":"以賽亞書 62:11","verses":[{"number":11,"text":"看哪、耶和華曾宣告到地極、對錫安的居民說、你的拯救者來到．他的賞賜在他那裏、他的報應在他面前。"}],"total":1},"ISA 63:1-6":{"label":"以賽亞書 63:1–6","verses":[{"number":1,"text":"這從以東的波斯拉來、穿紅衣服、裝扮華美、能力廣大、大步行走的是誰呢．就是我、是憑公義說話、以大能施行拯救．"},{"number":2,"text":"你的裝扮爲何有紅色、你的衣服爲何像踹酒醡的呢．"},{"number":3,"text":"我獨自踹酒醡．衆民中無一人與我同在．我發怒將他們踹下、發烈怒將他們踐踏．他們的血濺在我衣服上、並且汚染了我一切的衣裳．"},{"number":4,"text":"因爲報仇之日在我心中、救贖我民之年已經來到。"}],"total":6},"ISA 65:17-25":{"label":"以賽亞書 65:17–25","verses":[{"number":17,"text":"看哪、我造新天新地、從前的事不再被記念、也不再追想。"},{"number":18,"text":"你們當因我所造的永遠歡喜快樂．因我造耶路撒冷爲人所喜、造其中的居民爲人所樂。"},{"number":19,"text":"我必因耶路撒冷歡喜、因我的百姓快樂．其中必不再聽見哭泣的聲音、和哀號的聲音。"},{"number":20,"text":"其中必沒有數日夭亡的嬰孩、也沒有壽數不滿的老者．因爲百歲死的仍算孩童、有百歲死的罪人算被咒詛。"}],"total":9},"ISA 66:22":{"label":"以賽亞書 66:22","verses":[{"number":22,"text":"耶和華說、我所要造的新天新地、怎樣在我面前長存、你們的後裔和你們的名字、也必照樣長存。"}],"total":1},"JAS 2:25":{"label":"雅各書 2:25","verses":[{"number":25,"text":"妓女喇合接待使者、又放他們從別的路上出去、不也是一樣因行爲稱義麼。"}],"total":1},"JDG 2:16-19":{"label":"士師記 2:16–19","verses":[{"number":16,"text":"耶和華興起士師、士師就拯救他們脫離搶奪他們人的手。"},{"number":17,"text":"他們卻不聽從士師、竟隨從叩拜別神、行了邪淫、速速的偏離他們列祖所行的道、不如他們列祖順從耶和華的命令。"},{"number":18,"text":"耶和華爲他們興起士師、就與那士師同在．士師在世的一切日子、耶和華拯救他們脫離仇敵的手．他們因受欺壓擾害、就哀聲歎氣、所以耶和華後悔了。"},{"number":19,"text":"及至士師死後、他們就轉去行惡、比他們列祖更甚、去事奉叩拜別神．總不斷絕頑梗的惡行。"}],"total":4},"JDG 13:2-7":{"label":"士師記 13:2–7","verses":[{"number":2,"text":"那時有一個瑣拉人、是屬但族的、名叫瑪挪亞．他的妻不懷孕、不生育。"},{"number":3,"text":"耶和華的使者向那婦人顯現、對他說、向來你不懷孕、不生育、如今你必懷孕生一個兒子．"},{"number":4,"text":"所以你當謹愼、清酒濃酒都不可喝、一切不潔之物也不可喫。"},{"number":5,"text":"你必懷孕生一個兒子、不可用剃頭刀剃他的頭、因爲這孩子一出胎就歸　神作拿細耳人．他必起首拯救以色列人脫離非利士人的手。"}],"total":6},"JER 6:16":{"label":"耶利米書 6:16","verses":[{"number":16,"text":"耶和華如此說、你們當站在路上察看、訪問古道、那是善道、便行在其間．這樣、你們心裏必得安息．他們卻說、我們不行在其間。"}],"total":1},"JER 7:1-15":{"label":"耶利米書 7:1–15","verses":[{"number":1,"text":"耶和華的話臨到耶利米、說、"},{"number":2,"text":"你當站在耶和華殿的門口、在那裏宣傳這話、說、你們進這些門敬拜耶和華的一切猶大人、當聽耶和華的話。"},{"number":3,"text":"萬軍之耶和華以色列的　神如此說、你們改正行動作爲、我就使你們在這地方仍然居住。"},{"number":4,"text":"你們不要倚靠虛謊的話、說、這些是耶和華的殿、是耶和華的殿、是耶和華的殿。"}],"total":15},"JER 23:5-6":{"label":"耶利米書 23:5–6","verses":[{"number":5,"text":"耶和華說、日子將到、我要給大衞興起一個公義的苗裔、他必掌王權、行事有智慧、在地上施行公平、和公義。"},{"number":6,"text":"在他的日子、猶大必得救、以色列也安然居住．他的名必稱爲耶和華我們的義。"}],"total":2},"JER 30:8-9":{"label":"耶利米書 30:8–9","verses":[{"number":8,"text":"萬軍之耶和華說、到那日、我必從你頸項上折斷仇敵的軛、扭開他的繩索、外邦人不得再使你作他們的奴僕。"},{"number":9,"text":"你們卻要事奉耶和華你們的　神、和我爲你們所要興起的王大衞。"}],"total":2},"JER 31:15-17":{"label":"耶利米書 31:15–17","verses":[{"number":15,"text":"耶和華如此說、在拉瑪聽見號咷痛哭的聲音、是拉結哭他兒女不肯受安慰、因爲他們都不在了。"},{"number":16,"text":"耶和華如此說、你禁止聲音不要哀哭、禁止眼目不要流淚、因你所作之工、必有賞賜．他們必從敵國歸回．這是耶和華說的。"},{"number":17,"text":"耶和華說、你末後必有指望、你的兒女必回到自己的境界。"}],"total":3},"JER 31:31-34":{"label":"耶利米書 31:31–34","verses":[{"number":31,"text":"耶和華說、日子將到、我要與以色列家和猶大家、另立新約。"},{"number":32,"text":"不像我拉着他們祖宗的手、領他們出埃及地的時候、與他們所立的約．我雖作他們的丈夫、他們卻背了我的約．這是耶和華說的。"},{"number":33,"text":"耶和華說、那些日子以後、我與以色列家所立的約、乃是這樣．我要將我的律法放在他們裏面、寫在他們心上．我要作他們的　神、他們要作我的子民。"},{"number":34,"text":"他們各人不再教導自己的鄰舍、和自己的弟兄、說、你該認識耶和華．因爲他們從最小的、到至大的、都必認識我．我要赦免他們的罪孽、不再記念他們的罪惡．這是耶和華說的。"}],"total":4},"JER 33:14-18":{"label":"耶利米書 33:14–18","verses":[{"number":14,"text":"耶和華說、日子將到、我應許以色列家和猶大家的恩言、必然成就。"},{"number":15,"text":"當那日子、那時候、我必使大衞公義的苗裔長起來．他必在地上施行公平和公義。"},{"number":16,"text":"在那日子猶大必得救、耶路撒冷必安然居住．他的名必稱爲耶和華我們的義。"},{"number":17,"text":"因爲耶和華如此說、大衞必永不斷人坐在以色列家的寶座上．"}],"total":5},"JHN 1:14":{"label":"約翰福音 1:14","verses":[{"number":14,"text":"道成了肉身、住在我們中間、充充滿滿的有恩典有眞理。我們也見過他的榮光、正是父獨生子的榮光。"}],"total":1},"JHN 1:14-18":{"label":"約翰福音 1:14–18","verses":[{"number":14,"text":"道成了肉身、住在我們中間、充充滿滿的有恩典有眞理。我們也見過他的榮光、正是父獨生子的榮光。"},{"number":15,"text":"約翰爲他作見證、喊着說、這就是我曾說、那在我以後來的、反成了在我以前的．因他本來在我以前。"},{"number":16,"text":"從他豐滿的恩典裏我們都領受了、而且恩上加恩。"},{"number":17,"text":"律法本是藉着摩西傳的、恩典和眞理、都是由耶穌基督來的。"}],"total":5},"JHN 1:18":{"label":"約翰福音 1:18","verses":[{"number":18,"text":"從來沒有人看見　神．只有在父懷裏的獨生子將他表明出來。"}],"total":1},"JHN 1:23":{"label":"約翰福音 1:23","verses":[{"number":23,"text":"他說、我就是那在曠野有人聲喊着說、修直主的道路、正如先知以賽亞所說的。"}],"total":1},"JHN 1:50-51":{"label":"約翰福音 1:50–51","verses":[{"number":50,"text":"耶穌對他說、因爲我說在無花果樹底下看見你、你就信麼．你將要看見比這更大的事。"},{"number":51,"text":"又說、我實實在在的告訴你們、你們將要看見天開了、　神的使者上去下來在人子身上。"}],"total":2},"JHN 2:17":{"label":"約翰福音 2:17","verses":[{"number":17,"text":"他的門徒就想起經上記着說、『我爲你的殿、心裏焦急、如同火燒。』"}],"total":1},"JHN 2:19":{"label":"約翰福音 2:19","verses":[{"number":19,"text":"耶穌回答說、你們拆毀這殿、我三日內要再建立起來。"}],"total":1},"JHN 2:19-22":{"label":"約翰福音 2:19–22","verses":[{"number":19,"text":"耶穌回答說、你們拆毀這殿、我三日內要再建立起來。"},{"number":20,"text":"猶太人便說、這殿是四十六年纔造成的、你三日內就再建立起來麼。"},{"number":21,"text":"但耶穌這話、是以他的身體爲殿。"},{"number":22,"text":"所以到他從死裏復活以後、門徒就想起他說過這話、便信了聖經和耶穌所說的。"}],"total":4},"JHN 3:3":{"label":"約翰福音 3:3","verses":[{"number":3,"text":"耶穌回答說、我實實在在的告訴你、人若不重生、就不能見　神的國。"}],"total":1},"JHN 3:3-10":{"label":"約翰福音 3:3–10","verses":[{"number":3,"text":"耶穌回答說、我實實在在的告訴你、人若不重生、就不能見　神的國。"},{"number":4,"text":"尼哥底母說、人已經老了、如何能重生呢．豈能再進母腹生出來麼。"},{"number":5,"text":"耶穌說、我實實在在的告訴你、人若不是從水和聖靈生的、就不能進　神的國。"},{"number":6,"text":"從肉身生的、就是肉身．從靈生的、就是靈。"}],"total":8},"JHN 3:5-8":{"label":"約翰福音 3:5–8","verses":[{"number":5,"text":"耶穌說、我實實在在的告訴你、人若不是從水和聖靈生的、就不能進　神的國。"},{"number":6,"text":"從肉身生的、就是肉身．從靈生的、就是靈。"},{"number":7,"text":"我說、你們必須重生、你不要以爲希奇。"},{"number":8,"text":"風隨着意思吹、你聽見風的響聲、卻不曉得從那裏來、往那裏去．凡從聖靈生的、也是如此。"}],"total":4},"JHN 3:13":{"label":"約翰福音 3:13","verses":[{"number":13,"text":"除了從天降下仍舊在天的人子、沒有人升過天。"}],"total":1},"JHN 3:14-15":{"label":"約翰福音 3:14–15","verses":[{"number":14,"text":"摩西在曠野怎樣舉蛇、人子也必照樣被舉起來．"},{"number":15,"text":"叫一切信他的都得永生。"}],"total":2},"JHN 3:14-17":{"label":"約翰福音 3:14–17","verses":[{"number":14,"text":"摩西在曠野怎樣舉蛇、人子也必照樣被舉起來．"},{"number":15,"text":"叫一切信他的都得永生。"},{"number":16,"text":"神愛世人、甚至將他的獨生子賜給他們、叫一切信他的、不至滅亡、反得永生。"},{"number":17,"text":"因爲　神差他的兒子降世、不是要定世人的罪、乃是要叫世人因他得救。"}],"total":4},"JHN 4:21-24":{"label":"約翰福音 4:21–24","verses":[{"number":21,"text":"耶穌說、婦人、你當信我、時候將到、你們拜父、也不在這山上、也不在耶路撒冷。"},{"number":22,"text":"你們所拜的、你們不知道．我們所拜的、我們知道．因爲救恩是從猶太人出來的。"},{"number":23,"text":"時候將到、如今就是了、那眞正拜父的、要用心靈和誠實拜他、因爲父要這樣的人拜他。"},{"number":24,"text":"神是個靈．所以拜他的、必須用心靈和誠實拜他。"}],"total":4},"JHN 5:25-29":{"label":"約翰福音 5:25–29","verses":[{"number":25,"text":"我實實在在的告訴你們、時候將到、現在就是了、死人要聽見　神兒子的聲音．聽見的人就要活了。"},{"number":26,"text":"因爲父怎樣在自己有生命、就賜給他兒子也照樣在自己有生命．"},{"number":27,"text":"並且因爲他是人子、就賜給他行審判的權柄。"},{"number":28,"text":"你們不要把這事看作希奇．時候要到、凡在墳墓裏的、都要聽見他的聲音、就出來．"}],"total":5},"JHN 5:28-29":{"label":"約翰福音 5:28–29","verses":[{"number":28,"text":"你們不要把這事看作希奇．時候要到、凡在墳墓裏的、都要聽見他的聲音、就出來．"},{"number":29,"text":"行善的復活得生、作惡的復活定罪。"}],"total":2},"JHN 6:14":{"label":"約翰福音 6:14","verses":[{"number":14,"text":"衆人看見耶穌所行的神蹟、就說、這眞是那要到世間來的先知。"}],"total":1},"JHN 6:30-35":{"label":"約翰福音 6:30–35","verses":[{"number":30,"text":"他們又說、你行甚麼神蹟、叫我們看見就信你．你到底作甚麼事呢。"},{"number":31,"text":"我們的祖宗在曠野喫過嗎哪、如經上寫着說、『他從天上賜下糧來給他們喫。』"},{"number":32,"text":"耶穌說、我實實在在的告訴你們、那從天上來的糧、不是摩西賜給你們的、乃是我父將天上來的眞糧賜給你們。"},{"number":33,"text":"因爲　神的糧、就是那從天上降下來賜生命給世界的。"}],"total":6},"JHN 6:32-33":{"label":"約翰福音 6:32–33","verses":[{"number":32,"text":"耶穌說、我實實在在的告訴你們、那從天上來的糧、不是摩西賜給你們的、乃是我父將天上來的眞糧賜給你們。"},{"number":33,"text":"因爲　神的糧、就是那從天上降下來賜生命給世界的。"}],"total":2},"JHN 6:35":{"label":"約翰福音 6:35","verses":[{"number":35,"text":"耶穌說、我就是生命的糧．到我這裏來的、必定不餓．信我的、永遠不渴。"}],"total":1},"JHN 6:44-45":{"label":"約翰福音 6:44–45","verses":[{"number":44,"text":"若不是差我來的父吸引人、就沒有能到我這裏來的．到我這裏來的、在末日我要叫他復活。"},{"number":45,"text":"在先知書上寫着說、『他們都要蒙　神的教訓。』凡聽見父之教訓又學習的、就到我這裏來。"}],"total":2},"JHN 6:48-51":{"label":"約翰福音 6:48–51","verses":[{"number":48,"text":"我就是生命的糧。"},{"number":49,"text":"你們的祖宗在曠野喫過嗎哪、還是死了。"},{"number":50,"text":"這是從天上降下來的糧、叫人喫了就不死。"},{"number":51,"text":"我是從天上降下來生命的糧．人若喫這糧、就必永遠活着．我所要賜的糧、就是我的肉、爲世人之生命所賜的。"}],"total":4},"JHN 6:48-58":{"label":"約翰福音 6:48–58","verses":[{"number":48,"text":"我就是生命的糧。"},{"number":49,"text":"你們的祖宗在曠野喫過嗎哪、還是死了。"},{"number":50,"text":"這是從天上降下來的糧、叫人喫了就不死。"},{"number":51,"text":"我是從天上降下來生命的糧．人若喫這糧、就必永遠活着．我所要賜的糧、就是我的肉、爲世人之生命所賜的。"}],"total":11},"JHN 6:53-58":{"label":"約翰福音 6:53–58","verses":[{"number":53,"text":"耶穌說、我實實在在的告訴你們、你們若不喫人子的肉、不喝人子的血、就沒有生命在你們裏面。"},{"number":54,"text":"喫我肉喝我血的人就有永生．在末日我要叫他復活。"},{"number":55,"text":"我的肉眞是可喫的、我的血眞是可喝的。"},{"number":56,"text":"喫我肉喝我血的人、常在我裏面、我也常在他裏面。"}],"total":6},"JHN 7:37-38":{"label":"約翰福音 7:37–38","verses":[{"number":37,"text":"節期的末日、就是最大之日、耶穌站着高聲說、人若渴了、可以到我這裏來喝。"},{"number":38,"text":"信我的人、就如經上所說、從他腹中要流出活水的江河來。"}],"total":2},"JHN 7:37-39":{"label":"約翰福音 7:37–39","verses":[{"number":37,"text":"節期的末日、就是最大之日、耶穌站着高聲說、人若渴了、可以到我這裏來喝。"},{"number":38,"text":"信我的人、就如經上所說、從他腹中要流出活水的江河來。"},{"number":39,"text":"耶穌這話是指着信他之人、要受聖靈說的、那時還沒有賜下聖靈來．因爲耶穌尚未得着榮耀。"}],"total":3},"JHN 7:41-42":{"label":"約翰福音 7:41–42","verses":[{"number":41,"text":"有的說、這是基督．但也有的說、基督豈是從加利利出來的麼。"},{"number":42,"text":"經上豈不是說、基督是大衞的後裔、從大衞本鄉伯利恆出來的麼。"}],"total":2},"JHN 8:58":{"label":"約翰福音 8:58","verses":[{"number":58,"text":"耶穌說、我實實在在的告訴你們、還沒有亞伯拉罕、就有了我。"}],"total":1},"JHN 10:1-18":{"label":"約翰福音 10:1–18","verses":[{"number":1,"text":"我實實在在的告訴你們、人進羊圈、不從門進去、倒從別處爬進去、那人就是賊、就是強盜。"},{"number":2,"text":"從門進去的、纔是羊的牧人。"},{"number":3,"text":"看門的就給他開門．羊也聽他的聲音．他按着名叫自己的羊、把羊領出來。"},{"number":4,"text":"旣放出自己的羊來、就在前頭走、羊也跟着他、因爲認得他的聲音。"}],"total":18},"JHN 10:3-4":{"label":"約翰福音 10:3–4","verses":[{"number":3,"text":"看門的就給他開門．羊也聽他的聲音．他按着名叫自己的羊、把羊領出來。"},{"number":4,"text":"旣放出自己的羊來、就在前頭走、羊也跟着他、因爲認得他的聲音。"}],"total":2},"JHN 10:11-16":{"label":"約翰福音 10:11–16","verses":[{"number":11,"text":"我是好牧人、好牧人爲羊捨命。"},{"number":12,"text":"若是雇工、不是牧人、羊也不是他自己的、他看見狼來、就撇下羊逃走．狼抓住羊、趕散了羊羣。"},{"number":13,"text":"雇工逃走、因他是雇工、並不顧念羊。"},{"number":14,"text":"我是好牧人．我認識我的羊、我的羊也認識我。"}],"total":6},"JHN 10:11-18":{"label":"約翰福音 10:11–18","verses":[{"number":11,"text":"我是好牧人、好牧人爲羊捨命。"},{"number":12,"text":"若是雇工、不是牧人、羊也不是他自己的、他看見狼來、就撇下羊逃走．狼抓住羊、趕散了羊羣。"},{"number":13,"text":"雇工逃走、因他是雇工、並不顧念羊。"},{"number":14,"text":"我是好牧人．我認識我的羊、我的羊也認識我。"}],"total":8},"JHN 10:30":{"label":"約翰福音 10:30","verses":[{"number":30,"text":"我與父原爲一。"}],"total":1},"JHN 10:30-38":{"label":"約翰福音 10:30–38","verses":[{"number":30,"text":"我與父原爲一。"},{"number":31,"text":"猶太人又拿起石頭來要打他。"},{"number":32,"text":"耶穌對他們說、我從父顯出許多善事給你們看、你們是爲那一件拿石頭打我呢。"},{"number":33,"text":"猶太人回答說、我們不是爲善事拿石頭打你、是爲你說僭妄的話．又爲你是個人、反將自己當作　神。"}],"total":9},"JHN 10:34-38":{"label":"約翰福音 10:34–38","verses":[{"number":34,"text":"耶穌說、你們的律法上豈不是寫着、『我曾說你們是神』麼。"},{"number":35,"text":"經上的話是不能廢的．若那些承受　神道的人、尚且稱爲神、"},{"number":36,"text":"父所分別爲聖、又差到世間來的、他自稱是　神的兒子、你們還向他說、你說僭妄的話麼。"},{"number":37,"text":"我若不行我父的事、你們就不必信我。"}],"total":5},"JHN 11:25-26":{"label":"約翰福音 11:25–26","verses":[{"number":25,"text":"耶穌對他說、復活在我、生命也在我．信我的人、雖然死了、也必復活．"},{"number":26,"text":"凡活着信我的人、必永遠不死。你信這話麼。"}],"total":2},"JHN 12:12-15":{"label":"約翰福音 12:12–15","verses":[{"number":12,"text":"第二天有許多上來過節的人、聽見耶穌將到耶路撒冷、"},{"number":13,"text":"就拿着棕樹枝、出去迎接他、喊着說、和散那、奉主名來的以色列王、是應當稱頌的。"},{"number":14,"text":"耶穌得了一個驢駒、就騎上．如經上所記的說、"},{"number":15,"text":"『錫安的民哪、不要懼怕、你的王騎着驢駒來了。』"}],"total":4},"JHN 12:14-16":{"label":"約翰福音 12:14–16","verses":[{"number":14,"text":"耶穌得了一個驢駒、就騎上．如經上所記的說、"},{"number":15,"text":"『錫安的民哪、不要懼怕、你的王騎着驢駒來了。』"},{"number":16,"text":"這些事門徒起先不明白．等到耶穌得了榮耀以後、纔想起這話是指着他寫的、並且衆人果然向他這樣行了。"}],"total":3},"JHN 12:37-41":{"label":"約翰福音 12:37–41","verses":[{"number":37,"text":"他雖然在他們面前行了許多神蹟、他們還是不信他。"},{"number":38,"text":"這是要應驗先知以賽亞的話、說、『主阿、我們所傳的、有誰信呢．主的膀臂向誰顯露呢。』"},{"number":39,"text":"他們所以不能信、因爲以賽亞又說、"},{"number":40,"text":"『主叫他們瞎了眼、硬了心、免得他們眼睛看見、心裏明白、回轉過來、我就醫治他們。』"}],"total":5},"JHN 12:38":{"label":"約翰福音 12:38","verses":[{"number":38,"text":"這是要應驗先知以賽亞的話、說、『主阿、我們所傳的、有誰信呢．主的膀臂向誰顯露呢。』"}],"total":1},"JHN 13:18":{"label":"約翰福音 13:18","verses":[{"number":18,"text":"我這話不是指着你們衆人說的．我知道我所揀選的是誰．現在要應驗經上的話、說、『同我喫飯的人、用脚踢我。』"}],"total":1},"JHN 15:1-5":{"label":"約翰福音 15:1–5","verses":[{"number":1,"text":"我是眞葡萄樹、我父是栽培的人。"},{"number":2,"text":"凡屬我不結果子的枝子、他就剪去．凡結果子的、他就修理乾淨、使枝子結果子更多。"},{"number":3,"text":"現在你們因我講給你們的道、已經乾淨了。"},{"number":4,"text":"你們要常在我裏面、我也常在你們裏面。枝子若不常在葡萄樹上、自己就不能結果子．你們若不常在我裏面、也是這樣。"}],"total":5},"JHN 15:18-25":{"label":"約翰福音 15:18–25","verses":[{"number":18,"text":"世人若恨你們、你們知道恨你們以先、已經恨我了。"},{"number":19,"text":"你們若屬世界、世界必愛屬自己的．只因你們不屬世界．乃是我從世界中揀選了你們、所以世界就恨你們。"},{"number":20,"text":"你們要記念我從前對你們所說的話、僕人不能大於主人。他們若逼迫了我、也要逼迫你們．若遵守了我的話、也要遵守你們的話。"},{"number":21,"text":"但他們因我的名、要向你們行這一切的事、因爲他們不認識那差我來的。"}],"total":8},"JHN 19:23-24":{"label":"約翰福音 19:23–24","verses":[{"number":23,"text":"兵丁旣然將耶穌釘在十字架上、就拿他的衣服分爲四分、每兵一分．又拿他的裏衣．這件裏衣、原來沒有縫兒、是上下一片織成的。"},{"number":24,"text":"他們就彼此說、我們不要撕開、只要拈鬮、看誰得着．這要應驗經上的話說、『他們分了我的外衣、爲我的裏衣拈鬮。』兵丁果然作了這事。"}],"total":2},"JHN 19:28":{"label":"約翰福音 19:28","verses":[{"number":28,"text":"這事以後、耶穌知道各樣的事已經成了、爲要使經上的話應驗、就說、我渴了。"}],"total":1},"JHN 19:28-30":{"label":"約翰福音 19:28–30","verses":[{"number":28,"text":"這事以後、耶穌知道各樣的事已經成了、爲要使經上的話應驗、就說、我渴了。"},{"number":29,"text":"有一個器皿盛滿了醋、放在那裏．他們就拿海絨蘸滿了醋、綁在牛膝草上、送到他口。"},{"number":30,"text":"耶穌嘗了那醋、就說、成了．便低下頭、將靈魂交付　神了。"}],"total":3},"JHN 19:31-36":{"label":"約翰福音 19:31–36","verses":[{"number":31,"text":"猶太人因這日是豫備日、又因那安息日是個大日、就求彼拉多叫人打斷他們的腿、把他們拿去、免得屍首當安息日留在十字架上。"},{"number":32,"text":"於是兵丁來、把頭一個人的腿、並與耶穌同釘第二個人的腿、都打斷了。"},{"number":33,"text":"只是來到耶穌那裏、見他已經死了、就不打斷他的腿。"},{"number":34,"text":"惟有一個兵拿槍扎他的肋旁、隨卽有血和水流出來。"}],"total":6},"JHN 19:34-37":{"label":"約翰福音 19:34–37","verses":[{"number":34,"text":"惟有一個兵拿槍扎他的肋旁、隨卽有血和水流出來。"},{"number":35,"text":"看見這事的那人就作見證、他的見證也是眞的、並且他知道自己所說的是眞的、叫你們也可以信。"},{"number":36,"text":"這些事成了、爲要應驗經上的話說、『他的骨頭、一根也不可折斷。』"},{"number":37,"text":"經上又有一句說、『他們要仰望自己所扎的人。』"}],"total":4},"JHN 20:25-27":{"label":"約翰福音 20:25–27","verses":[{"number":25,"text":"那些門徒就對他說、我們已經看見主了。多馬卻說、我非看見他手上的釘痕、用指頭探入那釘痕、又用手探入他的肋旁、我總不信。"},{"number":26,"text":"過了八日、門徒又在屋裏、多馬也和他們同在、門都關了．耶穌來站在當中說、願你們平安。"},{"number":27,"text":"就對多馬說、伸過你的指頭來、摸（摸原文作看）我的手．伸出你的手來、探入我的肋旁．不要疑惑、總要信。"}],"total":3},"JHN 20:27":{"label":"約翰福音 20:27","verses":[{"number":27,"text":"就對多馬說、伸過你的指頭來、摸（摸原文作看）我的手．伸出你的手來、探入我的肋旁．不要疑惑、總要信。"}],"total":1},"JOB 19:23-27":{"label":"約伯記 19:23–27","verses":[{"number":23,"text":"惟願我的言語、現在寫上、都記錄在書上．"},{"number":24,"text":"用鐵筆鐫刻、用鉛灌在磐石上、直存到永遠。"},{"number":25,"text":"我知道我的救贖主活着、末了必站立在地上．"},{"number":26,"text":"我這皮肉滅絕之後、我必在肉體之外得見　神。"}],"total":5},"JOL 2:28-32":{"label":"約珥書 2:28–32","verses":[{"number":28,"text":"以後、我要將我的靈澆灌凡有血氣的．你們的兒女要說豫言．你們的老年人要作異夢．少年人要見異象．"},{"number":29,"text":"在那些日子、我要將我的靈澆灌我的僕人和使女。"},{"number":30,"text":"在天上地下、我要顯出奇事、有血、有火、有煙柱。"},{"number":31,"text":"日頭要變爲黑暗、月亮要變爲血、這都在耶和華大而可畏的日子未到以前。"}],"total":5},"JOL 3:13":{"label":"約珥書 3:13","verses":[{"number":13,"text":"開鐮罷．因爲莊稼熟了．踐踏罷。因爲酒醡滿了、酒池盈溢．他們的罪惡甚大。"}],"total":1},"JON 1:17":{"label":"約拿書 1:17","verses":[{"number":17,"text":"耶和華安排一條大魚吞了約拿、他在魚腹中三日三夜。"}],"total":1},"JON 2:1-10":{"label":"約拿書 2:1–10","verses":[{"number":1,"text":"約拿在魚腹中禱告耶和華他的　神、"},{"number":2,"text":"說、我遭遇患難求告耶和華、你就應允我．從陰間的深處呼求、你就俯聽我的聲音。"},{"number":3,"text":"你將我投下深淵、就是海的深處．大水環繞我．你的波浪洪濤、都漫過我身。"},{"number":4,"text":"我說、我從你眼前雖被驅逐、我仍要仰望你的聖殿。"}],"total":10},"JOS 1:1-9":{"label":"約書亞記 1:1–9","verses":[{"number":1,"text":"耶和華的僕人摩西死了以後、耶和華曉諭摩西的幫手嫩的兒子約書亞、說、"},{"number":2,"text":"我的僕人摩西死了。現在你要起來、和衆百姓過這約但河、往我所要賜給以色列人的地去。"},{"number":3,"text":"凡你們脚掌所踏之地、我都照着我所應許摩西的話賜給你們了。"},{"number":4,"text":"從曠野、和這利巴嫩、直到伯拉大河、赫人的全地、又到大海日落之處、都要作你們的境界。"}],"total":9},"JOS 2:15-21":{"label":"約書亞記 2:15–21","verses":[{"number":15,"text":"於是女人用繩子將二人從窗戶裏縋下去．因他的房子是在城牆邊上、他也住在城牆上。"},{"number":16,"text":"他對他們說、你們且往山上去、恐怕追趕的人碰見你們．要在那裏隱藏三天、等追趕的人回來、然後纔可以走你們的路。"},{"number":17,"text":"二人對他說、你要這樣行．不然、你叫我們所起的誓、就與我們無干了。"},{"number":18,"text":"我們來到這地的時候、你要把這條朱紅線繩繫在縋我們下去的窗戶上．並要使你的父母、弟兄、和你父的全家、都聚集在你家中。"}],"total":7},"JOS 5:13-15":{"label":"約書亞記 5:13–15","verses":[{"number":13,"text":"約書亞靠近耶利哥的時候舉目觀看、不料、有一個人手裏有拔出來的刀、對面站立．約書亞到他那裏、問他說、你是幫助我們呢、是幫助我們敵人呢。"},{"number":14,"text":"他回答說、不是的、我來是要作耶和華軍隊的元帥。約書亞就俯伏在地下拜、說、我主有甚麼話吩咐僕人。"},{"number":15,"text":"耶和華軍隊的元帥對約書亞說、把你脚上的鞋脫下來、因爲你所站的地方是聖的。約書亞就照着行了。"}],"total":3},"JOS 21:43-45":{"label":"約書亞記 21:43–45","verses":[{"number":43,"text":"這樣、耶和華將從前向他們列祖起誓所應許的全地、賜給以色列人、他們就得了爲業、住在其中。"},{"number":44,"text":"耶和華照着向他們列祖起誓所應許的一切話、使他們四境平安．他們一切仇敵中、沒有一人在他們面前站立得住．耶和華把一切仇敵都交在他們手中。"},{"number":45,"text":"耶和華應許賜福給以色列家的話、一句也沒有落空、都應驗了。"}],"total":3},"LAM 3:25-33":{"label":"耶利米哀歌 3:25–33","verses":[{"number":25,"text":"凡等候耶和華、心裏尋求他的、耶和華必施恩給他。"},{"number":26,"text":"人仰望耶和華、靜默等候他的救恩、這原是好的。"},{"number":27,"text":"人在幼年負軛、這原是好的。"},{"number":28,"text":"他當獨坐無言、因爲這是耶和華加在他身上的。"}],"total":9},"LEV 1:1-9":{"label":"利未記 1:1–9","verses":[{"number":1,"text":"耶和華從會幕中呼叫摩西、對他說、"},{"number":2,"text":"你曉諭以色列人說、你們中間若有人獻供物給耶和華、要從牛羣羊羣中、獻牲畜爲供物。"},{"number":3,"text":"他的供物若以牛爲燔祭、就要在會幕門口獻一隻沒有殘疾的公牛、可以在耶和華面前蒙悅納。"},{"number":4,"text":"他要按手在燔祭牲的頭上、燔祭便蒙悅納、爲他贖罪。"}],"total":9},"LEV 4:1-12":{"label":"利未記 4:1–12","verses":[{"number":1,"text":"耶和華對摩西說、"},{"number":2,"text":"你曉諭以色列人說、若有人在耶和華所吩咐不可行的甚麼事上、誤犯了一件．"},{"number":3,"text":"或是受膏的祭司犯罪、使百姓陷在罪裏、就當爲他所犯的罪、把沒有殘疾的公牛犢、獻給耶和華爲贖罪祭。"},{"number":4,"text":"他要牽公牛到會幕門口、在耶和華面前、按手在牛的頭上、把牛宰於耶和華面前。"}],"total":12},"LEV 4:11-12":{"label":"利未記 4:11–12","verses":[{"number":11,"text":"公牛的皮、和所有的肉、並頭、腿、臟、腑、糞、"},{"number":12,"text":"就是全公牛、要搬到營外潔淨之地、倒灰之所、用火燒在柴上。"}],"total":2},"LEV 5:14-19":{"label":"利未記 5:14–19","verses":[{"number":14,"text":"耶和華曉諭摩西說、"},{"number":15,"text":"人若在耶和華的聖物上誤犯了罪、有了過犯、就要照你所估的、按聖所的舍客勒拿銀子、將贖愆祭牲、就是羊羣中一隻沒有殘疾的公綿羊、牽到耶和華面前爲贖愆祭．"},{"number":16,"text":"並且他因在聖物上的差錯要償還、另外加五分之一、都給祭司．祭司要用贖愆祭的公綿羊、爲他贖罪、他必蒙赦免。"},{"number":17,"text":"若有人犯罪、行了耶和華所吩咐不可行的甚麼事、他雖然不知道、還是有了罪、就要擔當他的罪孽。"}],"total":6},"LEV 12:1-8":{"label":"利未記 12:1–8","verses":[{"number":1,"text":"耶和華對摩西說、"},{"number":2,"text":"你曉諭以色列人說、若有婦人懷孕生男孩、他就不潔淨七天、像在月經汚穢的日子不潔淨一樣。"},{"number":3,"text":"第八天要給嬰孩行割禮。"},{"number":4,"text":"婦人在產血不潔之中、要家居三十三天．他潔淨的日子未滿、不可摸聖物、也不可進入聖所。"}],"total":8},"LEV 16:1-34":{"label":"利未記 16:1–34","verses":[{"number":1,"text":"亞倫的兩個兒子近到耶和華面前死了．死了之後、耶和華曉諭摩西說、"},{"number":2,"text":"要告訴你哥哥亞倫、不可隨時進聖所的幔子內、到櫃上的施恩座前、免得他死亡、因爲我要從雲中顯現在施恩座上．"},{"number":3,"text":"亞倫進聖所要帶一隻公牛犢爲贖罪祭、一隻公綿羊爲燔祭。"},{"number":4,"text":"要穿上細麻布聖內袍、把細麻布褲子穿在身上、腰束細麻布帶子、頭戴細麻布冠冕．這都是聖服．他要用水洗身、然後穿戴。"}],"total":34},"LEV 16:14-16":{"label":"利未記 16:14–16","verses":[{"number":14,"text":"也要取些公牛的血、用指頭彈在施恩座的東面、又在施恩座的前面、彈血七次。"},{"number":15,"text":"隨後他要宰那爲百姓作贖罪祭的公山羊、把羊的血帶入幔子內、彈在施恩座的上面、和前面、好像彈公牛的血一樣。"},{"number":16,"text":"他因以色列人諸般的汚穢、過犯、就是他們一切的罪愆、當這樣在聖所行贖罪之禮、並因會幕在他們汚穢之中、也要照樣而行。"}],"total":3},"LEV 16:27":{"label":"利未記 16:27","verses":[{"number":27,"text":"作贖罪祭的公牛、和公山羊的血、旣帶入聖所贖罪、這牛羊就要搬到營外、將皮、肉、糞、用火焚燒。"}],"total":1},"LEV 17:10-14":{"label":"利未記 17:10–14","verses":[{"number":10,"text":"凡以色列家中的人、或是寄居在他們中間的外人、若喫甚麼血、我必向那喫血的人變臉、把他從民中剪除。"},{"number":11,"text":"因爲活物的生命是在血中．我把這血賜給你們、可以在壇上爲你們的生命贖罪．因血裏有生命、所以能贖罪．"},{"number":12,"text":"因此我對以色列人說、你們都不可喫血、寄居在你們中間的外人、也不可喫血。"},{"number":13,"text":"凡以色列人、或是寄居在他們中間的外人、若打獵得了可喫的禽獸、必放出他的血來、用土掩蓋。"}],"total":5},"LEV 23:1-44":{"label":"利未記 23:1–44","verses":[{"number":1,"text":"耶和華對摩西說、"},{"number":2,"text":"你曉諭以色列人說、耶和華的節期、你們要宣告爲聖會的節期．"},{"number":3,"text":"六日要作工、第七日是聖安息日、當有聖會、你們甚麼工都不可作、這是在你們一切的住處向耶和華守的安息日。"},{"number":4,"text":"耶和華的節期、就是你們到了日期要宣告爲聖會的、乃是這些．"}],"total":44},"LEV 23:9-14":{"label":"利未記 23:9–14","verses":[{"number":9,"text":"耶和華對摩西說、"},{"number":10,"text":"你曉諭以色列人說、你們到了我賜給你們的地、收割莊稼的時候、要將初熟的莊稼一捆、帶給祭司．"},{"number":11,"text":"他要把這一捆在耶和華面前搖一搖、使你們得蒙悅納．祭司要在安息日的次日、把這捆搖一搖。"},{"number":12,"text":"搖這捆的日子、你們要把一歲沒有殘疾的公綿羊羔、獻給耶和華爲燔祭。"}],"total":6},"LEV 25:8-17":{"label":"利未記 25:8–17","verses":[{"number":8,"text":"你要計算七個安息年、就是七七年．這便爲你成了七個安息年、共是四十九年。"},{"number":9,"text":"當年七月初十日、你要大發角聲、這日就是贖罪日、要在遍地發出角聲。"},{"number":10,"text":"第五十年你們要當作聖年、在遍地給一切的居民宣告自由．這年必爲你們的禧年、各人要歸自己的產業、各歸本家。"},{"number":11,"text":"第五十年要作爲你們的禧年．這年不可耕種、地中自長的、不可收割．沒有修理的葡萄樹、也不可摘取葡萄。"}],"total":10},"LUK 1:16-17":{"label":"路加福音 1:16–17","verses":[{"number":16,"text":"他要使許多以色列人回轉、歸於主他們的　神。"},{"number":17,"text":"他必有以利亞的心志能力、行在主的前面、叫爲父的心轉向兒女、叫悖逆的人轉從義人的智慧．又爲主豫備合用的百姓。"}],"total":2},"LUK 1:28-33":{"label":"路加福音 1:28–33","verses":[{"number":28,"text":"天使進去、對他說、蒙大恩的女子、我問你安、主和你同在了。"},{"number":29,"text":"馬利亞因這話就很驚慌、又反復思想這樣問安是甚麼意思。"},{"number":30,"text":"天使對他說、馬利亞、不要怕．你在　神面前已經蒙恩了。"},{"number":31,"text":"你要懷孕生子、可以給他起名叫耶穌。"}],"total":6},"LUK 1:32":{"label":"路加福音 1:32","verses":[{"number":32,"text":"他要爲大、稱爲至高者的兒子．主　神要把他祖大衞的位給他．"}],"total":1},"LUK 1:32-33":{"label":"路加福音 1:32–33","verses":[{"number":32,"text":"他要爲大、稱爲至高者的兒子．主　神要把他祖大衞的位給他．"},{"number":33,"text":"他要作雅各家的王、直到永遠．他的國也沒有窮盡。"}],"total":2},"LUK 1:46-55":{"label":"路加福音 1:46–55","verses":[{"number":46,"text":"馬利亞說、我心尊主爲大、"},{"number":47,"text":"我靈以　神我的救主爲樂。"},{"number":48,"text":"因爲他顧念他使女的卑微．從今以後、萬代要稱我有福。"},{"number":49,"text":"那有權能的爲我成就了大事．他的名爲聖。"}],"total":10},"LUK 1:69":{"label":"路加福音 1:69","verses":[{"number":69,"text":"在他僕人大衞家中、爲我們興起了拯救的角、"}],"total":1},"LUK 1:72-75":{"label":"路加福音 1:72–75","verses":[{"number":72,"text":"向我們列祖施憐憫、記念他的聖約．"},{"number":73,"text":"就是他對我們祖宗亞伯拉罕所起的誓、"},{"number":74,"text":"叫我們旣從仇敵手中被救出來、"},{"number":75,"text":"就可以終身在他面前、坦然無懼的用聖潔公義事奉他。"}],"total":4},"LUK 1:78-79":{"label":"路加福音 1:78–79","verses":[{"number":78,"text":"因我們　神憐憫的心腸、叫清晨的日光從高天臨到我們、"},{"number":79,"text":"要照亮坐在黑暗中死蔭裏的人．把我們的脚引到平安的路上。"}],"total":2},"LUK 2:11":{"label":"路加福音 2:11","verses":[{"number":11,"text":"因今天在大衞的城裏、爲你們生了救主、就是主基督。"}],"total":1},"LUK 2:22-24":{"label":"路加福音 2:22–24","verses":[{"number":22,"text":"按摩西律法滿了潔淨的日子、他們帶着孩子上耶路撒冷去、要把他獻與主．"},{"number":23,"text":"（正如主的律法上所記、『凡頭生的男子、必稱聖歸主。』）"},{"number":24,"text":"又要照主的律法上所說、或用一對斑鳩、或用兩隻雛鴿獻祭。"}],"total":3},"LUK 2:29-32":{"label":"路加福音 2:29–32","verses":[{"number":29,"text":"主阿、如今可以照你的話、釋放僕人安然去世．"},{"number":30,"text":"因爲我的眼睛已經看見你的救恩、"},{"number":31,"text":"就是你在萬民面前所豫備的．"},{"number":32,"text":"是照亮外邦人的光、又是你民以色列的榮耀。"}],"total":4},"LUK 3:3-6":{"label":"路加福音 3:3–6","verses":[{"number":3,"text":"他就來到約但河一帶地方、宣講悔改的洗禮、使罪得赦．"},{"number":4,"text":"正如先知以賽亞書上所記的話、說、『在曠野有人聲喊着說、豫備主的道、修直他的路。"},{"number":5,"text":"一切山窪都要填滿、大小山岡都要削平、彎彎曲曲的地方要改爲正直、高高低低的道路要改爲平坦。"},{"number":6,"text":"凡有血氣的、都要見　神的救恩。』"}],"total":4},"LUK 3:27":{"label":"路加福音 3:27","verses":[{"number":27,"text":"約亞拿是利撒的兒子、利撒是所羅巴伯的兒子、所羅巴伯是撒拉鐵的兒子、撒拉鐵是尼利的兒子、尼利是麥基的兒子、"}],"total":1},"LUK 4:1-13":{"label":"路加福音 4:1–13","verses":[{"number":1,"text":"耶穌被聖靈充滿、從約但河回來、聖靈將他引到曠野、四十天受魔鬼的試探。"},{"number":2,"text":"那些日子沒有喫甚麼．日子滿了、他就餓了。"},{"number":3,"text":"魔鬼對他說、你若是　神的兒子、可以吩咐這塊石頭變成食物。"},{"number":4,"text":"耶穌回答說、經上記着說、『人活着不是單靠食物、乃是靠　神口裏所出的一切話。』"}],"total":13},"LUK 4:4":{"label":"路加福音 4:4","verses":[{"number":4,"text":"耶穌回答說、經上記着說、『人活着不是單靠食物、乃是靠　神口裏所出的一切話。』"}],"total":1},"LUK 4:8":{"label":"路加福音 4:8","verses":[{"number":8,"text":"耶穌說、經上記着說、『當拜主你的　神、單要事奉他。』"}],"total":1},"LUK 4:12":{"label":"路加福音 4:12","verses":[{"number":12,"text":"耶穌對他說、經上說、『不可試探主你的　神。』"}],"total":1},"LUK 4:16-21":{"label":"路加福音 4:16–21","verses":[{"number":16,"text":"耶穌來到拿撒勒、就是他長大的地方．在安息日、照他平常的規矩、進了會堂、站起來要念聖經。"},{"number":17,"text":"有人把先知以賽亞的書交給他、他就打開、找到一處寫着說、"},{"number":18,"text":"『主的靈在我身上、因爲他用膏膏我、叫我傳福音給貧窮的人．差遣我報告被擄的得釋放、瞎眼的得看見、叫那受壓制的得自由、"},{"number":19,"text":"報告　神悅納人的禧年。』"}],"total":6},"LUK 4:18":{"label":"路加福音 4:18","verses":[{"number":18,"text":"『主的靈在我身上、因爲他用膏膏我、叫我傳福音給貧窮的人．差遣我報告被擄的得釋放、瞎眼的得看見、叫那受壓制的得自由、"}],"total":1},"LUK 4:18-19":{"label":"路加福音 4:18–19","verses":[{"number":18,"text":"『主的靈在我身上、因爲他用膏膏我、叫我傳福音給貧窮的人．差遣我報告被擄的得釋放、瞎眼的得看見、叫那受壓制的得自由、"},{"number":19,"text":"報告　神悅納人的禧年。』"}],"total":2},"LUK 4:21":{"label":"路加福音 4:21","verses":[{"number":21,"text":"耶穌對他們說、今天這經應驗在你們耳中了。"}],"total":1},"LUK 4:24-30":{"label":"路加福音 4:24–30","verses":[{"number":24,"text":"又說、我實在告訴你們、沒有先知在自己家鄉被人悅納的。"},{"number":25,"text":"我對你們說實話、當以利亞的時候、天閉塞了三年零六個月、徧地有大饑荒、那時、以色列中有許多寡婦．"},{"number":26,"text":"以利亞並沒有奉差往他們一個人那裏去、只奉差往西頓的撒勒法、一個寡婦那裏去。"},{"number":27,"text":"先知以利沙的時候、以色列中有許多長大痲瘋的．但內中除了叙利亞國的乃縵、沒有一個得潔淨的。"}],"total":7},"LUK 4:25-27":{"label":"路加福音 4:25–27","verses":[{"number":25,"text":"我對你們說實話、當以利亞的時候、天閉塞了三年零六個月、徧地有大饑荒、那時、以色列中有許多寡婦．"},{"number":26,"text":"以利亞並沒有奉差往他們一個人那裏去、只奉差往西頓的撒勒法、一個寡婦那裏去。"},{"number":27,"text":"先知以利沙的時候、以色列中有許多長大痲瘋的．但內中除了叙利亞國的乃縵、沒有一個得潔淨的。"}],"total":3},"LUK 7:18-23":{"label":"路加福音 7:18–23","verses":[{"number":18,"text":"約翰的門徒把這些事都告訴約翰。"},{"number":19,"text":"他便叫了兩個門徒來、打發他們到主那裏去、說、那將要來的是你麼。還是我們等候別人呢。"},{"number":20,"text":"那兩個人來到耶穌那裏、說、施洗的約翰打發我們來問你、那將要來的是你麼．還是我們等候別人呢。"},{"number":21,"text":"正當那時候、耶穌治好了許多有疾病的、受災患的、被惡鬼附着的．又開恩叫好些瞎子能看見。"}],"total":6},"LUK 7:20-23":{"label":"路加福音 7:20–23","verses":[{"number":20,"text":"那兩個人來到耶穌那裏、說、施洗的約翰打發我們來問你、那將要來的是你麼．還是我們等候別人呢。"},{"number":21,"text":"正當那時候、耶穌治好了許多有疾病的、受災患的、被惡鬼附着的．又開恩叫好些瞎子能看見。"},{"number":22,"text":"耶穌回答說、你們去把所看見所聽見的事告訴約翰．就是瞎子看見、瘸子行走、長大痲瘋的潔淨、聾子聽見、死人復活、窮人有福音傳給他們。"},{"number":23,"text":"凡不因我跌倒的、就有福了。"}],"total":4},"LUK 7:22":{"label":"路加福音 7:22","verses":[{"number":22,"text":"耶穌回答說、你們去把所看見所聽見的事告訴約翰．就是瞎子看見、瘸子行走、長大痲瘋的潔淨、聾子聽見、死人復活、窮人有福音傳給他們。"}],"total":1},"LUK 7:22-23":{"label":"路加福音 7:22–23","verses":[{"number":22,"text":"耶穌回答說、你們去把所看見所聽見的事告訴約翰．就是瞎子看見、瘸子行走、長大痲瘋的潔淨、聾子聽見、死人復活、窮人有福音傳給他們。"},{"number":23,"text":"凡不因我跌倒的、就有福了。"}],"total":2},"LUK 7:27":{"label":"路加福音 7:27","verses":[{"number":27,"text":"經上記着說、『我要差遣我的使者在你前面、豫備道路。』所說的就是這個人。"}],"total":1},"LUK 9:30-31":{"label":"路加福音 9:30–31","verses":[{"number":30,"text":"忽然有摩西以利亞兩個人、同耶穌說話．"},{"number":31,"text":"他們在榮光裏顯現、談論耶穌去世的事、就是他在耶路撒冷將要成的事。"}],"total":2},"LUK 11:29-32":{"label":"路加福音 11:29–32","verses":[{"number":29,"text":"當衆人聚集的時候、耶穌開講說、這世代是一個邪惡的世代．他們求看神蹟、除了約拿的神蹟以外、再沒有神蹟給他們看。"},{"number":30,"text":"約拿怎樣爲尼尼微人成了神蹟、人子也要照樣爲這世代的人成了神蹟。"},{"number":31,"text":"當審判的時候、南方的女王、要起來定這世代的罪．因爲他從地極而來、要聽所羅門的智慧話．看哪、在這裏有一人比所羅門更大。"},{"number":32,"text":"當審判的時候、尼尼微人要起來定這世代的罪．因爲尼尼微人聽了約拿所傳的、就悔改了．看哪、在這裏有一人比約拿更大。"}],"total":4},"LUK 11:31":{"label":"路加福音 11:31","verses":[{"number":31,"text":"當審判的時候、南方的女王、要起來定這世代的罪．因爲他從地極而來、要聽所羅門的智慧話．看哪、在這裏有一人比所羅門更大。"}],"total":1},"LUK 13:35":{"label":"路加福音 13:35","verses":[{"number":35,"text":"看哪、你們的家成爲荒塲留給你們．我告訴你們、從今以後你們不得再見我、直等到你們說、奉主名來的是應當稱頌的。"}],"total":1},"LUK 19:37-38":{"label":"路加福音 19:37–38","verses":[{"number":37,"text":"將近耶路撒冷、正下橄欖山的時候、衆門徒因所見過的一切異能、都歡樂起來、大聲讚美　神、"},{"number":38,"text":"說、奉主名來的王、是應當稱頌的．在天上有和平、在至高之處有榮光。"}],"total":2},"LUK 19:45-46":{"label":"路加福音 19:45–46","verses":[{"number":45,"text":"耶穌進了殿、趕出裏頭作買賣的人、"},{"number":46,"text":"對他們說、經上說、『我的殿、必作禱告的殿。』你們倒使他成爲賊窩了。"}],"total":2},"LUK 19:46":{"label":"路加福音 19:46","verses":[{"number":46,"text":"對他們說、經上說、『我的殿、必作禱告的殿。』你們倒使他成爲賊窩了。"}],"total":1},"LUK 20:9-18":{"label":"路加福音 20:9–18","verses":[{"number":9,"text":"耶穌就設比喻、對百姓說、有人栽了一個葡萄園、租給園戶、就往外國去住了許久。"},{"number":10,"text":"到了時候、打發一個僕人到園戶那裏去、叫他們把園中當納的果子交給他．園戶竟打了他、叫他空手回去。"},{"number":11,"text":"又打發一個僕人去．他們也打了他、並且凌辱他、叫他空手回去。"},{"number":12,"text":"又打發第三個僕人去．他們也打傷了他、把他推出去了。"}],"total":10},"LUK 20:9-19":{"label":"路加福音 20:9–19","verses":[{"number":9,"text":"耶穌就設比喻、對百姓說、有人栽了一個葡萄園、租給園戶、就往外國去住了許久。"},{"number":10,"text":"到了時候、打發一個僕人到園戶那裏去、叫他們把園中當納的果子交給他．園戶竟打了他、叫他空手回去。"},{"number":11,"text":"又打發一個僕人去．他們也打了他、並且凌辱他、叫他空手回去。"},{"number":12,"text":"又打發第三個僕人去．他們也打傷了他、把他推出去了。"}],"total":11},"LUK 20:17-18":{"label":"路加福音 20:17–18","verses":[{"number":17,"text":"耶穌看着他們說、經上記着、『匠人所棄的石頭、已作了房角的頭塊石頭。』這是甚麼意思呢。"},{"number":18,"text":"凡掉在那石頭上的、必要跌碎．那石頭掉在誰的身上、就要把誰砸得稀爛。"}],"total":2},"LUK 20:37-38":{"label":"路加福音 20:37–38","verses":[{"number":37,"text":"至於死人復活、摩西在荊棘篇上、稱主是亞伯拉罕的　神、以撒的　神、雅各的　神、就指示明白了。"},{"number":38,"text":"神原不是死人的　神、乃是活人的　神．因爲在他那裏、人都是活的。"}],"total":2},"LUK 20:41-44":{"label":"路加福音 20:41–44","verses":[{"number":41,"text":"耶穌對他們說、人怎麼說基督是大衞的子孫呢。"},{"number":42,"text":"詩篇上、大衞自己說、『主對我主說、你坐在我的右邊、"},{"number":43,"text":"等我使你仇敵作你的脚凳。』"},{"number":44,"text":"大衞旣稱他爲主、他怎麼又是大衞的子孫呢。"}],"total":4},"LUK 22:14-20":{"label":"路加福音 22:14–20","verses":[{"number":14,"text":"時候到了、耶穌坐席、使徒也和他同坐。"},{"number":15,"text":"耶穌對他們說、我很願意在受害以先、和你們喫這逾越節的筵席。"},{"number":16,"text":"我告訴你們、我不再喫這筵席、直到成就在　神的國裏。"},{"number":17,"text":"耶穌接過杯來、祝謝了、說、你們拿這個、大家分着喝。"}],"total":7},"LUK 22:15-20":{"label":"路加福音 22:15–20","verses":[{"number":15,"text":"耶穌對他們說、我很願意在受害以先、和你們喫這逾越節的筵席。"},{"number":16,"text":"我告訴你們、我不再喫這筵席、直到成就在　神的國裏。"},{"number":17,"text":"耶穌接過杯來、祝謝了、說、你們拿這個、大家分着喝。"},{"number":18,"text":"我告訴你們、從今以後、我不再喝這葡萄汁、直等　神的國來到。"}],"total":6},"LUK 22:20":{"label":"路加福音 22:20","verses":[{"number":20,"text":"飯後也照樣拿起杯來、說、這杯是用我血所立的新約、是爲你們流出來的。"}],"total":1},"LUK 22:37":{"label":"路加福音 22:37","verses":[{"number":37,"text":"我告訴你們、經上寫着說、『他被列在罪犯之中。』這話必應驗在我身上、因爲那關係我的事、必然成就。"}],"total":1},"LUK 22:69":{"label":"路加福音 22:69","verses":[{"number":69,"text":"從今以後、人子要坐在　神權能的右邊。"}],"total":1},"LUK 23:46":{"label":"路加福音 23:46","verses":[{"number":46,"text":"耶穌大聲喊着說、父阿、我將我的靈魂交在你手裏．說了這話、氣就斷了。"}],"total":1},"LUK 23:49":{"label":"路加福音 23:49","verses":[{"number":49,"text":"還有一切與耶穌熟識的人、和從加利利跟着他來的婦女們、都遠遠的站着、看這些事。"}],"total":1},"LUK 24":{"label":"路加福音 24 章","verses":[{"number":1,"text":"七日的頭一日、黎明的時候、那些婦女帶着所豫備的香料、來到墳墓前。"},{"number":2,"text":"看見石頭已經從墳墓輥開了．"},{"number":3,"text":"他們就進去、只是不見主耶穌的身體。"},{"number":4,"text":"正在猜疑之間、忽然有兩個人站在旁邊．衣服放光。"}],"total":53},"LUK 24:44-47":{"label":"路加福音 24:44–47","verses":[{"number":44,"text":"耶穌對他們說、這就是我從前與你們同在之時、所告訴你們的話、說、摩西的律法、先知的書、和詩篇上所記的、凡指着我的話、都必須應驗。"},{"number":45,"text":"於是耶穌開他們的心竅、使他們能明白聖經．"},{"number":46,"text":"又對他們說、照經上所寫的、基督必受害、第三日從死裏復活．"},{"number":47,"text":"並且人要奉他的名傳悔改赦罪的道、從耶路撒冷起直傳到萬邦。"}],"total":4},"LUK 24:46":{"label":"路加福音 24:46","verses":[{"number":46,"text":"又對他們說、照經上所寫的、基督必受害、第三日從死裏復活．"}],"total":1},"LUK 24:47":{"label":"路加福音 24:47","verses":[{"number":47,"text":"並且人要奉他的名傳悔改赦罪的道、從耶路撒冷起直傳到萬邦。"}],"total":1},"MAL 1:11":{"label":"瑪拉基書 1:11","verses":[{"number":11,"text":"萬軍之耶和華說、從日出之地到日落之處、我的名在外邦中必尊爲大．在各處、人必奉我的名燒香、獻潔淨的供物．因爲我的名在外邦中必尊爲大。"}],"total":1},"MAL 3:1":{"label":"瑪拉基書 3:1","verses":[{"number":1,"text":"萬軍之耶和華說、我要差遣我的使者、在我前面豫備道路．你們所尋求的主、必忽然進入他的殿．立約的使者、就是你們所仰慕的、快要來到。"}],"total":1},"MAL 4:2":{"label":"瑪拉基書 4:2","verses":[{"number":2,"text":"但向你們敬畏我名的人、必有公義的日頭出現、其光線有醫治之能。你們必出來跳躍如圈裏的肥犢。"}],"total":1},"MAL 4:5-6":{"label":"瑪拉基書 4:5–6","verses":[{"number":5,"text":"看哪、耶和華大而可畏之日未到以前、我必差遣先知以利亞到你們那裏去。"},{"number":6,"text":"他必使父親的心轉向兒女、兒女的心轉向父親、免得我來咒詛徧地。"}],"total":2},"MAT 1:3-6":{"label":"馬太福音 1:3–6","verses":[{"number":3,"text":"猶大從他瑪氏生法勒斯和謝拉．法勒斯生希斯崙．希斯崙生亞蘭．"},{"number":4,"text":"亞蘭生亞米拿達．亞米拿達生拿順．拿順生撒門．"},{"number":5,"text":"撒門從喇合氏生波阿斯．波阿斯從路得氏生俄備得．俄備得生耶西．"},{"number":6,"text":"耶西生大衞王。大衞從烏利亞的妻子生所羅門．"}],"total":4},"MAT 1:12-13":{"label":"馬太福音 1:12–13","verses":[{"number":12,"text":"遷到巴比倫之後、耶哥尼雅生撒拉鐵．撒拉鐵生所羅巴伯．"},{"number":13,"text":"所羅巴伯生亞比玉．亞比玉生以利亞敬．以利亞敬生亞所．"}],"total":2},"MAT 1:18-23":{"label":"馬太福音 1:18–23","verses":[{"number":18,"text":"耶穌基督降生的事、記在下面．他母親馬利亞已經許配了約瑟、還沒有迎娶、馬利亞就從聖靈懷了孕。"},{"number":19,"text":"他丈夫約瑟是個義人、不願意明明的羞辱他、想要暗暗的把他休了。"},{"number":20,"text":"正思念這事的時候、有主的使者向他夢中顯現、說、大衞的子孫約瑟、不要怕、只管娶過你的妻子馬利亞來．因他所懷的孕、是從聖靈來的。"},{"number":21,"text":"他將要生一個兒子．你要給他起名叫耶穌．因他要將自己的百姓從罪惡裏救出來。"}],"total":6},"MAT 1:21":{"label":"馬太福音 1:21","verses":[{"number":21,"text":"他將要生一個兒子．你要給他起名叫耶穌．因他要將自己的百姓從罪惡裏救出來。"}],"total":1},"MAT 2:1-6":{"label":"馬太福音 2:1–6","verses":[{"number":1,"text":"當希律王的時候、耶穌生在猶太的伯利恆．有幾個博士從東方來到耶路撒冷、說、"},{"number":2,"text":"那生下來作猶太人之王的在那裏。我們在東方看見他的星、特來拜他。"},{"number":3,"text":"希律王聽見了、就心裏不安．耶路撒冷合城的人、也都不安。"},{"number":4,"text":"他就召齊了祭司長和民間的文士、問他們說、基督當生在何處。"}],"total":6},"MAT 2:1-11":{"label":"馬太福音 2:1–11","verses":[{"number":1,"text":"當希律王的時候、耶穌生在猶太的伯利恆．有幾個博士從東方來到耶路撒冷、說、"},{"number":2,"text":"那生下來作猶太人之王的在那裏。我們在東方看見他的星、特來拜他。"},{"number":3,"text":"希律王聽見了、就心裏不安．耶路撒冷合城的人、也都不安。"},{"number":4,"text":"他就召齊了祭司長和民間的文士、問他們說、基督當生在何處。"}],"total":11},"MAT 2:1-12":{"label":"馬太福音 2:1–12","verses":[{"number":1,"text":"當希律王的時候、耶穌生在猶太的伯利恆．有幾個博士從東方來到耶路撒冷、說、"},{"number":2,"text":"那生下來作猶太人之王的在那裏。我們在東方看見他的星、特來拜他。"},{"number":3,"text":"希律王聽見了、就心裏不安．耶路撒冷合城的人、也都不安。"},{"number":4,"text":"他就召齊了祭司長和民間的文士、問他們說、基督當生在何處。"}],"total":12},"MAT 2:13-15":{"label":"馬太福音 2:13–15","verses":[{"number":13,"text":"他們去後、有主的使者向約瑟夢中顯現、說、起來、帶着小孩子同他母親、逃往埃及、住在那裏、等我吩咐你．因爲希律必尋找小孩子要除滅他。"},{"number":14,"text":"約瑟就起來、夜間帶着小孩子和他母親往埃及去．"},{"number":15,"text":"住在那裏、直到希律死了．這是要應驗主藉先知所說的話、說、『我從埃及召出我的兒子來。』"}],"total":3},"MAT 2:16-18":{"label":"馬太福音 2:16–18","verses":[{"number":16,"text":"希律見自己被博士愚弄、就大大發怒、差人將伯利恆城裏、並四境所有的男孩、照着他向博士仔細查問的時候、凡兩歲以裏的、都殺盡了。"},{"number":17,"text":"這就應了先知耶利米的話、說、"},{"number":18,"text":"『在拉瑪聽見號咷大哭的聲音、是拉結哭他兒女、不肯受安慰、因爲他們都不在了。』"}],"total":3},"MAT 2:23":{"label":"馬太福音 2:23","verses":[{"number":23,"text":"到了一座城、名叫拿撒勒、就住在那裏．這是要應驗先知所說、他將稱爲拿撒勒人的話了。"}],"total":1},"MAT 4:1-11":{"label":"馬太福音 4:1–11","verses":[{"number":1,"text":"當時、耶穌被聖靈引到曠野、受魔鬼的試探。"},{"number":2,"text":"他禁食四十晝夜、後來就餓了。"},{"number":3,"text":"那試探人的進前來、對他說、你若是　神的兒子、可以吩咐這些石頭變成食物。"},{"number":4,"text":"耶穌卻回答說、經上記着說、『人活着、不是單靠食物、乃是靠　神口裏所出的一切話。』"}],"total":11},"MAT 4:4":{"label":"馬太福音 4:4","verses":[{"number":4,"text":"耶穌卻回答說、經上記着說、『人活着、不是單靠食物、乃是靠　神口裏所出的一切話。』"}],"total":1},"MAT 4:7":{"label":"馬太福音 4:7","verses":[{"number":7,"text":"耶穌對他說、經上又記着說、『不可試探主你的　神。』"}],"total":1},"MAT 4:10":{"label":"馬太福音 4:10","verses":[{"number":10,"text":"耶穌說、撒但退去罷。因爲經上記着說、『當拜主你的　神、單要事奉他。』"}],"total":1},"MAT 4:12-17":{"label":"馬太福音 4:12–17","verses":[{"number":12,"text":"耶穌聽見約翰下了監、就退到加利利去．"},{"number":13,"text":"後又離開拿撒勒、往迦百農去、就住在那裏．那地方靠海、在西布倫和拿弗他利的邊界上。"},{"number":14,"text":"這是要應驗先知以賽亞的話、"},{"number":15,"text":"說、『西布倫地、拿弗他利地、就是沿海的路、約但河外、外邦人的加利利地。"}],"total":6},"MAT 4:17":{"label":"馬太福音 4:17","verses":[{"number":17,"text":"從那時候耶穌就傳起道來、說、天國近了、你們應當悔改。"}],"total":1},"MAT 8:17":{"label":"馬太福音 8:17","verses":[{"number":17,"text":"這是要應驗先知以賽亞的話、說、『他代替我們的輭弱、擔當我們的疾病。』"}],"total":1},"MAT 9:36":{"label":"馬太福音 9:36","verses":[{"number":36,"text":"他看見許多的人、就憐憫他們．因爲他們困苦流離、如同羊沒有牧人一般。"}],"total":1},"MAT 11:2-6":{"label":"馬太福音 11:2–6","verses":[{"number":2,"text":"約翰在監裏聽見基督所作的事、就打發兩個門徒去、"},{"number":3,"text":"問他說、那將要來的是你麼、還是我們等候別人呢。"},{"number":4,"text":"耶穌回答說、你們去把所聽見所看見的事告訴約翰．"},{"number":5,"text":"就是瞎子看見、瘸子行走、長大痲瘋的潔淨、聾子聽見、死人復活、窮人有福音傳給他們。"}],"total":5},"MAT 11:4-6":{"label":"馬太福音 11:4–6","verses":[{"number":4,"text":"耶穌回答說、你們去把所聽見所看見的事告訴約翰．"},{"number":5,"text":"就是瞎子看見、瘸子行走、長大痲瘋的潔淨、聾子聽見、死人復活、窮人有福音傳給他們。"},{"number":6,"text":"凡不因我跌倒的、就有福了。"}],"total":3},"MAT 11:10":{"label":"馬太福音 11:10","verses":[{"number":10,"text":"經上記着說、『我要差遣我的使者在你前面、豫備道路。』所說的就是這個人。"}],"total":1},"MAT 11:13-14":{"label":"馬太福音 11:13–14","verses":[{"number":13,"text":"因爲衆先知和律法說豫言、到約翰爲止。"},{"number":14,"text":"你們若肯領受、這人就是那應當來的以利亞。"}],"total":2},"MAT 11:28-30":{"label":"馬太福音 11:28–30","verses":[{"number":28,"text":"凡勞苦擔重擔的人、可以到我這裏來、我就使你們得安息。"},{"number":29,"text":"我心裏柔和謙卑、你們當負我的軛、學我的樣式、這樣、你們心裏就必得享安息。"},{"number":30,"text":"因爲我的軛是容易的、我的擔子是輕省的。"}],"total":3},"MAT 12:6":{"label":"馬太福音 12:6","verses":[{"number":6,"text":"但我告訴你們、在這裏有一人比殿更大。"}],"total":1},"MAT 12:15-21":{"label":"馬太福音 12:15–21","verses":[{"number":15,"text":"耶穌知道了、就離開那裏、有許多人跟着他、他把其中有病的人都治好了。"},{"number":16,"text":"又囑咐他們、不要給他傳名。"},{"number":17,"text":"這是要應驗先知以賽亞的話、說、"},{"number":18,"text":"『看哪、我的僕人、我所揀選、所親愛、心裏所喜悅的、我要將我的靈賜給他、他必將公理傳給外邦。"}],"total":7},"MAT 12:38-41":{"label":"馬太福音 12:38–41","verses":[{"number":38,"text":"當時有幾個文士和法利賽人、對耶穌說、夫子、我們願意你顯個神蹟給我們看。"},{"number":39,"text":"耶穌回答說、一個邪惡淫亂的世代求看神蹟．除了先知約拿的神蹟以外、再沒有神蹟給他們看。"},{"number":40,"text":"約拿三日三夜在大魚肚腹中．人子也要這樣三日三夜在地裏頭。"},{"number":41,"text":"當審判的時候、尼尼微人、要起來定這世代的罪、因爲尼尼微人聽了約拿所傳的、就悔改了．看哪、在這裏有一人比約拿更大。"}],"total":4},"MAT 12:39-40":{"label":"馬太福音 12:39–40","verses":[{"number":39,"text":"耶穌回答說、一個邪惡淫亂的世代求看神蹟．除了先知約拿的神蹟以外、再沒有神蹟給他們看。"},{"number":40,"text":"約拿三日三夜在大魚肚腹中．人子也要這樣三日三夜在地裏頭。"}],"total":2},"MAT 12:39-41":{"label":"馬太福音 12:39–41","verses":[{"number":39,"text":"耶穌回答說、一個邪惡淫亂的世代求看神蹟．除了先知約拿的神蹟以外、再沒有神蹟給他們看。"},{"number":40,"text":"約拿三日三夜在大魚肚腹中．人子也要這樣三日三夜在地裏頭。"},{"number":41,"text":"當審判的時候、尼尼微人、要起來定這世代的罪、因爲尼尼微人聽了約拿所傳的、就悔改了．看哪、在這裏有一人比約拿更大。"}],"total":3},"MAT 12:42":{"label":"馬太福音 12:42","verses":[{"number":42,"text":"當審判的時候、南方的女王、要起來定這世代的罪、因爲他從地極而來、要聽所羅門的智慧話．看哪、在這裏有一人比所羅門更大。"}],"total":1},"MAT 13:13-15":{"label":"馬太福音 13:13–15","verses":[{"number":13,"text":"所以我用比喻對他們講、是因他們看也看不見、聽也聽不見、也不明白。"},{"number":14,"text":"在他們身上、正應了以賽亞的豫言、說、『你們聽是要聽見、卻不明白．看是要看見、卻不曉得．』"},{"number":15,"text":"因爲這百姓油蒙了心、耳朶發沉、眼睛閉着．恐怕眼睛看見、耳朶聽見、心裏明白、回轉過來、我就醫治他們。"}],"total":3},"MAT 13:34-35":{"label":"馬太福音 13:34–35","verses":[{"number":34,"text":"這都是耶穌用比喻對衆人說的話．若不用比喻、就不對他們說甚麼．"},{"number":35,"text":"這是要應驗先知的話、說、『我要開口用比喻、把創世以來所隱藏的事發明出來。』"}],"total":2},"MAT 13:43":{"label":"馬太福音 13:43","verses":[{"number":43,"text":"那時義人在他們父的國裏、要發出光來、像太陽一樣。有耳可聽的、就應當聽。"}],"total":1},"MAT 17:10-13":{"label":"馬太福音 17:10–13","verses":[{"number":10,"text":"門徒問耶穌說、文士爲甚麼說以利亞必須先來。"},{"number":11,"text":"耶穌回答說、以利亞固然先來、並要復興萬事．"},{"number":12,"text":"只是我告訴你們、以利亞已經來了、人卻不認識他、竟任意待他．人子也將要這樣受他們的害。"},{"number":13,"text":"門徒這纔明白耶穌所說的、是指着施洗的約翰。"}],"total":4},"MAT 17:11-12":{"label":"馬太福音 17:11–12","verses":[{"number":11,"text":"耶穌回答說、以利亞固然先來、並要復興萬事．"},{"number":12,"text":"只是我告訴你們、以利亞已經來了、人卻不認識他、竟任意待他．人子也將要這樣受他們的害。"}],"total":2},"MAT 21:1-9":{"label":"馬太福音 21:1–9","verses":[{"number":1,"text":"耶穌和門徒將近耶路撒冷、到了伯法其在橄欖山那裏．"},{"number":2,"text":"耶穌就打發兩個門徒、對他們說、你們往對面村子裏去、必看見一匹驢拴在那裏、還有驢駒同在一處．你們解開牽到我這裏來。"},{"number":3,"text":"若有人對你們說甚麼、你們就說、主要用他．那人必立時讓你們牽來。"},{"number":4,"text":"這事成就、是要應驗先知的話、說、"}],"total":9},"MAT 21:2-3":{"label":"馬太福音 21:2–3","verses":[{"number":2,"text":"耶穌就打發兩個門徒、對他們說、你們往對面村子裏去、必看見一匹驢拴在那裏、還有驢駒同在一處．你們解開牽到我這裏來。"},{"number":3,"text":"若有人對你們說甚麼、你們就說、主要用他．那人必立時讓你們牽來。"}],"total":2},"MAT 21:4-5":{"label":"馬太福音 21:4–5","verses":[{"number":4,"text":"這事成就、是要應驗先知的話、說、"},{"number":5,"text":"『要對錫安的居民說、看哪、你的王來到你這裏、是溫柔的、又騎着驢、就是騎着驢駒子。』"}],"total":2},"MAT 21:16":{"label":"馬太福音 21:16","verses":[{"number":16,"text":"對他說、這些人所說的、你聽見了麼。耶穌說、是的．經上說、『你從嬰孩和喫奶的口中、完全了讚美的話。』你們沒有念過麼。"}],"total":1},"MAT 24:15":{"label":"馬太福音 24:15","verses":[{"number":15,"text":"你們看見先知但以理所說的、那行毀壞可憎的、站在聖地．（讀這經的人須要會意）"}],"total":1},"MAT 24:30":{"label":"馬太福音 24:30","verses":[{"number":30,"text":"那時、人子的兆頭要顯在天上、地上的萬族都要哀哭．他們要看見人子、有能力、有大榮耀、駕着天上的雲降臨。"}],"total":1},"MAT 26:14-16":{"label":"馬太福音 26:14–16","verses":[{"number":14,"text":"當下、十二門徒裏、有一個稱爲加畧人猶大的、去見祭司長、說、"},{"number":15,"text":"我把他交給你們、你們願意給我多少錢。他們就給了他三十塊錢。"},{"number":16,"text":"從那時候、他就找機會、要把耶穌交給他們。"}],"total":3},"MAT 26:30":{"label":"馬太福音 26:30","verses":[{"number":30,"text":"他們唱了詩、就出來往橄欖山去。"}],"total":1},"MAT 26:31-32":{"label":"馬太福音 26:31–32","verses":[{"number":31,"text":"那時、耶穌對他們說、今夜你們爲我的緣故、都要跌倒．因爲經上記着說、『我要擊打牧人、羊就分散了。』"},{"number":32,"text":"但我復活以後、要在你們以先往加利利去。"}],"total":2},"MAT 26:67":{"label":"馬太福音 26:67","verses":[{"number":67,"text":"他們就吐唾沫在他臉上、用拳頭打他．也有用手掌打他的、說、"}],"total":1},"MAT 27:3-5":{"label":"馬太福音 27:3–5","verses":[{"number":3,"text":"這時候、賣耶穌的猶大、看見耶穌已經定了罪、就後悔、把那三十塊錢、拿回來給祭司長和長老說、"},{"number":4,"text":"我賣了無辜之人的血、是有罪了。他們說、那與我們有甚麼相干．你自己承當罷。"},{"number":5,"text":"猶大就把那銀錢丟在殿裏、出去弔死了。"}],"total":3},"MAT 27:3-10":{"label":"馬太福音 27:3–10","verses":[{"number":3,"text":"這時候、賣耶穌的猶大、看見耶穌已經定了罪、就後悔、把那三十塊錢、拿回來給祭司長和長老說、"},{"number":4,"text":"我賣了無辜之人的血、是有罪了。他們說、那與我們有甚麼相干．你自己承當罷。"},{"number":5,"text":"猶大就把那銀錢丟在殿裏、出去弔死了。"},{"number":6,"text":"祭司長拾起銀錢來說、這是血價、不可放在庫裏。"}],"total":8},"MAT 27:39-46":{"label":"馬太福音 27:39–46","verses":[{"number":39,"text":"從那裏經過的人、譏誚他、搖着頭說、"},{"number":40,"text":"你這拆毀聖殿、三日又建造起來的、可以救自己罷．你如果是　神的兒子、就從十字架上下來罷。"},{"number":41,"text":"祭司長和文士並長老、也是這樣戲弄他、說、"},{"number":42,"text":"他救了別人、不能救自己。他是以色列的王、現在可以從十字架上下來、我們就信他。"}],"total":8},"MAT 27:46":{"label":"馬太福音 27:46","verses":[{"number":46,"text":"約在申初、耶穌大聲喊着說、以利、以利、拉馬撒巴各大尼．就是說、我的　神、我的　神、爲甚麼離棄我。"}],"total":1},"MAT 27:60-66":{"label":"馬太福音 27:60–66","verses":[{"number":60,"text":"安放在自己的新墳墓裏、就是他鑿在磐石裏的．他又把大石頭輥到墓門口、就去了。"},{"number":61,"text":"有抹大拉的馬利亞、和那個馬利亞在那裏、對着墳墓坐着。"},{"number":62,"text":"次日、就是豫備日的第二天、祭司長和法利賽人聚集、來見彼拉多、說、"},{"number":63,"text":"大人、我們記得那誘惑人的、還活着的時候、曾說、三日後我要復活。"}],"total":7},"MAT 28:1-6":{"label":"馬太福音 28:1–6","verses":[{"number":1,"text":"安息日將盡、七日的頭一日、天快亮的時候、抹大拉的馬利亞、和那個馬利亞、來看墳墓。"},{"number":2,"text":"忽然地大震動．因爲有主的使者、從天上下來、把石頭輥開、坐在上面。"},{"number":3,"text":"他的像貌如同閃電、衣服潔白如雪。"},{"number":4,"text":"看守的人、就因他嚇得渾身亂戰、甚至和死人一樣。"}],"total":6},"MIC 2:12-13":{"label":"彌迦書 2:12–13","verses":[{"number":12,"text":"雅各家阿、我必要聚集你們、必要招聚以色列剩下的人、安置在一處、如波斯拉的羊、又如草塲上的羊羣．因爲人數衆多。就必大大喧嘩。"},{"number":13,"text":"開路的在他們前面上去．他們直闖過城門、從城門出去．他們的王在前面行、耶和華引導他們。"}],"total":2},"MIC 4:1-5":{"label":"彌迦書 4:1–5","verses":[{"number":1,"text":"末後的日子、耶和華殿的山必堅立、超乎諸山、高舉過於萬嶺．萬民都要流歸這山。"},{"number":2,"text":"必有許多國的民前往、說、來罷、我們登耶和華的山、奔雅各　神的殿．主必將他的道教訓我們、我們也要行他的路．因爲訓誨必出於錫安、耶和華的言語、必出於耶路撒冷。"},{"number":3,"text":"他必在多國的民中施行審判、爲遠方強盛的國斷定是非．他們要將刀打成犂頭、把槍打成鐮刀．這國不舉刀攻擊那國、他們也不再學習戰事。"},{"number":4,"text":"人人都要坐在自己葡萄樹下和無花果樹下、無人驚嚇．這是萬軍之耶和華親口說的。"}],"total":5},"MIC 5:2-5":{"label":"彌迦書 5:2–5","verses":[{"number":2,"text":"伯利恆以法他阿、你在猶大諸城中爲小、將來必有一位從你那裏出來、在以色列中爲我作掌權的．他的根源從亙古、從太初就有。"},{"number":3,"text":"耶和華必將以色列人交付敵人、直等那生產的婦人生下子來．那時掌權者其餘的弟兄必歸到以色列人那裏。"},{"number":4,"text":"他必起來、倚靠耶和華的大能、並耶和華他　神之名的威嚴、牧養他的羊羣．他們要安然居住．因爲他必日見尊大、直到地極。"},{"number":5,"text":"這位必作我們的平安。當亞述人進入我們的地境踐踏宮殿的時候、我們就立起七個牧者、八個首領攻擊他。"}],"total":4},"MIC 7:18-20":{"label":"彌迦書 7:18–20","verses":[{"number":18,"text":"神阿、有何神像你、赦免罪孽、饒恕你產業之餘民的罪過．不永遠懷怒、喜愛施恩。"},{"number":19,"text":"必再憐憫我們、將我們的罪孽踏在脚下、又將我們的一切罪投於深海。"},{"number":20,"text":"你必按古時起誓應許我們列祖的話、向雅各發誠實、向亞伯拉罕施慈愛。"}],"total":3},"MRK 1:2-3":{"label":"馬可福音 1:2–3","verses":[{"number":2,"text":"正如先知以賽亞書上記着說、『看哪、我要差遣我的使者在你前面、豫備道路．"},{"number":3,"text":"在曠野有人聲喊着說、豫備主的道、修直他的路。』"}],"total":2},"MRK 1:2-4":{"label":"馬可福音 1:2–4","verses":[{"number":2,"text":"正如先知以賽亞書上記着說、『看哪、我要差遣我的使者在你前面、豫備道路．"},{"number":3,"text":"在曠野有人聲喊着說、豫備主的道、修直他的路。』"},{"number":4,"text":"照這話、約翰來了、在曠野施洗、傳悔改的洗禮、使罪得赦。"}],"total":3},"MRK 2:19-20":{"label":"馬可福音 2:19–20","verses":[{"number":19,"text":"耶穌對他們說、新郎和陪伴之人同在的時候、陪伴之人豈能禁食呢．新郎還同在、他們不能禁食。"},{"number":20,"text":"但日子將到、新郎要離開他們、那日他們就要禁食。"}],"total":2},"MRK 4:30-32":{"label":"馬可福音 4:30–32","verses":[{"number":30,"text":"又說、　神的國、我們可用甚麼比較呢．可用甚麼比喻表明呢。"},{"number":31,"text":"好像一粒芥菜種、種在地裏的時候、雖比地上的百種都小、"},{"number":32,"text":"但種上以後、就長起來、比各樣的菜都大、又長出大枝來．甚至天上的飛鳥、可以宿在他的蔭下。"}],"total":3},"MRK 4:35-41":{"label":"馬可福音 4:35–41","verses":[{"number":35,"text":"當那天晚上、耶穌對門徒說、我們渡到那邊去罷。"},{"number":36,"text":"門徒離開衆人、耶穌仍在船上、他們就把他一同帶去．也有別的船和他同行。"},{"number":37,"text":"忽然起了暴風、波浪打入船內、甚至船要滿了水。"},{"number":38,"text":"耶穌在船尾上、枕着枕頭睡覺．門徒叫醒了他、說、夫子、我們喪命、你不顧麼。"}],"total":7},"MRK 4:39-40":{"label":"馬可福音 4:39–40","verses":[{"number":39,"text":"耶穌醒了．斥責風、向海說、住了罷、靜了罷．風就止住、大大的平靜了。"},{"number":40,"text":"耶穌對他們說、爲甚麼膽怯．你們還沒有信心麼。"}],"total":2},"MRK 6:34":{"label":"馬可福音 6:34","verses":[{"number":34,"text":"耶穌出來、見有許多的人、就憐憫他們．因爲他們如同羊沒有牧人一般．於是開口教訓他們許多道理。"}],"total":1},"MRK 11:15-17":{"label":"馬可福音 11:15–17","verses":[{"number":15,"text":"他們來到耶路撒冷、耶穌進入聖殿、趕出殿裏作買賣的人、推倒兌換銀錢之人的桌子、和賣鴿子之人的凳子．"},{"number":16,"text":"也不許人拿着器具從殿裏經過。"},{"number":17,"text":"便教訓他們說、經上不是記着說、『我的殿必稱爲萬國禱告的殿』麼．你們倒使他成爲賊窩了。"}],"total":3},"MRK 11:17":{"label":"馬可福音 11:17","verses":[{"number":17,"text":"便教訓他們說、經上不是記着說、『我的殿必稱爲萬國禱告的殿』麼．你們倒使他成爲賊窩了。"}],"total":1},"MRK 12:1-11":{"label":"馬可福音 12:1–11","verses":[{"number":1,"text":"耶穌就用比喻對他們說、有人栽了一個葡萄園、周圍圈上籬笆、挖了一個壓酒池蓋了一座樓、租給園戶、就往外國去了。"},{"number":2,"text":"到了時候、打發一個僕人到園戶那裏、要從園戶收葡萄園的果子。"},{"number":3,"text":"園戶拿住他、打了他、叫他空手回去。"},{"number":4,"text":"再打發一個僕人到他們那裏．他們打傷他的頭、並且凌辱他。"}],"total":11},"MRK 12:1-12":{"label":"馬可福音 12:1–12","verses":[{"number":1,"text":"耶穌就用比喻對他們說、有人栽了一個葡萄園、周圍圈上籬笆、挖了一個壓酒池蓋了一座樓、租給園戶、就往外國去了。"},{"number":2,"text":"到了時候、打發一個僕人到園戶那裏、要從園戶收葡萄園的果子。"},{"number":3,"text":"園戶拿住他、打了他、叫他空手回去。"},{"number":4,"text":"再打發一個僕人到他們那裏．他們打傷他的頭、並且凌辱他。"}],"total":12},"MRK 13:14":{"label":"馬可福音 13:14","verses":[{"number":14,"text":"你們看見那行毀壞可憎的、站在不當站的地方．（讀這經的人、須要會意）那時在猶太的、應當逃到山上．"}],"total":1},"MRK 14:22":{"label":"馬可福音 14:22","verses":[{"number":22,"text":"他們喫的時候、耶穌拿起餅來、祝了福、就擘開遞給他們說、你們拿着喫．這是我的身體。"}],"total":1},"MRK 14:22-24":{"label":"馬可福音 14:22–24","verses":[{"number":22,"text":"他們喫的時候、耶穌拿起餅來、祝了福、就擘開遞給他們說、你們拿着喫．這是我的身體。"},{"number":23,"text":"又拿起杯來、祝謝了、遞給他們．他們都喝了。"},{"number":24,"text":"耶穌說、這是我立約的血、爲多人流出來的。"}],"total":3},"MRK 14:24":{"label":"馬可福音 14:24","verses":[{"number":24,"text":"耶穌說、這是我立約的血、爲多人流出來的。"}],"total":1},"MRK 14:27-28":{"label":"馬可福音 14:27–28","verses":[{"number":27,"text":"耶穌對他們說、你們都要跌倒了．因爲經上記着說、『我要擊打牧人、羊就分散了。』"},{"number":28,"text":"但我復活以後、要在你們以先往加利利去。"}],"total":2},"MRK 14:60-61":{"label":"馬可福音 14:60–61","verses":[{"number":60,"text":"大祭司起來、站在中間、問耶穌說、你甚麼都不回答麼．這些人作見證告你的是甚麼呢。"},{"number":61,"text":"耶穌卻不言語、一句也不回答。大祭司又問他說、你是那當稱頌者的兒子基督不是。"}],"total":2},"MRK 14:61-62":{"label":"馬可福音 14:61–62","verses":[{"number":61,"text":"耶穌卻不言語、一句也不回答。大祭司又問他說、你是那當稱頌者的兒子基督不是。"},{"number":62,"text":"耶穌說、我是．你們必看見人子、坐在那權能者的右邊、駕着天上的雲降臨。"}],"total":2},"MRK 14:62":{"label":"馬可福音 14:62","verses":[{"number":62,"text":"耶穌說、我是．你們必看見人子、坐在那權能者的右邊、駕着天上的雲降臨。"}],"total":1},"MRK 14:65":{"label":"馬可福音 14:65","verses":[{"number":65,"text":"就有人吐唾沫在他臉上、又蒙着他的臉、用拳頭打他、對他說、你說豫言罷．差役接過他來用手掌打他。"}],"total":1},"MRK 15:19":{"label":"馬可福音 15:19","verses":[{"number":19,"text":"又拿一根葦子、打他的頭、吐唾沫在他臉上屈膝拜他。"}],"total":1},"MRK 15:34":{"label":"馬可福音 15:34","verses":[{"number":34,"text":"申初的時候、耶穌大聲喊着說、以羅伊、以羅伊、拉馬撒巴各大尼．繙出來、就是我的　神、我的　神、爲甚麼離棄我。"}],"total":1},"NAM 1:15":{"label":"那鴻書 1:15","verses":[{"number":15,"text":"看哪、有報好信傳平安之人的脚登山、說、猶大阿、可以守你的節期、還你所許的願罷．因爲那惡人不再從你中間經過他已滅絕淨盡了。"}],"total":1},"NUM 9:12":{"label":"民數記 9:12","verses":[{"number":12,"text":"一點不可留到早晨、羊羔的骨頭一根也不可折斷．他們要照逾越節的一切律例而守。"}],"total":1},"NUM 12:6-8":{"label":"民數記 12:6–8","verses":[{"number":6,"text":"耶和華說、你們且聽我的話、你們中間若有先知、我耶和華必在異象中向他顯現、在夢中與他說話。"},{"number":7,"text":"我的僕人摩西不是這樣、他是在我全家盡忠的。"},{"number":8,"text":"我要與他面對面說話、乃是明說、不用謎語、並且他必見我的形像．你們毀謗我的僕人摩西、爲何不懼怕呢。"}],"total":3},"NUM 19:1-10":{"label":"民數記 19:1–10","verses":[{"number":1,"text":"耶和華曉諭摩西、亞倫說、"},{"number":2,"text":"耶和華命定律法中的一條律例、乃是這樣說、你要吩咐以色列人、把一隻沒有殘疾、未曾負軛、純紅的母牛、牽到你這裏來。"},{"number":3,"text":"交給祭司以利亞撒、他必牽到營外、人就把牛宰在他面前。"},{"number":4,"text":"祭司以利亞撒、要用指頭蘸這牛的血、向會幕前面彈七次。"}],"total":10},"NUM 20:1-13":{"label":"民數記 20:1–13","verses":[{"number":1,"text":"正月間以色列全會衆、到了尋的曠野、就住在加低斯、米利暗死在那裏、就葬在那裏。"},{"number":2,"text":"會衆沒有水喝、就聚集攻擊摩西、亞倫。"},{"number":3,"text":"百姓向摩西爭鬧說、我們的弟兄曾死在耶和華面前、我們恨不得與他們同死。"},{"number":4,"text":"你們爲何把耶和華的會衆領到這曠野、使我們和牲畜都死在這裏呢。"}],"total":13},"NUM 21:4-9":{"label":"民數記 21:4–9","verses":[{"number":4,"text":"他們從何珥山起行、往紅海那條路走、要繞過以東地．百姓因這路難行、心中甚是煩躁．"},{"number":5,"text":"就怨讟　神和摩西、說、你們爲甚麼把我們從埃及領出來、使我們死在曠野呢．這裏沒有糧、沒有水、我們的心厭惡這淡薄的食物。"},{"number":6,"text":"於是耶和華使火蛇進入百姓中間、蛇就咬他們、以色列人中死了許多。"},{"number":7,"text":"百姓到摩西那裏說、我們怨讟耶和華和你、有罪了、求你禱告耶和華、叫這些蛇離開我們．於是摩西爲百姓禱告。"}],"total":6},"NUM 24:15-19":{"label":"民數記 24:15–19","verses":[{"number":15,"text":"他就題起詩歌說、比珥的兒子巴蘭說、眼目閉住的人說、"},{"number":16,"text":"得聽　神的言語、明白至高者的意旨、看見全能者的異象、眼目睜開而仆倒的人說、"},{"number":17,"text":"我看他卻不在現時、我望他卻不在近日．有星要出於雅各、有杖要興於以色列、必打破摩押的四角、毀壞擾亂之子。"},{"number":18,"text":"他必得以東爲基業、又得仇敵之地西珥爲產業．以色列必行事勇敢。"}],"total":5},"NUM 27:15-18":{"label":"民數記 27:15–18","verses":[{"number":15,"text":"摩西對耶和華說、"},{"number":16,"text":"願耶和華萬人之靈的　神、立一個人治理會衆。"},{"number":17,"text":"可以在他們面前出入、也可以引導他們、免得耶和華的會衆如同沒有牧人的羊羣一般。"},{"number":18,"text":"耶和華對摩西說、嫩的兒子約書亞、是心中有聖靈的、你將他領來按手在他頭上．"}],"total":4},"PHP 2:9-11":{"label":"腓立比書 2:9–11","verses":[{"number":9,"text":"所以　神將他升爲至高、又賜給他那超乎萬名之上的名、"},{"number":10,"text":"叫一切在天上的、地上的、和地底下的、因耶穌的名、無不屈膝、"},{"number":11,"text":"無不口稱耶穌基督爲主、使榮耀歸與父　神。"}],"total":3},"PRO 8:22-31":{"label":"箴言 8:22–31","verses":[{"number":22,"text":"在耶和華造化的起頭、在太初創造萬物之先、就有了我。"},{"number":23,"text":"從亙古、從太初、未有世界以前、我已被立。"},{"number":24,"text":"沒有深淵、沒有大水的泉源、我已生出。"},{"number":25,"text":"大山未曾奠定、小山未有之先、我已生出。"}],"total":10},"PRO 30:4":{"label":"箴言 30:4","verses":[{"number":4,"text":"誰昇天又降下來．誰聚風在掌握中．誰包水在衣服裏．誰立定地的四極．他名叫甚麼．他兒子名叫甚麼．你知道麼。"}],"total":1},"PSA 2:1-12":{"label":"詩篇 2:1–12","verses":[{"number":1,"text":"外邦爲甚麼爭鬧、萬民爲甚麼謀算虛妄的事。"},{"number":2,"text":"世上的君王一齊起來、臣宰一同商議、要敵擋耶和華、並他的受膏者、"},{"number":3,"text":"說、我們要掙開他們的捆綁、脫去他們的繩索。"},{"number":4,"text":"那坐在天上的必發笑．主必嗤笑他們。"}],"total":12},"PSA 8:1-9":{"label":"詩篇 8:1–9","verses":[{"number":1,"text":"大衞的詩、交與伶長、用迦特樂器。耶和華我們的主阿、你的名在全地何其美．你將你的榮耀彰顯於天。"},{"number":2,"text":"你因敵人的緣故、從嬰孩和喫奶的口中、建立了能力、使仇敵和報仇的、閉口無言。"},{"number":3,"text":"我觀看你指頭所造的天、並你所陳設的月亮星宿、"},{"number":4,"text":"便說、人算甚麼、你竟顧念他．世人算甚麼、你竟眷顧他。"}],"total":9},"PSA 16:8-11":{"label":"詩篇 16:8–11","verses":[{"number":8,"text":"我將耶和華常擺在我面前．因他在我右邊、我便不至搖動。"},{"number":9,"text":"因此我的心歡喜、我的靈快樂．我的肉身也要安然居住。"},{"number":10,"text":"因爲你必不將我的靈魂撇在陰間．也不叫你的聖者見朽壞。"},{"number":11,"text":"你必將生命的道路指示我．在你面前有滿足的喜樂．在你右手中有永遠的福樂。"}],"total":4},"PSA 18:49":{"label":"詩篇 18:49","verses":[{"number":49,"text":"耶和華阿、因此我要在外邦中稱謝你、歌頌你的名．"}],"total":1},"PSA 22:1-31":{"label":"詩篇 22:1–31","verses":[{"number":1,"text":"大衞的詩、交與伶長、調用朝鹿。我的　神、我的　神、爲甚麼離棄我．爲甚麼遠離不救我、不聽我唉哼的言語。"},{"number":2,"text":"我的　神阿、我白日呼求、你不應允．夜間呼求、並不住聲。"},{"number":3,"text":"但你是聖潔的、是用以色列的讚美爲寶座的。"},{"number":4,"text":"我們的祖宗倚靠你．他們倚靠你、你便解救他們。"}],"total":31},"PSA 23:1-6":{"label":"詩篇 23:1–6","verses":[{"number":1,"text":"大衞的詩。耶和華是我的牧者．我必不至缺乏。"},{"number":2,"text":"他使我躺臥在青草地上、領我在可安歇的水邊。"},{"number":3,"text":"他使我的靈魂甦醒、爲自己的名引導我走義路。"},{"number":4,"text":"我雖然行過死蔭的幽谷、也不怕遭害．因爲你與我同在．你的杖、你的竿、都安慰我。"}],"total":6},"PSA 24:7-10":{"label":"詩篇 24:7–10","verses":[{"number":7,"text":"衆城門哪、你們要抬起頭來．永久的門戶、你們要被舉起．那榮耀的王將要進來。"},{"number":8,"text":"榮耀的王是誰呢．就是有力有能的耶和華、在戰塲上有能的耶和華。"},{"number":9,"text":"衆城門哪、你們要抬起頭來．永久的門戶、你們要把頭抬起．那榮耀的王將要進來。"},{"number":10,"text":"榮耀的王是誰呢．萬軍之耶和華、他是榮耀的王。細拉"}],"total":4},"PSA 31:5":{"label":"詩篇 31:5","verses":[{"number":5,"text":"我將我的靈魂交在你手裏．耶和華誠實的　神阿、你救贖了我。"}],"total":1},"PSA 34:8":{"label":"詩篇 34:8","verses":[{"number":8,"text":"你們要嘗嘗主恩的滋味、便知道他是美善．投靠他的人有福了。"}],"total":1},"PSA 34:20":{"label":"詩篇 34:20","verses":[{"number":20,"text":"又保全他一身的骨頭、連一根也不折斷。"}],"total":1},"PSA 35:19":{"label":"詩篇 35:19","verses":[{"number":19,"text":"求你不容那無理與我爲仇的、向我誇耀．不容那無故恨我的、向我擠眼。"}],"total":1},"PSA 38:11-14":{"label":"詩篇 38:11–14","verses":[{"number":11,"text":"我的良朋密友、因我的災病、都躱在旁邊站着．我的親戚本家、也遠遠的站立。"},{"number":12,"text":"那尋索我命的、設下網羅．那想要害我的、口出惡言、終日思想詭計。"},{"number":13,"text":"但我如聾子不聽、像啞吧不開口。"},{"number":14,"text":"我如不聽見的人、口中沒有回話。"}],"total":4},"PSA 40:6-8":{"label":"詩篇 40:6–8","verses":[{"number":6,"text":"祭物和禮物、你不喜悅．你已經開通我的耳朶．燔祭和贖罪祭、非你所要。"},{"number":7,"text":"那時我說、看哪、我來了．我的事在經卷上已經記載了。"},{"number":8,"text":"我的　神阿、我樂意照你的旨意行．你的律法在我心裏。"}],"total":3},"PSA 41:9":{"label":"詩篇 41:9","verses":[{"number":9,"text":"連我知己的朋友、我所倚靠、喫過我飯的、也用脚踢我。"}],"total":1},"PSA 45:6-7":{"label":"詩篇 45:6–7","verses":[{"number":6,"text":"神阿、你的寶座是永永遠遠的．你的國權是正直的。"},{"number":7,"text":"你喜愛公義、恨惡罪惡．所以　神、就是你的　神、用喜樂油膏你、勝過膏你的同伴。"}],"total":2},"PSA 68:18":{"label":"詩篇 68:18","verses":[{"number":18,"text":"你已經升上高天、擄掠仇敵、你在人間、就是在悖逆的人間、受了供獻、叫耶和華　神可以與他們同住。"}],"total":1},"PSA 69:4":{"label":"詩篇 69:4","verses":[{"number":4,"text":"無故恨我的、比我頭髮還多．無理與我爲仇、要把我剪除的、甚爲強盛．我沒有搶奪的、要叫我償還。"}],"total":1},"PSA 69:7-21":{"label":"詩篇 69:7–21","verses":[{"number":7,"text":"因我爲你的緣故受了辱罵、滿面羞愧。"},{"number":8,"text":"我的弟兄看我爲外路人．我的同胞看我爲外邦人。"},{"number":9,"text":"因我爲你的殿心裏焦急、如同火燒．並且辱罵你人的辱罵、都落在我身上。"},{"number":10,"text":"我哭泣、以禁食刻苦我心、這倒算爲我的羞辱。"}],"total":15},"PSA 69:25":{"label":"詩篇 69:25","verses":[{"number":25,"text":"願他們的住處、變爲荒塲．願他們的帳棚、無人居住。"}],"total":1},"PSA 72:1-19":{"label":"詩篇 72:1–19","verses":[{"number":1,"text":"所羅門的詩。　神阿、求你將判斷的權柄賜給王、將公義賜給王的兒子。"},{"number":2,"text":"他要按公義審判你的民、按公平審判你的困苦人。"},{"number":3,"text":"大山小山、都要因公義使民得享平安。"},{"number":4,"text":"他必爲民中的困苦人伸寃、拯救窮乏之輩、壓碎那欺壓人的。"}],"total":19},"PSA 78:1-4":{"label":"詩篇 78:1–4","verses":[{"number":1,"text":"亞薩的訓誨詩。我的民哪、你們要留心聽我的訓誨、側耳聽我口中的話。"},{"number":2,"text":"我要開口說比喻．我要說出古時的謎語．"},{"number":3,"text":"是我們所聽見所知道的、也是我們的祖宗告訴我們的。"},{"number":4,"text":"我們不將這些事向他們的子孫隱瞞．要將耶和華的美德和他的能力、並他奇妙的作爲、述說給後代聽。"}],"total":4},"PSA 78:23-25":{"label":"詩篇 78:23–25","verses":[{"number":23,"text":"他卻吩咐天空、又敞開天上的門、"},{"number":24,"text":"降嗎哪像雨給他們喫、將天上的糧食賜給他們。"},{"number":25,"text":"各人喫大能者的食物．他賜下糧食、使他們飽足。"}],"total":3},"PSA 80:14-19":{"label":"詩篇 80:14–19","verses":[{"number":14,"text":"萬軍之　神阿、求你回轉、從天上垂看、眷顧這葡萄樹、"},{"number":15,"text":"保護你右手所栽的、和你爲自己所堅固的枝子。"},{"number":16,"text":"這樹已經被火焚燒被刀砍伐．他們因你臉上的怒容就滅亡了。"},{"number":17,"text":"願你的手扶持你右邊的人、就是你爲自己所堅固的人子。"}],"total":6},"PSA 82:6":{"label":"詩篇 82:6","verses":[{"number":6,"text":"我曾說、你們是神、都是至高者的兒子。"}],"total":1},"PSA 89:3-4":{"label":"詩篇 89:3–4","verses":[{"number":3,"text":"我與我所揀選的人立了約、向我的僕人大衞起了誓．"},{"number":4,"text":"我要建立你的後裔、直到永遠、要建立你的寶座、直到萬代。"}],"total":2},"PSA 89:19-37":{"label":"詩篇 89:19–37","verses":[{"number":19,"text":"當時你在異象中曉諭你的聖民、說、我已把救助之力、加在那有能者的身上．我高舉那從民中所揀選的。"},{"number":20,"text":"我尋得我的僕人大衞、用我的聖膏膏他。"},{"number":21,"text":"我的手必使他堅立．我的膀臂也必堅固他。"},{"number":22,"text":"仇敵必不勒索他、凶惡之子、也不苦害他。"}],"total":19},"PSA 95:7-11":{"label":"詩篇 95:7–11","verses":[{"number":7,"text":"因爲他是我們的　神．我們是他草塲的羊、是他手下的民。惟願你們今天聽他的話。"},{"number":8,"text":"你們不可硬着心、像當日在米利巴、就是在曠野的瑪撒。"},{"number":9,"text":"那時你們的祖宗試我探我、並且觀看我的作爲。"},{"number":10,"text":"四十年之久、我厭煩那世代、說、這是心裏迷糊的百姓、竟不曉得我的作爲．"}],"total":5},"PSA 97:7":{"label":"詩篇 97:7","verses":[{"number":7,"text":"願一切事奉雕刻的偶像、靠虛無之神自誇的、都蒙羞愧。萬神哪、你們都當拜他。"}],"total":1},"PSA 102:25-27":{"label":"詩篇 102:25–27","verses":[{"number":25,"text":"你起初立了地的根基．天也是你手所造的。"},{"number":26,"text":"天地都要滅沒、你卻要長存．天地都要如外衣漸漸舊了．你要將天地如裏衣更換、天地就都改變了．"},{"number":27,"text":"惟有你永不改變．你的年數沒有窮盡。"}],"total":3},"PSA 104:4":{"label":"詩篇 104:4","verses":[{"number":4,"text":"以風爲使者、以火燄爲僕役．"}],"total":1},"PSA 107:23-30":{"label":"詩篇 107:23–30","verses":[{"number":23,"text":"在海上坐船、在大水中經理事務的．"},{"number":24,"text":"他們看見耶和華的作爲、並他在深水中的奇事。"},{"number":25,"text":"因他一吩咐、狂風就起來、海中的波浪也揚起．"},{"number":26,"text":"他們上到天空、下到海底、他們的心因患難便消化。"}],"total":8},"PSA 109:8":{"label":"詩篇 109:8","verses":[{"number":8,"text":"願他的年日短少．願別人得他的職分。"}],"total":1},"PSA 110:1-3":{"label":"詩篇 110:1–3","verses":[{"number":1,"text":"大衞的詩。耶和華對我主說、你坐在我的右邊、等我使你仇敵作你的脚凳。"},{"number":2,"text":"耶和華必使你從錫安伸出能力的杖來．你要在你仇敵中掌權。"},{"number":3,"text":"當你掌權的日子、你的民要以聖潔的妝飾爲衣、甘心犧牲自己．你的民多如清晨的甘露。"}],"total":3},"PSA 110:4":{"label":"詩篇 110:4","verses":[{"number":4,"text":"耶和華起了誓、決不後悔、說、你是照着麥基洗德的等次、永遠爲祭司。"}],"total":1},"PSA 117:1-2":{"label":"詩篇 117:1–2","verses":[{"number":1,"text":"萬國阿、你們都當讚美耶和華．萬民哪、你們都當頌讚他。"},{"number":2,"text":"因爲他向我們大施慈愛．耶和華的誠實、存到永遠。你們要讚美耶和華。"}],"total":2},"PSA 118:22-24":{"label":"詩篇 118:22–24","verses":[{"number":22,"text":"匠人所棄的石頭、已成了房角的頭塊石頭。"},{"number":23,"text":"這是耶和華所作的、在我們眼中看爲希奇。"},{"number":24,"text":"這是耶和華所定的日子．我們在其中要高興歡喜。"}],"total":3},"PSA 118:25-26":{"label":"詩篇 118:25–26","verses":[{"number":25,"text":"耶和華阿、求你拯救．耶和華阿、求你使我們亨通。"},{"number":26,"text":"奉耶和華名來的、是應當稱頌的．我們從耶和華的殿中、爲你們祝福。"}],"total":2},"PSA 130:7-8":{"label":"詩篇 130:7–8","verses":[{"number":7,"text":"以色列阿、你當仰望耶和華．因他有慈愛、有豐盛的救恩。"},{"number":8,"text":"他必救贖以色列脫離一切的罪孽。"}],"total":2},"PSA 132:11-18":{"label":"詩篇 132:11–18","verses":[{"number":11,"text":"耶和華向大衞憑誠實起了誓、必不反覆、說、我要使你所生的坐在你的寶座上。"},{"number":12,"text":"你的衆子若守我的約、和我所教訓他們的法度、他們的子孫、必永遠坐在你的寶座上。"},{"number":13,"text":"因爲耶和華揀選了錫安、願意當作自己的居所、"},{"number":14,"text":"說、這是我永遠安息之所．我要住在這裏．因爲是我所願意的。"}],"total":8},"PSA 146:7-9":{"label":"詩篇 146:7–9","verses":[{"number":7,"text":"他爲受屈的伸寃、賜食物與飢餓的。耶和華釋放被囚的．"},{"number":8,"text":"耶和華開了瞎子的眼睛．耶和華扶起被壓下的人．耶和華喜愛義人．"},{"number":9,"text":"耶和華保護寄居的、扶持孤兒和寡婦．卻使惡人的道路彎曲。"}],"total":3},"REV 1:5-6":{"label":"啟示錄 1:5–6","verses":[{"number":5,"text":"並那誠實作見證的、從死裏首先復活、爲世上君王元首的耶穌基督．有恩惠平安歸與你們。他愛我們、用自己的血使我們脫離罪惡．"},{"number":6,"text":"又使我們成爲國民、作他父　神的祭司．但願榮耀權能歸給他、直到永永遠遠。阿們。"}],"total":2},"REV 1:7":{"label":"啟示錄 1:7","verses":[{"number":7,"text":"看哪、他駕雲降臨．衆目要看見他、連刺他的人也要看見他．地上的萬族都要因他哀哭。這話是眞實的。阿們。"}],"total":1},"REV 1:13":{"label":"啟示錄 1:13","verses":[{"number":13,"text":"燈臺中間、有一位好像人子、身穿長衣、直垂到脚、胸間束着金帶。"}],"total":1},"REV 2:26-27":{"label":"啟示錄 2:26–27","verses":[{"number":26,"text":"那得勝又遵守我命令到底的、我要賜給他權柄制伏列國．"},{"number":27,"text":"他必用鐵杖轄管他們、將他們如同窰戶的瓦器打得粉碎．像我從我父領受的權柄一樣．"}],"total":2},"REV 3:7":{"label":"啟示錄 3:7","verses":[{"number":7,"text":"你要寫信給非拉鐵非教會的使者、說、那聖潔、眞實、拿着大衞的鑰匙、開了就沒有人能關、關了就沒有人能開的、說、"}],"total":1},"REV 5:5":{"label":"啟示錄 5:5","verses":[{"number":5,"text":"長老中有一位對我說、不要哭．看哪、猶大支派中的獅子、大衞的根、他已得勝、能以展開那書卷、揭開那七印。"}],"total":1},"REV 5:5-6":{"label":"啟示錄 5:5–6","verses":[{"number":5,"text":"長老中有一位對我說、不要哭．看哪、猶大支派中的獅子、大衞的根、他已得勝、能以展開那書卷、揭開那七印。"},{"number":6,"text":"我又看見寶座與四活物並長老之中、有羔羊站立、像是被殺過的、有七角七眼、就是　神的七靈、奉差遣往普天下去的。"}],"total":2},"REV 7:16-17":{"label":"啟示錄 7:16–17","verses":[{"number":16,"text":"他們不再饑、不再渴．日頭和炎熱、也必不傷害他們．"},{"number":17,"text":"因爲寶座中的羔羊必牧養他們、領他們到生命水的泉源．　神也必擦去他們一切的眼淚。"}],"total":2},"REV 11:15":{"label":"啟示錄 11:15","verses":[{"number":15,"text":"第七位天使吹號、天上就有大聲音說、世上的國、成了我主和主基督的國．他要作王、直到永永遠遠。"}],"total":1},"REV 12:9":{"label":"啟示錄 12:9","verses":[{"number":9,"text":"大龍就是那古蛇、名叫魔鬼、又叫撒但、是迷惑普天下的．他被摔在地上、他的使者也一同被摔下去。"}],"total":1},"REV 14:14-20":{"label":"啟示錄 14:14–20","verses":[{"number":14,"text":"我又觀看、見有一片白雲、雲上坐着一位好像人子、頭上戴着金冠冕、手裏拿着快鐮刀。"},{"number":15,"text":"又有一位天使從殿中出來、向那坐在雲上的大聲喊着說、伸出你的鐮刀來收割．因爲收割的時候已經到了、地上的莊稼已經熟透了。"},{"number":16,"text":"那坐在雲上的、就把鐮刀扔在地上．地上的莊稼就被收割了。"},{"number":17,"text":"又有一位天使從天上的殿中出來、他也拿着快鐮刀。"}],"total":7},"REV 19:7-9":{"label":"啟示錄 19:7–9","verses":[{"number":7,"text":"我們要歡喜快樂、將榮耀歸給他．因爲羔羊婚娶的時候到了、新婦也自己豫備好了。"},{"number":8,"text":"就蒙恩得穿光明潔白的細麻衣、這細麻衣就是聖徒所行的義。"},{"number":9,"text":"天使吩咐我說、你要寫上、凡被請赴羔羊之婚筵的有福了。又對我說、這是　神眞實的話。"}],"total":3},"REV 19:11-16":{"label":"啟示錄 19:11–16","verses":[{"number":11,"text":"我觀看、見天開了．有一匹白馬．騎在馬上的、稱爲誠信眞實．他審判爭戰都按着公義。"},{"number":12,"text":"他的眼睛如火燄、他頭上戴着許多冠冕．又有寫着的名字、除了他自己沒有人知道。"},{"number":13,"text":"他穿着濺了血的衣服．他的名稱爲　神之道。"},{"number":14,"text":"在天上的衆軍、騎着白馬、穿着細麻衣、又白又潔、跟隨他。"}],"total":6},"REV 21:1-5":{"label":"啟示錄 21:1–5","verses":[{"number":1,"text":"我又看見一個新天新地．因爲先前的天地已經過去了．海也不再有了。"},{"number":2,"text":"我又看見聖城新耶路撒冷由　神那裏從天而降、豫備好了、就如新婦妝飾整齊、等候丈夫。"},{"number":3,"text":"我聽見有大聲音從寶座出來說、看哪、　神的帳幕在人間．他要與人同住、他們要作他的子民、　神要親自與他們同在、作他們的　神．"},{"number":4,"text":"神要擦去他們一切的眼淚．不再有死亡、也不再有悲哀、哭號、疼痛、因爲以前的事都過去了。"}],"total":5},"REV 21:3":{"label":"啟示錄 21:3","verses":[{"number":3,"text":"我聽見有大聲音從寶座出來說、看哪、　神的帳幕在人間．他要與人同住、他們要作他的子民、　神要親自與他們同在、作他們的　神．"}],"total":1},"REV 21:4":{"label":"啟示錄 21:4","verses":[{"number":4,"text":"神要擦去他們一切的眼淚．不再有死亡、也不再有悲哀、哭號、疼痛、因爲以前的事都過去了。"}],"total":1},"REV 21:23-26":{"label":"啟示錄 21:23–26","verses":[{"number":23,"text":"那城內又不用日月光照．因有　神的榮耀光照．又有羔羊爲城的燈。"},{"number":24,"text":"列國要在城的光裏行走．地上的君王必將自己的榮耀歸與那城。"},{"number":25,"text":"城門白晝總不關閉．在那裏原沒有黑夜。"},{"number":26,"text":"人必將列國的榮耀尊貴歸與那城。"}],"total":4},"REV 21:24-26":{"label":"啟示錄 21:24–26","verses":[{"number":24,"text":"列國要在城的光裏行走．地上的君王必將自己的榮耀歸與那城。"},{"number":25,"text":"城門白晝總不關閉．在那裏原沒有黑夜。"},{"number":26,"text":"人必將列國的榮耀尊貴歸與那城。"}],"total":3},"REV 22:1-2":{"label":"啟示錄 22:1–2","verses":[{"number":1,"text":"天使又指示我在城內街道當中一道生命水的河、明亮如水晶、從　神和羔羊的寶座流出來。"},{"number":2,"text":"在河這邊與那邊有生命樹、結十二樣果子、每月都結果子．樹上的葉子乃爲醫治萬民。"}],"total":2},"REV 22:1-3":{"label":"啟示錄 22:1–3","verses":[{"number":1,"text":"天使又指示我在城內街道當中一道生命水的河、明亮如水晶、從　神和羔羊的寶座流出來。"},{"number":2,"text":"在河這邊與那邊有生命樹、結十二樣果子、每月都結果子．樹上的葉子乃爲醫治萬民。"},{"number":3,"text":"以後再沒有咒詛．在城裏有　神和羔羊的寶座．他的僕人都要事奉他．"}],"total":3},"REV 22:12":{"label":"啟示錄 22:12","verses":[{"number":12,"text":"看哪、我必快來．賞罰在我、要照各人所行的報應他。"}],"total":1},"REV 22:16":{"label":"啟示錄 22:16","verses":[{"number":16,"text":"我耶穌差遣我的使者爲衆教會將這些事向你們證明。我是大衞的根、又是他的後裔．我是明亮的晨星。"}],"total":1},"ROM 1:17":{"label":"羅馬書 1:17","verses":[{"number":17,"text":"因爲　神的義、正在這福音上顯明出來．這義是本於信、以致於信．如經上所記、『義人必因信得生。』"}],"total":1},"ROM 3:24-26":{"label":"羅馬書 3:24–26","verses":[{"number":24,"text":"如今卻蒙　神的恩典、因基督耶穌的救贖、就白白的稱義。"},{"number":25,"text":"神設立耶穌作挽回祭、是憑着耶穌的血、藉着人的信、要顯明　神的義．因爲他用忍耐的心、寬容人先時所犯的罪．"},{"number":26,"text":"好在今時顯明他的義、使人知道他自己爲義、也稱信耶穌的人爲義。"}],"total":3},"ROM 4:1-25":{"label":"羅馬書 4:1–25","verses":[{"number":1,"text":"如此說來、我們的祖宗亞伯拉罕、憑着肉體得了甚麼呢。"},{"number":2,"text":"倘若亞伯拉罕是因行爲稱義、就有可誇的．只是在　神面前並無可誇。"},{"number":3,"text":"經上說甚麼呢．說、『亞伯拉罕信　神、這就算爲他的義。』"},{"number":4,"text":"作工的得工價、不算恩典、乃是該得的、"}],"total":25},"ROM 5:12-21":{"label":"羅馬書 5:12–21","verses":[{"number":12,"text":"這就如罪是從一人入了世界、死又是從罪來的、於是死就臨到衆人、因爲衆人都犯了罪。"},{"number":13,"text":"沒有律法之先、罪已經在世上．但沒有律法、罪也不算罪。"},{"number":14,"text":"然而從亞當到摩西死就作了王、連那些不與亞當犯一樣罪過的、也在他的權下．亞當乃是那以後要來之人的豫像。"},{"number":15,"text":"只是過犯不如恩賜．若因一人的過犯、衆人都死了、何况　神的恩典、與那因耶穌基督一人恩典中的賞賜、豈不更加倍的臨到衆人麼。"}],"total":10},"ROM 8:11":{"label":"羅馬書 8:11","verses":[{"number":11,"text":"然而叫耶穌從死裏復活者的靈、若住在你們心裏、那叫基督耶穌從死裏復活的、也必藉着住在你們心裏的聖靈、使你們必死的身體又活過來。"}],"total":1},"ROM 8:32":{"label":"羅馬書 8:32","verses":[{"number":32,"text":"神旣不愛惜自己的兒子爲我們衆人捨了、豈不也把萬物和他一同白白的賜給我們麼。"}],"total":1},"ROM 8:33-34":{"label":"羅馬書 8:33–34","verses":[{"number":33,"text":"誰能控告　神所揀選的人呢．有　神稱他們爲義了。"},{"number":34,"text":"誰能定他們的罪呢．有基督耶穌已經死了、而且從死裏復活、現今在　神的右邊、也替我們祈求。"}],"total":2},"ROM 9:24-26":{"label":"羅馬書 9:24–26","verses":[{"number":24,"text":"這器皿就是我們被　神所召的、不但是從猶太人中、也是從外邦人中、這有甚麼不可呢。"},{"number":25,"text":"就像　神在何西阿書上說、『那本來不是我子民的、我要稱爲我的子民．本來不是蒙愛的、我要稱爲蒙愛的。"},{"number":26,"text":"從前在甚麼地方對他們說、你們不是我的子民、將來就在那裏稱他們爲永生　神的兒子。』"}],"total":3},"ROM 9:30-33":{"label":"羅馬書 9:30–33","verses":[{"number":30,"text":"這樣、我們可說甚麼呢．那本來不追求義的外邦人、反得了義、就是因信而得的義．"},{"number":31,"text":"但以色列人追求律法的義、反得不着律法的義。"},{"number":32,"text":"這是甚麼緣故呢．是因爲他們不憑着信心求、只憑着行爲求．他們正跌在那絆脚石上．"},{"number":33,"text":"就如經上所記、『我在錫安放一塊絆脚的石頭、跌人的磐石．信靠他的人必不至於羞愧。』"}],"total":4},"ROM 10:5-13":{"label":"羅馬書 10:5–13","verses":[{"number":5,"text":"摩西寫着說、『人若行那出於律法的義、就必因此活着。』"},{"number":6,"text":"惟有出於信心的義如此說、『你不要心裏說、誰要升到天上去呢．就是要領下基督來．"},{"number":7,"text":"誰要下到陰間去呢．就是要領基督從死裏上來。』"},{"number":8,"text":"他到底怎麼說呢．他說、『這道離你不遠、正在你口裏、在你心裏。』就是我們所傳信主的道。"}],"total":9},"ROM 10:9-13":{"label":"羅馬書 10:9–13","verses":[{"number":9,"text":"你若口裏認耶穌爲主、心裏信　神叫他從死裏復活、就必得救．"},{"number":10,"text":"因爲人心裏相信、就可以稱義．口裏承認、就可以得救。"},{"number":11,"text":"經上說、『凡信他的人、必不至於羞愧。』"},{"number":12,"text":"猶太人和希利尼人、並沒有分別．因爲衆人同有一位主、他也厚待一切求告他的人．"}],"total":5},"ROM 10:11":{"label":"羅馬書 10:11","verses":[{"number":11,"text":"經上說、『凡信他的人、必不至於羞愧。』"}],"total":1},"ROM 10:14-17":{"label":"羅馬書 10:14–17","verses":[{"number":14,"text":"然而人未曾信他、怎能求他呢．未曾聽見他、怎能信他呢．沒有傳道的、怎能聽見呢。"},{"number":15,"text":"若沒有奉差遣、怎能傳道呢．如經上所記、『報福音傳喜信的人、他們的脚蹤何等佳美。』"},{"number":16,"text":"只是人沒有都聽從福音．因爲以賽亞說、『主阿、我們所傳的有誰信呢。』"},{"number":17,"text":"可見信道是從聽道來的、聽道是從基督的話來的。"}],"total":4},"ROM 10:15":{"label":"羅馬書 10:15","verses":[{"number":15,"text":"若沒有奉差遣、怎能傳道呢．如經上所記、『報福音傳喜信的人、他們的脚蹤何等佳美。』"}],"total":1},"ROM 11:25-29":{"label":"羅馬書 11:25–29","verses":[{"number":25,"text":"弟兄們、我不願意你們不知道這奧祕、（恐怕你們自以爲聰明）就是以色列人有幾分是硬心的、等到外邦人的數目添滿了．"},{"number":26,"text":"於是以色列全家都要得救、如經上所記、『必有一位救主、從錫安出來、要消除雅各家的一切罪惡。』"},{"number":27,"text":"又說、『我除去他們罪的時候、這就是我與他們所立的約。』"},{"number":28,"text":"就着福音說、他們爲你們的緣故是仇敵．就着揀選說、他們爲列祖的緣故是蒙愛的。"}],"total":5},"ROM 14:11":{"label":"羅馬書 14:11","verses":[{"number":11,"text":"經上寫着、『主說、我憑着我的永生起誓、萬膝必向我跪拜、萬口必向我承認。』"}],"total":1},"ROM 15:3":{"label":"羅馬書 15:3","verses":[{"number":3,"text":"因爲基督也不求自己的喜悅、如經上所記、『辱罵你人的辱罵、都落在我身上。』"}],"total":1},"ROM 15:8-12":{"label":"羅馬書 15:8–12","verses":[{"number":8,"text":"我說、基督是爲　神眞理作了受割禮人的執事、要證實所應許列祖的話。"},{"number":9,"text":"並叫外邦人、因他的憐憫、榮耀　神．如經上所記、『因此我要在外邦中稱讚你、歌頌你的名。』"},{"number":10,"text":"又說、『你們外邦人、當與主的百姓一同歡樂。』"},{"number":11,"text":"又說、『外邦阿、你們當讚美主．萬民哪、你們都當頌讚他。』"}],"total":5},"ROM 15:10":{"label":"羅馬書 15:10","verses":[{"number":10,"text":"又說、『你們外邦人、當與主的百姓一同歡樂。』"}],"total":1},"ROM 15:12":{"label":"羅馬書 15:12","verses":[{"number":12,"text":"又有以賽亞說、『將來有耶西的根、就是那興起來要治理外邦的．外邦人要仰望他。』"}],"total":1},"ROM 15:21":{"label":"羅馬書 15:21","verses":[{"number":21,"text":"就如經上所記、『未曾聞知他信息的、將要看見．未曾聽過的、將要明白。』"}],"total":1},"ROM 16:20":{"label":"羅馬書 16:20","verses":[{"number":20,"text":"賜平安的　神、快要將撒但踐踏在你們脚下。願我主耶穌基督的恩、常和你們同在。"}],"total":1},"RUT 2:20":{"label":"路得記 2:20","verses":[{"number":20,"text":"拿俄米對兒婦說、願那人蒙耶和華賜福、因爲他不斷的恩待活人死人．拿俄米又說、那是我們本族的人、是一個至近的親屬。"}],"total":1},"RUT 4:1-17":{"label":"路得記 4:1–17","verses":[{"number":1,"text":"波阿斯到了城門、坐在那裏、恰巧波阿斯所說的那至近的親屬經過．波阿斯說、某人哪、你來坐在這裏、他就來坐下．"},{"number":2,"text":"波阿斯又從本城的長老中揀選了十人、對他們說、請你們坐在這裏、他們就都坐下．"},{"number":3,"text":"波阿斯對那至近的親屬說、從摩押地回來的拿俄米、現在要賣我們族兄以利米勒的那塊地．"},{"number":4,"text":"我想當贖那塊地的是你、其次是我、以外再沒有別人了、你可以在這裏的人面前、和我本國的長老面前說明、你若肯贖就贖、若不肯贖就告訴我．那人回答說、我肯贖。"}],"total":17},"SNG 2:16":{"label":"雅歌 2:16","verses":[{"number":16,"text":"良人屬我、我也屬他．他在百合花中牧放羣羊。"}],"total":1},"SNG 8:6-7":{"label":"雅歌 8:6–7","verses":[{"number":6,"text":"求你將我放在你心上如印記、帶在你臂上如戳記．因爲愛情如死之堅強．嫉恨如陰間之殘忍．所發的電光、是火燄的電光、是耶和華的烈燄。"},{"number":7,"text":"愛情、衆水不能息滅、大水也不能淹沒．若有人拿家中所有的財寶要換愛情、就全被藐視。"}],"total":2},"TIT 2:14":{"label":"提多書 2:14","verses":[{"number":14,"text":"他爲我們捨了自己、要贖我們脫離一切罪惡、又潔淨我們、特作自己的子民、熱心爲善。"}],"total":1},"TIT 3:5-6":{"label":"提多書 3:5–6","verses":[{"number":5,"text":"他便救了我們、並不是因我們自己所行的義、乃是照他的憐憫、藉着重生的洗、和聖靈的更新。"},{"number":6,"text":"聖靈就是　神藉着耶穌基督我們救主、厚厚澆灌在我們身上的．"}],"total":2},"ZEC 3:1-10":{"label":"撒迦利亞書 3:1–10","verses":[{"number":1,"text":"天使又指給我看、大祭司約書亞站在耶和華的使者面前、撒但也站在約書亞的右邊、與他作對。"},{"number":2,"text":"耶和華向撒但說、撒但哪、耶和華責備你、就是揀選耶路撒冷的耶和華責備你．這不是從火中抽出來的一根柴麼。"},{"number":3,"text":"約書亞穿着汚穢的衣服、站在使者面前。"},{"number":4,"text":"使者吩咐站在面前的說、你們要脫去他汚穢的衣服。又對約書亞說、我使你脫離罪孽、要給你穿上華美的衣服。"}],"total":10},"ZEC 6:9-15":{"label":"撒迦利亞書 6:9–15","verses":[{"number":9,"text":"耶和華的話臨到我說、"},{"number":10,"text":"你要從被擄之人中取黑玳、多比雅、耶大雅的金銀．這三人是從巴比倫來到西番雅的兒子約西亞的家裏．當日你要進他的家、"},{"number":11,"text":"取這金銀作冠冕、戴在約撒答的兒子大祭司約書亞的頭上、"},{"number":12,"text":"對他說、萬軍之耶和華如此說、看哪、那名稱爲大衞苗裔的、他要在本處長起來．並要建造耶和華的殿。"}],"total":7},"ZEC 9:9-10":{"label":"撒迦利亞書 9:9–10","verses":[{"number":9,"text":"錫安的民哪、應當大大喜樂．耶路撒冷的民哪、應當歡呼．看哪、你的王來到你這裏．他是公義的、並且施行拯救、謙謙和和的騎着驢、就是騎着驢的駒子。"},{"number":10,"text":"我必除滅以法蓮的戰車、和耶路撒冷的戰馬．爭戰的弓也必除滅．他必向列國講和平．他的權柄必從這海管到那海、從大河管到地極。"}],"total":2},"ZEC 9:11-12":{"label":"撒迦利亞書 9:11–12","verses":[{"number":11,"text":"錫安哪、我因與你立約的血、將你中間被擄而囚的人、從無水的坑中釋放出來。"},{"number":12,"text":"你們被囚而有指望的人、都要轉回保障．我今日說明、我必加倍賜福給你們。"}],"total":2},"ZEC 11:4-14":{"label":"撒迦利亞書 11:4–14","verses":[{"number":4,"text":"耶和華我的　神如此說、你撒迦利亞要牧養這將宰的羣羊．"},{"number":5,"text":"買他們的宰了他們、以自己爲無罪．賣他們的說、耶和華是應當稱頌的、因我成爲富足。牧養他們的、並不憐恤他們。"},{"number":6,"text":"耶和華說、我不再憐恤這地的居民．必將這民交給各人的鄰舍、和他們王的手中。他們必毀滅這地、我也不救這民脫離他們的手。"},{"number":7,"text":"於是我牧養這將宰的羣羊、就是羣中最困苦的羊。我拿着兩根杖．一根我稱爲榮美、一根我稱爲聯索．這樣、我牧養了羣羊。"}],"total":11},"ZEC 12:10-14":{"label":"撒迦利亞書 12:10–14","verses":[{"number":10,"text":"我必將那施恩叫人懇求的靈、澆灌大衞家、和耶路撒冷的居民．他們必仰望我、就是他們所扎的．必爲我悲哀、如喪獨生子、又爲我愁苦、如喪長子。"},{"number":11,"text":"那日耶路撒冷必有大大的悲哀、如米吉多平原之哈達臨門的悲哀。"},{"number":12,"text":"境內、一家一家的、都必悲哀．大衞家、男的獨在一處、女的獨在一處．拿單家、男的獨在一處、女的獨在一處．"},{"number":13,"text":"利未家、男的獨在一處、女的獨在一處．示每家、男的獨在一處、女的獨在一處．"}],"total":5},"ZEC 13:1":{"label":"撒迦利亞書 13:1","verses":[{"number":1,"text":"那日必給大衞家和耶路撒冷的居民、開一個泉源、洗除罪惡與汚穢。"}],"total":1},"ZEC 13:6":{"label":"撒迦利亞書 13:6","verses":[{"number":6,"text":"必有人問他說、你兩臂中間是甚麼傷呢．他必回答說、這是我在親友家中所受的傷。"}],"total":1},"ZEC 13:7":{"label":"撒迦利亞書 13:7","verses":[{"number":7,"text":"萬軍之耶和華說、刀劍哪、應當興起、攻擊我的牧人、和我的同伴．擊打牧人、羊就分散．我必反手加在微小者的身上。"}],"total":1},"ZEC 14:3-9":{"label":"撒迦利亞書 14:3–9","verses":[{"number":3,"text":"那時、耶和華必出去與那些國爭戰、好像從前爭戰一樣。"},{"number":4,"text":"那日、他的脚必站在耶路撒冷前面朝東的橄欖山上．這山必從中間分裂、自東至西、成爲極大的谷．山的一半向北挪移、一半向南挪移。"},{"number":5,"text":"你們要從我山的谷中逃跑、因爲山谷必延到亞薩．你們逃跑、必如猶大王烏西雅年間的人逃避大地震一樣．耶和華我的　神必降臨、有一切聖者同來。"},{"number":6,"text":"那日、必沒有光．三光必退縮。"}],"total":7},"ZEP 3:14-20":{"label":"西番雅書 3:14–20","verses":[{"number":14,"text":"錫安的民哪、應當歌唱．以色列阿、應當歡呼。耶路撒冷的民哪、應當滿心歡喜快樂。"},{"number":15,"text":"耶和華已經除去你的刑罰、趕出你的仇敵．以色列的王耶和華在你中間、你必不再懼怕災禍。"},{"number":16,"text":"當那日、必有話向耶路撒冷說、不要懼怕。錫安哪、不要手輭。"},{"number":17,"text":"耶和華你的　神、是施行拯救、大有能力的主、他在你中間必因你歡欣喜樂、默然愛你、且因你喜樂而歡呼。"}],"total":7}}};
